window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0166", [{"word":"persevere","ipa_uk":"/pəˈsɪə.vɪə/","ipa_us":"/pərˈsɪv.ɚ/","definition_zh":"坚持；面对困难仍不放弃；在漫长过程中持续投入；坚守立场或信仰","definition_en":"to keep doing something in a steady way even when it is hard, slow or discouraging","core_image":"一条长长的上坡石阶，雨越下越大，走路的人一步接一步往上，始终没有停下","scene":"哪怕实验记录被退回了三次，她仍然每天清晨回到同一张桌子前，把流程再走一遍。She perseveres with the experiment long after her first plan failed.","sceneCN":"这里 persevere 指「面对阻力仍持续做同一件事」（第 1 个义项：顶着挫败继续行动）；句意为最早的方案失败很久之后，她仍坚持做这项实验。图中可辨识物件：湿透的石阶、被雨打湿的记录纸、一直向前的脚印。","pos":[{"tag":"vi.","zh":"坚持；不屈不挠地继续（与 in、with、at 等介词搭配）"}],"collocations":[{"phrase":"persevere with a task","zh":"坚持做一项任务"},{"phrase":"persevere in the face of failure","zh":"在失败面前仍不放弃"},{"phrase":"persevere through hardship","zh":"熬过艰难时期仍继续"},{"phrase":"persevere against opposition","zh":"顶着反对坚持下去"},{"phrase":"persevere in one's studies","zh":"在学业上坚持不懈"},{"phrase":"persevere to the end","zh":"坚持到底"}],"forms":[{"label":"三单（he/she/it）","form":"perseveres"},{"label":"过去式","form":"persevered"},{"label":"过去分词","form":"persevered"},{"label":"现在分词","form":"persevering"},{"label":"名词（坚持）","form":"perseverance"},{"label":"形容词（有毅力的）","form":"persevering"}],"derivatives":[{"word":"perseverance","pos":"n.","zh":"由动词加表示状态的名词后缀构成，语义由「持续做下去」转为「持续做下去的状态与品质」"},{"word":"persevering","pos":"adj.","zh":"由动词加表示性质的形容词后缀构成，语义由「坚持下去」转为「具有坚持特征的」"},{"word":"perseveringly","pos":"adv.","zh":"在形容词后加副词后缀构成，语义由「有毅力的」转为「以有毅力的方式」"},{"word":"perseverant","pos":"adj.","zh":"借拉丁语现在分词形式进入英语的形容词，语义与「坚持不懈的」相同，现代用法较少"}],"senses":[{"no":"01","title":"Keep acting despite resistance","titleCN":"面对阻力仍继续行动","definition":"to go on doing something although it is difficult, and to refuse to stop because of setbacks","definitionCN":"尽管事情困难，仍继续做下去，不因挫折而停下","example":"She perseveres with the experiment long after her first plan failed.","exampleCN":"最早的方案失败很久之后，她仍坚持做这项实验。","why":"per- intensifies and severus means strict or serious, so persevere originally meant to hold to something strictly, without letting go.","whyCN":"前缀表「彻底」，词根意为「严格、严肃」，因此该词本义是「严格地守住一件事，不松手」。"},{"no":"02","title":"Continue a course once begun","titleCN":"开了头就一路做下去","definition":"to carry a course of action through to its end rather than abandoning it halfway","definitionCN":"把已经开始的做法一路做完，而不是中途放弃","example":"He persevered in his daily readings even during the busiest term.","exampleCN":"即便在最忙的一个学期里，他也坚持每天朗读。","why":"the idea of holding fast to a strict rule explains why the word suits steady habits, not only dramatic struggles.","whyCN":"「严格守住一条规矩」这层意思，解释了为什么该词既用于惊天动地的抗争，也用于日复一日的习惯。"},{"no":"03","title":"Hold to a purpose under pressure","titleCN":"顶着压力守住既定目标","definition":"to remain committed to a decided aim when others argue against it or when it becomes unpopular","definitionCN":"当他人反对或这件事不再受欢迎时，仍忠于已定的目标","example":"The team persevered with the proposal despite loud criticism.","exampleCN":"尽管批评声很大，团队仍坚持这份提案。","why":"a strict, serious holding of a purpose is the mental version of the uphill road: the aim stays fixed while conditions change.","whyCN":"「严肃地守住目标」是那条上坡路在心理层面的版本：条件在变，目标不变。"},{"no":"04","title":"Stay with a long inquiry","titleCN":"在长周期研究里持续投入","definition":"to keep working on a long piece of research or creative work across years of slow progress","definitionCN":"在进展缓慢的多年研究中或长期创作中持续投入","example":"The astronomers persevered for a decade before the signal made sense.","exampleCN":"天文学家坚持了十年，那个信号才变得可解。","why":"the word measures duration as much as difficulty, so it fits inquiries that pay off only after many seasons.","whyCN":"该词既量难度，也量时间，因此特别适合那些要过很多季才有回报的探究。"},{"no":"05","title":"Endure hardship without quitting","titleCN":"在困境中默默撑住而不退出","definition":"to bear continuing discomfort or misfortune rather than walk away from the situation","definitionCN":"承受持续的不适或不幸，而不是从处境中抽身离开","example":"The settlers persevered through a winter without fuel.","exampleCN":"拓荒者熬过了一个没有燃料的冬天。","why":"endurance shades into perseverance when the hardship is not a single event but a stretch of time that must be lived through.","whyCN":"当艰难不是一次事件，而是一段必须活过去的时间，忍耐就变成了坚持。"},{"no":"06","title":"Remain in a state or opinion","titleCN":"固守某种状态或见解","definition":"to continue in a particular condition or opinion, especially when others have moved on","definitionCN":"继续停留在某种状态或看法里，尤其是在别人已经改变之后","example":"He persevered in his doubts long after the evidence had settled the question.","exampleCN":"证据早已把问题定了下来，他却长时间固守着自己的疑虑。","why":"the older construction with in marks the state one stays inside, which is the same root idea as staying on the road.","whyCN":"旧说法在动词后接一个表示「在……之中」的介词，标出人「待在」某种状态里，这与「继续走在路上」是同一个词根意象。"},{"no":"07","title":"Insist on a point in argument","titleCN":"争论中坚持不让步","definition":"to keep repeating or defending a position in a discussion instead of conceding it","definitionCN":"在讨论中反复重申或捍卫某个立场，而不肯让步","example":"She persevered in her objection until the chair allowed a vote.","exampleCN":"她坚持她的反对意见，直到主席同意表决。","why":"holding strictly to a statement is the verbal face of the same stubborn steadiness that the road image shows.","whyCN":"严格守住一句话，与那条路上表现出的倔强稳定是同一件事的口头版本。"},{"no":"08","title":"Stay faithful to a belief","titleCN":"在信仰上坚守到底","definition":"to remain loyal to a faith or a set of beliefs to the end of one's life","definitionCN":"对某种信仰或一套信念忠诚到底，直至生命终点","example":"Many believers persevered in their faith under persecution.","exampleCN":"许多信徒在迫害之下仍坚守信仰。","why":"religious writers borrowed the Latin verb for holding to the faith, and that use kept the sense of holding fast at its purest.","whyCN":"宗教写作者借用了这个拉丁动词表示「守住信仰」，这一用法把「紧抓不放」的意思保存得最纯粹。"}],"etymology":{"intro":{"en":"Persevere comes from Latin perseverare 'to persist, to abide by strictly', built on per- 'thoroughly' and severus 'strict, grave'. The deeper origin of severus is not established, and dates are approximate.","cn":"该词来自拉丁语 perseverare「坚持、严格遵守」，由 per-「彻底」与 severus「严格、严肃」构成。severus 更深的来源尚未查明，年代均为约数。"},"items":[{"era":"LATIN SEVERUS","en":"Severus meant 'strict, serious, grave'. Its deeper source is not settled; the suggestions that link it to a root for 'heavy' or to a word for 'setting apart' are hypotheses, not demonstrated derivations.","cn":"severus 意为「严格、严肃、庄重」。其更深来源无定论；把它与表示「沉重」的词根或表示「分开」的词相联系的看法都只是假说，并非已证实的派生。"},{"era":"LATIN PERSEVERARE","en":"Per- 'thoroughly' plus severus produced perseverare 'to abide by strictly, to persist', a verb of holding to a rule without slackening.","cn":"per-「彻底」加 severus 构成 perseverare「严格遵守、坚持」，是一个表示「毫不放松地守住规矩」的动词。"},{"era":"LATIN PERSEVERANTIA","en":"The abstract noun perseverantia 'steadfastness' appears in late Latin prose, and it is the direct model for the English noun.","cn":"抽象名词 perseverantia「坚定不移」出现在晚期拉丁语散文中，是英语中对应名词的直接原型。"},{"era":"OLD FRENCH","en":"Old French perseverer carried the verb into Middle English in the fourteenth century, at first in religious and moral writing.","cn":"古法语 perseverer 在十四世纪把这个动词带入中古英语，最早见于宗教与道德论述。"},{"era":"RELIGIOUS USE","en":"English divinity fixed the phrase to persevere in the faith, meaning to hold out to the end rather than to start well.","cn":"英语神学固定了「在信仰中坚持到底」的说法，强调不是开头好，而是守到最后。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin of severus): no exact first citation is recorded for the everyday sense of keeping at a task, and any Indo-European form offered for severus is a reconstruction.","cn":"来源不确定（severus 的更深词源）：日常「坚持做一件事」的义项没有确切的最早书证；凡为 severus 给出的印欧语形式均属重构形式。"}]},"similar":{"note":{"en":"Group one collects look-alikes built with per- or with a similar shape but a different root; group two collects verbs of continuing that differ in what they stress.","cn":"第一组是形近但词根不同的词；第二组是都表示「继续」、但侧重不同的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"persuade","ipa":"/pəˈsweɪd/","tag":"different root","definition":"Per- 'thoroughly' plus suadere 'to advise': to talk someone into a view, with no element of endurance.","definitionCN":"由 per-「彻底」加 suadere「劝告」构成：以言辞使人接受某种看法，与「熬住」无关。"},{"word":"pursue","ipa":"/pəˈsjuː/","tag":"different root","definition":"From Latin pro- 'forward' plus sequi 'to follow': to chase or follow something, not to outlast it.","definitionCN":"来自拉丁 pro-「向前」加 sequi「跟随」：追赶或追随某物，而不是熬过它。"},{"word":"preserve","ipa":"/prɪˈzɜːv/","tag":"different prefix","definition":"Prae- 'before' plus servare 'to keep': to keep something safe from harm, which is about protection, not persistence.","definitionCN":"由 prae-「在前」加 servare「保存」构成：使某物免受损害，说的是保护而非持续。"},{"word":"perverse","ipa":"/pəˈvɜːs/","tag":"different root","definition":"Per- 'thoroughly' plus vertere 'to turn': turned the wrong way, deliberately contrary, with no link to strictness.","definitionCN":"由 per-「彻底」加 vertere「转」构成：方向转反了、故意与人相反，与「严格」无关。"},{"word":"severe","ipa":"/sɪˈvɪə/","tag":"shares the root","definition":"The adjective behind the Latin verb: strict, harsh, not allowing slack, so it is the closest relative in form and meaning.","definitionCN":"就是那个拉丁动词背后的形容词：严格、严厉、不许松懈，是形与义都最近的同族词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"persist","ipa":"/pəˈsɪst/","tag":"keep on existing","definition":"To continue in an action or state, often with the note of lasting longer than expected; it can describe things as well as people.","definitionCN":"继续做某事或保持某状态，常带「比预想更久」的意味；人与物都可用。"},{"word":"endure","ipa":"/ɪnˈdjʊə/","tag":"bear the pain","definition":"To suffer something difficult patiently; the focus is on the weight borne, while perseverance adds the choice to keep going.","definitionCN":"耐心承受艰难，重点在承担的分量；而该词另加了一层「主动选择继续」。"},{"word":"insist","ipa":"/ɪnˈsɪst/","tag":"hold a claim","definition":"To state or demand something firmly and refuse to drop it, usually in speech rather than in long effort.","definitionCN":"坚定地声明或要求某事而不肯作罢，多用于言语，而非长期行动。"},{"word":"carry on","ipa":"/ˈkæri ɒn/","tag":"plain and neutral","definition":"The everyday phrase for continuing an activity; it reports the fact without praising the grit.","definitionCN":"继续某项活动的日常说法；只陈述事实，不含赞许毅力的意味。"},{"word":"stick with it","ipa":"/stɪk wɪð ɪt/","tag":"informal staying power","definition":"An informal phrase for not abandoning a task; close to the meaning but limited to relaxed speech.","definitionCN":"不放弃某项任务的口语说法；意思相近，但只用于轻松的口语。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives rather than invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Per- 'thoroughly' plus severus 'strict': to be strict with yourself all the way through.","cn":"前缀表「彻底」，词根表「严格」：对自己一路严格到底。"},{"en":"The family runs persevere, perseverance, persevering, perseveringly, perseverant.","cn":"同族词包括动词、名词、形容词、副词与少用的拉丁式形容词五种形态。"},{"en":"Fixed phrases mark the struggle: persevere with a task, persevere in the face of failure, persevere to the end.","cn":"固定搭配标出这份挣扎：坚持任务、在失败面前不退、坚持到底。"},{"en":"The shared root shows in severe and severity, where the same strictness appears without the effort of continuing.","cn":"同根词 severe 与 severity 里能看到同一份「严厉」，只是不带「持续」的意味。"},{"en":"The noun perseverance is the one used in praise: perseverance wins long races.","cn":"名词形式常用于称赞：毅力能赢下长跑。"}],"abstract":[{"en":"Picture a candle that keeps burning although the window will not stay shut.","cn":"想象一支蜡烛，窗子关不严，它却一直燃着。"},{"en":"Picture a river that keeps cutting the same channel through new rock each year.","cn":"想象一条河，每年都在新岩层里把同一条河道切下去。"},{"en":"Picture a hand writing the same sentence again and again until the ink runs out.","cn":"想象一只手把同一句话一遍遍写下去，直到墨水用尽。"}]},"examples":[{"en":"The researchers persevered through four failed seasons before the method worked.","cn":"研究人员熬过四个失败的季节，方法才奏效。"},{"en":"You will not master the cello unless you persevere with the scales.","cn":"如果不在音阶上坚持，你就学不好大提琴。"},{"en":"She persevered in her request until the committee finally replied.","cn":"她一直坚持提出请求，委员会最终给了答复。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"per（彻底）+ severe（严厉）——对自己一路严厉下去，就是坚持","word":"persevere"},"root":"拉丁 perseverare「坚持、严格遵守」= per-（彻底）+ severus「严格、严肃」；severus 更深来源不确定，相关词根联系均为假说。","sensesIntro":{"en":"Eight senses follow one gesture: a person stays on the same road while the weather, the critics and the years change around it.","cn":"八个义项沿同一个动作展开：路不变，人在上面不走开，而天气、旁人与岁月都在变。"},"semanticMap":{"core":{"en":"CORE IMAGE: a walker on a long uphill stair in heavy rain, one step after another, never turning back.","cn":"核心意象：大雨里有人走在长长的上坡石阶上，一步接一步，从不回头。"},"chain":["BEGIN","MEET RESISTANCE","REFUSE TO STOP","REPEAT THE STEP","OUTLAST THE HARDSHIP","REACH THE END"],"branches":[{"senses":"01 · 02","en":"THE ROAD ITSELF: start moving and keep the same motion to the end.","cn":"路本身：起步行进，并把同一个动作做到终点。"},{"senses":"03 · 07","en":"HOLDING A POSITION: a purpose or an argument is gripped as tightly as a handrail.","cn":"守住位置：目标或论点像扶手一样被紧紧握住。"},{"senses":"04","en":"LONG TIME: years of slow work are the road stretched out.","cn":"长时间：多年缓慢的工作，就是把路拉得很长。"},{"senses":"05","en":"BEARING WEATHER: the rain is endured rather than escaped.","cn":"承受天气：雨是被熬过去的，而不是躲开的。"},{"senses":"06 · 08","en":"STAYING INSIDE: remaining in a state or a faith is standing still on the road rather than leaving it.","cn":"待在原处：留在某种状态或信仰里，就是站在原地而不离开这条路。"}]},"affixes":{"intro":{"en":"The word is a Latin verb held together by an intensive prefix and a root adjective, and both parts also build other English words, so it can be read morpheme by morpheme.","cn":"这个词是一个拉丁动词，由一个表加强的前缀和一个形容词性词根合成，两部分都还构成别的英语词，因此可以按语素逐个读出。"},"latinIntro":{"en":"Latin severus yields severe, severity and asseverate; per- yields perceive, persist and pervade, though each of those has its own root.","cn":"拉丁 severus 衍生出 severe、severity 与 asseverate；per- 还见于 perceive、persist 与 pervade，但它们各自另有词根。"},"items":[{"word":"per-","structure":"per- (Latin prefix, 'through, thoroughly')","meaning":"through; completely","meaningCN":"穿过；彻底","example":"The prefix pushes the action to its limit.","exampleCN":"这个前缀把动作推到极限。"},{"word":"severus","structure":"severus (Latin adjective, 'strict, grave')","meaning":"strict; serious","meaningCN":"严格的；严肃的","example":"The root supplies the note of strictness.","exampleCN":"这个词根提供了「严格」的意味。"},{"word":"persevere","structure":"per- + severus + verbal ending","meaning":"to hold to strictly","meaningCN":"严格守住；坚持","example":"They persevered with the rebuild.","exampleCN":"他们坚持把这件重建做完。"},{"word":"perseverance","structure":"persevere + -ance (state, quality)","meaning":"steadfastness","meaningCN":"坚定不移的品质","example":"Perseverance outlasted the doubt.","exampleCN":"毅力比怀疑撑得更久。"},{"word":"persevering","structure":"persevere + -ing (adjective)","meaning":"showing steady effort","meaningCN":"表现出持续用力的","example":"A persevering reader finished the whole archive.","exampleCN":"一位有毅力的读者读完了整座档案。"},{"word":"perseveringly","structure":"persevering + -ly (adverb)","meaning":"in a steadfast manner","meaningCN":"以坚持不懈的方式","example":"She wrote perseveringly for six hours.","exampleCN":"她坚持不懈地写了六个小时。"},{"word":"severity","structure":"severe + -ity (noun of quality)","meaning":"harshness, strictness","meaningCN":"严厉；严重","example":"The severity of the rule left no room to bend.","exampleCN":"这条规矩的严厉程度不留任何通融余地。"},{"word":"severe","structure":"severus passing into English","meaning":"strict, harsh","meaningCN":"严厉的；严峻的","example":"A severe winter closed the pass.","exampleCN":"一个严酷的冬天封住了山口。"},{"word":"asseverate","structure":"ad- + severus + -ate (verb)","meaning":"to state solemnly","meaningCN":"郑重声明","example":"He asseverated that the record was complete.","exampleCN":"他郑重声明记录是完整的。"}],"latinEntries":[{"word":"severus","structure":"severus, severa, severum (adjective, first and second declension)","meaning":"strict, grave, serious","meaningCN":"严格的；严肃的"},{"word":"perseverare","structure":"perseverare, perseveravi, perseveratum (verb, first conjugation)","meaning":"to persist, abide by strictly","meaningCN":"坚持；严格遵守"},{"word":"perseverantia","structure":"perseverantia, perseverantiae (f., first declension)","meaning":"steadfastness, persistence","meaningCN":"坚定；持久"},{"word":"perseverans","structure":"perseverans, perseverantis (present participle)","meaning":"persisting, holding fast","meaningCN":"坚持的；守住不放的"}]}},{"word":"determined","ipa_uk":"/dɪˈtɜː.mɪnd/","ipa_us":"/dɪˈtɝː.mɪnd/","definition_zh":"下定决心的；意志坚定的；由某因素所决定的；已确定下来的","definition_en":"having firmly decided to do something and unlikely to change one's mind","core_image":"一个人在地图上把终点圈住，把其他岔路一条条划掉，只留一条线","scene":"报名前一天，她划掉了所有备选方案，只在申请书第一行写下目标学校。She was determined to apply to only one school and to accept no fallback.","sceneCN":"这里 determined 指「已经下定决心、不再更改」（第 1 个义项：决定已作出且不动摇）；句意为她决心只申请一所学校，不接受任何备用选择。图中可辨识物件：被划掉的分支路线、圈住的终点、只写一行的申请书。","pos":[{"tag":"adj.","zh":"下定决心的；意志坚定的；确定的"},{"tag":"v. (past participle)","zh":"determine 的过去式与过去分词：决定；确定；查明"}],"collocations":[{"phrase":"be determined to do","zh":"决心做某事"},{"phrase":"a determined effort","zh":"坚决的努力"},{"phrase":"a determined attempt","zh":"一次决意十足的尝试"},{"phrase":"determined opposition","zh":"坚决的反对"},{"phrase":"determined by circumstances","zh":"由环境所决定"},{"phrase":"a determined look","zh":"坚定的神情"}],"forms":[{"label":"原级","form":"determined"},{"label":"比较级","form":"more determined"},{"label":"最高级","form":"most determined"},{"label":"动词原形（determine）","form":"determine"},{"label":"动词三单","form":"determines"},{"label":"动词过去式","form":"determined"},{"label":"动词现在分词","form":"determining"},{"label":"名词（决心）","form":"determination"}],"derivatives":[{"word":"determination","pos":"n.","zh":"由动词加表示行为与结果的名词后缀构成，语义由「定下界限」转为「定下决心的行为与那股劲」"},{"word":"determine","pos":"v.","zh":"基础动词，来自拉丁语「划定界限」，语义为「确定、决定、查明」"},{"word":"determinism","pos":"n.","zh":"在动词词干后加表示学说的名词后缀构成，语义由「被决定」转为「一切皆由前因决定的主张」"},{"word":"determinant","pos":"n./adj.","zh":"加表示「起作用之物」的后缀构成，语义由「确定」转为「起决定作用的因素」"},{"word":"indeterminate","pos":"adj.","zh":"加否定前缀与形容词后缀构成，语义由「已划定」转为「界限不明、无法确定」"},{"word":"predetermined","pos":"adj.","zh":"加表示「在前」的前缀构成，语义由「已决定」转为「事先就已定好」"}],"senses":[{"no":"01","title":"Having made a firm decision","titleCN":"已经下定决心，不肯更改","definition":"having decided firmly what one will do and refusing to be talked out of it","definitionCN":"已经坚定地决定要做什么，别人劝也劝不动","example":"She was determined to apply to only one school and to accept no fallback.","exampleCN":"她决心只申请一所学校，不接受任何备用选择。","why":"determine comes from de- plus terminare 'to set a boundary', so being determined is having one's choice fenced in and closed to other options.","whyCN":"该词来自拉丁语「划定界限」，因此「下定决心」就是把选择围起来，对别的选项关上口子。"},{"no":"02","title":"Resolute by temperament","titleCN":"性格上本就不屈不挠","definition":"having a character that does not easily give way to doubt, fatigue or discouragement","definitionCN":"性格上不容易被怀疑、疲惫或气馁所动摇","example":"A determined captain kept the crew working through the storm.","exampleCN":"一位意志坚定的船长让船员在风暴中继续工作。","why":"when this quality belongs to the person rather than to one decision, the adjective describes temperament, not a single act.","whyCN":"当这份品质属于整个人而非某一个决定时，这个形容词描述的是性情，而不是一次行动。"},{"no":"03","title":"Fixed in advance","titleCN":"事先就已确定","definition":"settled beforehand, so that no further choice or change is possible","definitionCN":"事先已经定好，因此不再有选择或更改的余地","example":"The starting date is determined and cannot be moved.","exampleCN":"开始日期已经确定，不能更改。","why":"the boundary image is literal here: a line drawn once, with nothing left to redraw.","whyCN":"这里「界限」的意象是字面用法：线已经画好一次，没有可重画的地方。"},{"no":"04","title":"Caused by a factor","titleCN":"由某个因素所决定","definition":"decided or produced by a particular cause rather than chosen freely","definitionCN":"由特定原因所决定或产生，而不是自由选择的","example":"Crop yields are largely determined by rainfall in this region.","exampleCN":"在这一地区，作物产量在很大程度上由降雨决定。","why":"the passive construction marks the boundary as drawn from outside: something else fixes where the outcome falls.","whyCN":"被动结构标出这条界限是由外部画上的：是别的因素定住了结果落在何处。"},{"no":"05","title":"Firm and forceful in execution","titleCN":"行动上果断有力","definition":"done with visible firmness and energy, so that the effort itself is unmistakable","definitionCN":"以看得见的坚定与力度完成，使努力本身一望即知","example":"They made a determined effort to finish before the deadline.","exampleCN":"他们下了决心，要在截止前完成。","why":"a decision that has closed off alternatives shows up in how the work is done, and the adjective then describes the effort.","whyCN":"一个已经排除其他可能的决定，会显现在做事的方式上，这个形容词于是用来描述努力本身。"},{"no":"06","title":"Aimed at one definite goal","titleCN":"目标明确、直指一处","definition":"directed at a single stated aim instead of scattered or exploratory movement","definitionCN":"直指一个明确说出的目标，而非散乱或试探性的移动","example":"It was a determined attempt to settle the question once and for all.","exampleCN":"那是一次要一劳永逸解决这个问题的决意尝试。","why":"one boundary means one target, which is why the adjective often appears before attempt and effort.","whyCN":"一条界限只对应一个目标，因此这个形容词常出现在「尝试」「努力」这类词之前。"},{"no":"07","title":"Unmoved from a stated position","titleCN":"立场不动摇","definition":"holding to a public position when pressure, ridicule or loss is applied against it","definitionCN":"在压力、嘲笑或损失袭来时，仍守住公开表明的立场","example":"The mayor remained determined despite the hostile press.","exampleCN":"尽管媒体充满敌意，市长仍不动摇。","why":"the strength is now social: the boundary is defended against other people pushing on it.","whyCN":"这时的力量是社会性的：这条界限是在别人推挤之下守住。"},{"no":"08","title":"Stubborn past the point of reason","titleCN":"倔强到近乎固执","definition":"holding on so hard that advice and evidence no longer get a hearing","definitionCN":"抓得太紧，以至于劝告与证据都进不来","example":"He was determined to prove the critics wrong, even at ruinous cost.","exampleCN":"他执意要证明批评者是错的，哪怕代价极其惨重。","why":"the same closed boundary turns into a vice when nothing at all can cross it, and the word acquires a shade of obstinacy.","whyCN":"同一条封闭的界线，如果什么都进不来，就会变成缺陷，于是这个词带上了固执的色彩。"}],"etymology":{"intro":{"en":"Determined is the past participle of determine, which comes from Latin determinare 'to limit, to fix the end of', built on de- 'completely' and terminare 'to set a boundary', from terminus 'boundary, end'. The origin of terminus itself is not settled. Dates are approximate.","cn":"determined 是 determine 的过去分词，后者来自拉丁语 determinare「限定、定下终点」，由 de-「完全」与 terminare「划定界限」构成，后者又出自动词 terminus「边界、终点」。terminus 本身的来源没有定论，年代均为约数。"},"items":[{"era":"LATIN TERMINUS","en":"Terminus meant 'boundary stone, end, limit'. Its deeper origin is uncertain; the connection sometimes drawn to a root meaning 'to cross over' is a hypothesis rather than a demonstrated derivation.","cn":"terminus 意为「界石、终点、界限」。其更深来源不确定；有人把它与表示「越过」的词根相联系，那只是假说，并非已证实的派生。"},{"era":"LATIN TERMINARE","en":"Terminare 'to set a boundary, to bring to an end' turned the stone into an action: you draw the line and the matter stops there.","cn":"terminare「划定界限、使结束」把这块界石变成了动作：把线一画，事情就停在那里。"},{"era":"LATIN DETERMINARE","en":"De- 'completely' plus terminare gave determinare 'to limit fully, to settle, to fix', the source of both the English verb and the adjective.","cn":"de-「完全」加 terminare 构成 determinare「完全限定、定下、确定」，是英语动词与形容词的共同来源。"},{"era":"OLD FRENCH","en":"Old French determiner passed the verb into Middle English, where it first meant to decide a question or to bring something to an end.","cn":"古法语 determiner 把这个动词带入中古英语，最初指裁决一个问题或把某事推向结束。"},{"era":"MODERN ADJECTIVE","en":"The past participle became an adjective in its own right, so that a determined person is one whose choice has already been closed off.","cn":"这个过去分词独立成为形容词，因此「一个下定决心的人」就是一个选择已经被关上的人。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (origin of terminus): no exact date can be given for the adjective's first use, and any Indo-European form proposed for terminus is a reconstruction.","cn":"来源不确定（terminus 的来源）：这个形容词最早使用的确切年代无从给出；凡为 terminus 提出的印欧语形式均属重构形式。"}]},"similar":{"note":{"en":"Group one separates words that look close to determined but rest on a different root; group two separates adjectives of resolve by what they stress.","cn":"第一组区分形近而词根不同的词；第二组按侧重区分表示「坚决」的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"determinant","ipa":"/dɪˈtɜːmɪnənt/","tag":"same root, noun use","definition":"A factor that fixes an outcome; same Latin base, but it names the cause rather than the resolve.","definitionCN":"决定结果的因素；拉丁词干相同，但它指那个原因，而不是那股决心。"},{"word":"terminate","ipa":"/ˈtɜːmɪneɪt/","tag":"same root, different prefix","definition":"To bring something to an end, built directly on terminare without the de- prefix.","definitionCN":"使某事结束，直接由 terminare 构成，不带 de- 前缀。"},{"word":"terminal","ipa":"/ˈtɜːmɪnəl/","tag":"same family","definition":"Relating to an end or a boundary, as in terminal station; it keeps the stone image but loses the sense of resolve.","definitionCN":"与终点或界限有关，如终点站；保留了界石的意象，但没有「决心」之义。"},{"word":"determinism","ipa":"/dɪˈtɜːmɪnɪzəm/","tag":"same root, theory","definition":"The doctrine that every event is fixed by prior causes; the boundary is drawn by the past, not by a person.","definitionCN":"主张一切事件皆由此前原因所决定；界限由过去画出，而不是由人画出。"},{"word":"exterminate","ipa":"/ɪkˈstɜːmɪneɪt/","tag":"different prefix","definition":"Ex- 'out' plus terminare 'boundary': to drive something past the boundary, hence to destroy it completely.","definitionCN":"由 ex-「出」加 terminare「界限」构成：把某物赶出界限之外，因而指彻底消灭。"}]},{"heading":"NEAR MEANING","entries":[{"word":"resolute","ipa":"/ˈresəluːt/","tag":"decision already made","definition":"Firm in purpose, with the sense of having solved or settled the question; slightly more formal than determined.","definitionCN":"目标坚定，带「问题已解决、已定下」的意味；比 determined 略正式。"},{"word":"stubborn","ipa":"/ˈstʌbən/","tag":"negative shade","definition":"Refusing to change even when change is reasonable; it keeps only the vice of determination.","definitionCN":"即便改变是合理的也不肯改；只保留了「决心」变成缺陷的那一面。"},{"word":"committed","ipa":"/kəˈmɪtɪd/","tag":"pledged","definition":"Bound by a pledge to a person, cause or course; the emphasis is on obligation and loyalty.","definitionCN":"因承诺而绑定于某人、某项事业或某条道路；重点在义务与忠诚。"},{"word":"decisive","ipa":"/dɪˈsaɪsɪv/","tag":"quick to settle","definition":"Able to settle a matter quickly and firmly; it describes the speed and finality of the choice.","definitionCN":"能迅速而坚定地定下事情；描述的是选择的速度与终局性。"},{"word":"steadfast","ipa":"/ˈstedfɑːst/","tag":"does not waver","definition":"Firmly fixed and not wavering over time; it stresses continuity more than a single decision.","definitionCN":"牢牢固定、经时不摇；比单次决定更强调时间上的连续性。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin de- 'completely' plus terminus 'boundary': a decision that fences the matter in on all sides.","cn":"拉丁 de-「完全」加 terminus「界限」：把这件事四面围起来的决定。"},{"en":"The family runs determine, determined, determination, determinant, determinism, indeterminate.","cn":"同族词覆盖动词、形容词、名词、因素名词、学说名词与否定形容词。"},{"en":"Fixed phrases mark the resolve: be determined to do, a determined effort, a determined attempt.","cn":"固定搭配标出这股决心：决心去做、坚决的努力、决意的尝试。"},{"en":"The passive phrase determined by shifts the boundary outside the person, so it means caused, not resolute.","cn":"被动说法「由……所决定」把界限移到人之外，因此意思是「由……造成」，而非「坚决」。"},{"en":"The same stone appears in terminal and terminate, where an end is reached rather than a will held.","cn":"同一块界石还出现在 terminal 与 terminate 里，那里是走到终点，而不是守住意志。"}],"abstract":[{"en":"Picture a pencil line drawn around one square on a map while every other square stays blank.","cn":"想象在地图上用一个方框圈住一格，其余格子全部留白。"},{"en":"Picture a door with the key turned once and then removed from the lock.","cn":"想象一扇门，钥匙转过一次后被从锁里拔走。"},{"en":"Picture a compass needle that has stopped trembling and now points one way only.","cn":"想象一枚罗盘指针不再抖动，只朝一个方向。"}]},"examples":[{"en":"The engineers were determined to find the leak before the rainy season.","cn":"工程师决心在雨季之前找到漏点。"},{"en":"She gave a determined answer that ended the argument.","cn":"她给出了一个坚决的答复，结束了争论。"},{"en":"Water loss is determined by soil type and by wind speed.","cn":"水分损失由土壤类型与风速决定。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"de（彻底）+ term（期限/界限）——把期限彻底定死 → 下定决心、确定","word":"determined"},"root":"拉丁 determinare「限定、定下终点」= de-（完全）+ terminare「划定界限」；terminus「界石、终点」更深来源不确定。","sensesIntro":{"en":"Eight senses follow one gesture: a line is drawn around a choice, and then the line is applied to a person's character, a fixed date, an external cause, a style of work, a single aim, a defended stand and finally to obstinacy.","cn":"八个义项沿同一个动作展开：先在一个选择周围画一条线，再把这条线依次用于人的性情、已定的日期、外部原因、做事风格、单一目标、被捍卫的立场，最后用于固执。"},"semanticMap":{"core":{"en":"CORE IMAGE: a line drawn once around one choice, with every other option left outside it.","cn":"核心意象：在一个选择周围画一次线，别的选项都被留在线外。"},"chain":["CHOOSE","DRAW THE LINE","CLOSE THE OPTIONS","HOLD THE LINE","ACT FIRMLY","BECOME RIGID"],"branches":[{"senses":"03 · 04","en":"WHO DRAWS THE LINE: a person, a calendar or an outside cause can all be the hand holding the pencil.","cn":"谁来画线：人、日历或外部原因都可以是握笔的那只手。"},{"senses":"01 · 02","en":"THE CLOSED CHOICE: a single decision hardens into a lasting trait of character.","cn":"被关上的选择：一次决定硬化成长久的人格特征。"},{"senses":"05 · 06","en":"THE LINE SHOWS IN THE WORK: one aim and a forceful manner are what a closed choice looks like from outside.","cn":"线显现在活里：单一目标与有力的做法，就是「选择已关上」从外面看到的样子。"},{"senses":"07","en":"THE DEFENDED LINE: other people push, and the boundary is held anyway.","cn":"被守住的线：别人来推，界线仍然守住。"},{"senses":"08","en":"THE LINE THAT BECOMES A WALL: when nothing can cross, firmness turns into a fault.","cn":"变成墙的线：什么都不能通过时，坚定就转成了缺陷。"}]},"affixes":{"intro":{"en":"Determined is a Latin participle whose prefix and stem also appear across a wide English family, so the whole group can be read by parts.","cn":"determined 是一个拉丁分词，它的前缀与词干还出现在一大串英语词里，因此整组词可以按部件读出。"},"latinIntro":{"en":"Latin terminus gives terminal, terminate, termination and exterminate; de- 'completely' also appears in declare and demolish, where it marks thoroughness.","cn":"拉丁 terminus 衍生出 terminal、terminate、termination 与 exterminate；de-「完全」也见于 declare 与 demolish，表示彻底。"},"items":[{"word":"de-","structure":"de- (Latin prefix, 'completely, down from')","meaning":"completely; down from","meaningCN":"完全；自……而下","example":"The prefix adds thoroughness to the action.","exampleCN":"这个前缀给动作添上「彻底」。"},{"word":"terminus","structure":"terminus (Latin noun, 'boundary stone, end')","meaning":"boundary; end","meaningCN":"界石；终点","example":"The stone marks where the land stops.","exampleCN":"这块石头标出土地到此为止。"},{"word":"determine","structure":"de- + terminare (verb)","meaning":"to fix, decide, find out","meaningCN":"确定；决定；查明","example":"Tests determine the cause of the fault.","exampleCN":"检测能确定故障原因。"},{"word":"determination","structure":"determine + -ation (action, result)","meaning":"the act of deciding, and the firmness behind it","meaningCN":"决定的行为，以及背后的坚定","example":"Her determination carried the plan through.","exampleCN":"她的决心撑住了整个计划。"},{"word":"determined","structure":"determine + -ed (past participle as adjective)","meaning":"having the decision closed","meaningCN":"决心已定的","example":"The crew was determined to finish.","exampleCN":"工人们决心把它做完。"},{"word":"determinant","structure":"determine + -ant (that which acts)","meaning":"a deciding factor","meaningCN":"决定因素","example":"Price is the main determinant of demand.","exampleCN":"价格是需求的主要决定因素。"},{"word":"determinism","structure":"determine + -ism (doctrine)","meaning":"the view that all events are fixed in advance","meaningCN":"一切事件皆前定的主张","example":"Determinism leaves no room for free choice.","exampleCN":"前定论不给自由选择留余地。"},{"word":"indeterminate","structure":"in- + determine + -ate (adjective)","meaning":"not fixed, not settled","meaningCN":"未确定的；界限不明的","example":"The species remains indeterminate.","exampleCN":"这个物种的分类仍未确定。"},{"word":"predetermined","structure":"pre- + determine + -ed","meaning":"settled beforehand","meaningCN":"事先定好的","example":"The routes were predetermined by the guide.","exampleCN":"路线由向导事先定好。"},{"word":"terminal","structure":"terminus + -al (adjective)","meaning":"belonging to an end","meaningCN":"属于终点的","example":"The terminal wing was closed.","exampleCN":"航站楼的末端区域封闭了。"}],"latinEntries":[{"word":"terminus","structure":"terminus, termini (m., second declension)","meaning":"boundary stone, end","meaningCN":"界石；终点"},{"word":"terminare","structure":"terminare, terminavi, terminatum (verb, first conjugation)","meaning":"to set a boundary, to end","meaningCN":"划定界限；结束"},{"word":"determinare","structure":"determinare, determinavi, determinatum (verb, first conjugation)","meaning":"to limit, settle, fix","meaningCN":"限定；定下；确定"},{"word":"determinatio","structure":"determinatio, determinationis (f., third declension)","meaning":"a fixing of limits, a decision","meaningCN":"限定；决定"}]}},{"word":"effort","ipa_uk":"/ˈef.ət/","ipa_us":"/ˈef.ɚt/","definition_zh":"努力；费力的一次尝试；费尽心力做出的成果；集体的协同行动；（物理学）作用力","definition_en":"the physical or mental energy used when trying to do something","core_image":"一个人推着装满石头的木车，青筋鼓起，车轮在地面上压出一道痕","scene":"山路太陡，几个人一起推同一辆货车，车轮才勉强往前走。Their combined effort moved the cart only a few metres before they had to rest.","sceneCN":"这里 effort 指「为达成一件事而付出的体力或脑力」（第 1 个义项：付出力气去做）；句意为他们合力只把车推动了几米就不得不停下。图中可辨识物件：木车、陡坡、被压出的车辙、几双用力的腿。","pos":[{"tag":"n.","zh":"努力；尝试；费力得到的成果；协同行动"},{"tag":"n. (technical)","zh":"（机械学）作用力、施力"}],"collocations":[{"phrase":"make an effort","zh":"作出努力；尽力"},{"phrase":"put effort into","zh":"在……上投入心力"},{"phrase":"a joint effort","zh":"共同的努力"},{"phrase":"spare no effort","zh":"不遗余力"},{"phrase":"a relief effort","zh":"救援行动"},{"phrase":"physical effort","zh":"体力付出"},{"phrase":"effort and reward","zh":"付出与回报"}],"forms":[{"label":"单数","form":"effort"},{"label":"复数","form":"efforts"},{"label":"形容词（费力的）","form":"effortful"},{"label":"副词（费力地）","form":"effortfully"},{"label":"形容词（不费力的）","form":"effortless"},{"label":"副词（不费力地）","form":"effortlessly"}],"derivatives":[{"word":"effortful","pos":"adj.","zh":"由名词加表示「充满」的形容词后缀构成，语义由「力气」转为「需要使力气的」"},{"word":"effortfully","pos":"adv.","zh":"在形容词后加副词后缀构成，语义由「费力的」转为「以费力方式」"},{"word":"effortless","pos":"adj.","zh":"加表示「缺少」的形容词后缀构成，语义由「力气」转为「看起来不费力气」"},{"word":"effortlessly","pos":"adv.","zh":"在否定式形容词后加副词后缀构成，语义由「不费力的」转为「毫不费力地」"},{"word":"effortlessness","pos":"n.","zh":"在否定式形容词后加名词后缀构成，语义由「不费力」转为「不费力这一特质」"}],"senses":[{"no":"01","title":"Energy spent on a task","titleCN":"为做成一件事付出的力气","definition":"the physical or mental energy that someone uses in trying to do something","definitionCN":"某人为做成某件事而投入的体力或脑力","example":"Their combined effort moved the cart only a few metres before they had to rest.","exampleCN":"他们合力只把车推动了大约几米，就不得不停下休息。","why":"the word descends from a Latin verb meaning to strengthen, so the first sense is simply the strength that a task draws out of a person.","whyCN":"这个词源自一个意为「使有力」的拉丁动词，所以第一个义项就是一件事从人身上抽出的那股力。"},{"no":"02","title":"A single attempt","titleCN":"一次具体的尝试","definition":"one act of trying to do something, viewed as a countable attempt","definitionCN":"试着做某事的一次行动，可以按次计数","example":"He made three efforts to lift the lid before asking for help.","exampleCN":"他试着揭开盖子三次，才去求助。","why":"once energy is spent it can be counted as a try, so the noun shifts from the fuel to the event that burns it.","whyCN":"力气一旦花出去，就可以说成「一次尝试」，于是名词从燃料转向烧掉燃料的那件事。"},{"no":"03","title":"A piece of work produced","titleCN":"费心做出的成果","definition":"a result or piece of work judged by how much care and labour went into it","definitionCN":"按投入的心血与劳动来评价的成果或作品","example":"Her essay was a serious effort, even if the argument faltered.","exampleCN":"她的文章是一份认真写就的成果，尽管论证有些摇晃。","why":"we praise a thing by naming the labour inside it, so the word can stand for the product rather than the process.","whyCN":"人们通过点出其中所含的劳动来称赞一件东西，于是这个词可以用产物代替过程。"},{"no":"04","title":"Organized collective action","titleCN":"有组织的集体行动","definition":"a coordinated campaign in which many people work toward one public aim","definitionCN":"许多人朝同一个公共目标协作推进的行动","example":"The relief effort reached the valley two days after the flood.","exampleCN":"洪水过后两天，救援行动抵达了山谷。","why":"when many people spend energy on one aim, the countable noun becomes the whole campaign rather than any single exertion.","whyCN":"当许多人把力气投向一个目标时，这个可数名词指的就是整场行动，而不是任何单次用力。"},{"no":"05","title":"Force applied in a machine","titleCN":"机械中施加的力","definition":"in mechanics, the force applied to a machine or load, as opposed to the resistance it moves","definitionCN":"力学中施加于机械或负载的力，与它所推动的阻力相对","example":"A longer lever increases the effect of the effort on the load.","exampleCN":"较长的杠杆会增大作用力对负载的效果。","why":"the technical sense keeps the plain meaning exactly: the force a worker puts in, measured against what the machine must move.","whyCN":"这个技术义保留了最朴素的意思：人使出的那股力，与机器要移动的东西相对而量。"},{"no":"06","title":"Degree of strain involved","titleCN":"费力程度","definition":"the amount of strain a task demands, considered as a property of the task","definitionCN":"任务所要求的紧张程度，作为任务本身的属性来看","example":"The climb costs little effort if you start early.","exampleCN":"如果早点出发，这段爬坡并不费多少力气。","why":"instead of the energy itself, the word can name the quantity of it that a job requires, which is why one asks how much effort a task takes.","whyCN":"这个词可以不指力气本身，而指一件事所需的力气分量，所以人们会问一项任务要花多少努力。"},{"no":"07","title":"National mobilization","titleCN":"举国之力的动员","definition":"the total organized activity of a country or a large body in wartime or emergency","definitionCN":"战时或紧急状态下，一国或一个大型机构投入的全部组织性活动","example":"The war effort drew factories, farms and railways into one plan.","exampleCN":"战时动员把工厂、农场与铁路都纳入一个计划。","why":"this is the collective sense enlarged to the scale of a whole society, where every exertion feeds a single campaign.","whyCN":"这是集体义被放大到整个社会的规模：每一份力气都汇入同一场行动。"},{"no":"08","title":"An attempt judged kindly","titleCN":"值得称许的一次尝试（即使未成）","definition":"an attempt that is praised for the honesty of the trying even though it falls short","definitionCN":"即便未达到目标，也因尝试本身认真而受到赞许的一次努力","example":"The team lost, but it was a brave effort by every player.","exampleCN":"球队输了，但每位队员的这次努力都很勇敢。","why":"because effort measures what was given rather than what was gained, the word becomes a way of honouring a failure.","whyCN":"因为这个词量的是付出而非所得，它就成了给失败留体面的一种说法。"}],"etymology":{"intro":{"en":"Effort comes through Old French esforz from the verb esforcier 'to force, exert', which rests on a Vulgar Latin verb reconstructed as exfortiare, from Latin fortis 'strong'. The deeper origin of fortis is not settled. Dates are approximate.","cn":"该词经古法语 esforz 来自动词 esforcier「用力、使力」，后者基于一个被重构为 exfortiare 的俗拉丁动词，其词根为拉丁 fortis「强壮」。fortis 的更深来源尚无定论，年代均为约数。"},"items":[{"era":"LATIN FORTIS","en":"Fortis meant 'strong, mighty, firm'. Its deeper origin is uncertain; the link proposed to a root for 'height' or 'mountain' is a hypothesis, not a demonstrated derivation.","cn":"fortis 意为「强壮、有力、坚固」。其更深来源不确定；把它与表示「高度」或「山」的词根相联系的看法只是假说，并非已证实的派生。"},{"era":"VULGAR LATIN EXFORTIARE","en":"A spoken-Latin verb reconstructed as exfortiare 'to put forth strength' carried the root into the everyday speech of the late empire; the form is a reconstruction, not an attested word.","cn":"一个被重构为 exfortiare 的口语拉丁动词「使出力气」，把词根带入帝国晚期日常口语；这一形式属重构，并非有书证的词。"},{"era":"OLD FRENCH ESFORCIER","en":"Old French esforcier 'to force, strive, exert oneself' produced the noun esforz, which named both the strain and the try.","cn":"古法语 esforcier「用力、奋力、施展」产生名词 esforz，兼指那份紧张与那次尝试。"},{"era":"MIDDLE ENGLISH","en":"Middle English took the noun as effort in the fourteenth century, still close to the sense of a strong exertion of the will.","cn":"中古英语在十四世纪把这个名词吸收为 effort，仍贴近「意志强力施展」的意思。"},{"era":"TECHNICAL SENSE","en":"From the nineteenth century mechanics used effort for the applied force in a simple machine, set against the load it moves.","cn":"从十九世纪起，力学用这个词指简单机械中施加的力，与被移动的负载相对。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin of fortis and the exact spoken form): any Indo-European form offered for fortis is a reconstruction, and the earliest noun use has no securely dated citation.","cn":"来源不确定（fortis 的更深来源与那个口语形式的确切面貌）：凡为 fortis 给出的印欧语形式均为重构形式；这个名词最早用法也没有确切年代的出处。"}]},"similar":{"note":{"en":"Group one collects words that look like effort but come from other roots; group two collects near neighbours that measure exertion differently.","cn":"第一组是形近而异源的词；第二组是语义相近、但衡量「付出」方式不同的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"effortless","ipa":"/ˈefətləs/","tag":"same root, opposite","definition":"Its negation: work done without visible strain, so the strain is precisely what has vanished.","definitionCN":"该词的否定形式：不显费力的工作，消失的正是那份紧张。"},{"word":"comfort","ipa":"/ˈkʌmfət/","tag":"different root","definition":"Com- 'together' plus fortis: what strengthens someone, hence ease and consolation, not exertion.","definitionCN":"由 com-「共同」加 fortis 构成：使人强健之物，因此指舒适与安慰，而非付出。"},{"word":"fortify","ipa":"/ˈfɔːtɪfaɪ/","tag":"shares fortis","definition":"Fortis 'strong' plus facere 'to make': to make strong, as a wall or a body.","definitionCN":"由 fortis「强壮」加 facere「做」构成：使变强，如城墙或身体。"},{"word":"fortitude","ipa":"/ˈfɔːtɪtjuːd/","tag":"shares fortis","definition":"Strength of mind under pain or pressure; it names the capacity rather than its spending.","definitionCN":"痛苦或压力下心志的坚强；指那份能力，而不是它的耗费。"},{"word":"forfeit","ipa":"/ˈfɔːfɪt/","tag":"different root","definition":"From for- 'outside' plus a Germanic root for a fine: to lose something as a penalty, with no link to strength.","definitionCN":"由 for-「在外」加一个表示罚金的日耳曼词根构成：作为惩罚而失去某物，与「强壮」无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"work","ipa":"/wɜːk/","tag":"the labour itself","definition":"The activity of labouring, named by what is done rather than by the strain it costs.","definitionCN":"指劳动这项活动，以「做了什么」命名，而不以耗费多少力气命名。"},{"word":"exertion","ipa":"/ɪɡˈzɜːʃən/","tag":"formal strain","definition":"A formal word for strong physical or mental strain; effort is its everyday counterpart.","definitionCN":"表示强烈体力或脑力紧张的正式词；effort 是它日常的对应说法。"},{"word":"attempt","ipa":"/əˈtempt/","tag":"the try alone","definition":"A try at something, with the outcome unknown; it says nothing about how much energy was spent.","definitionCN":"对某事的尝试，结果未知；不含花费了多少力气之意。"},{"word":"endeavour","ipa":"/ɪnˈdevə/","tag":"elevated effort","definition":"A sustained, purposeful effort, often on something public or grand; it carries a formal tone.","definitionCN":"持久的、有目的的付出，多用于公共或宏大的事；语气正式。"},{"word":"labour","ipa":"/ˈleɪbə/","tag":"hard work, often manual","definition":"Hard physical work, especially of a manual or repetitive kind; it stresses the grind.","definitionCN":"艰苦的体力劳动，尤指手工或重复性工作；强调辛苦本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The root is Latin fortis 'strong', so effort is strength brought out and spent.","cn":"词根是拉丁 fortis「强壮」，因此这个词就是被使出来、被花掉的力气。"},{"en":"The family runs effort, effortless, effortful, effortlessly, effortlessness.","cn":"同族词覆盖名词、肯定与否定两个形容词、副词与抽象名词。"},{"en":"Fixed phrases mark the spending: make an effort, put effort into, spare no effort.","cn":"固定搭配标出这份耗费：作出努力、投入心力、不遗余力。"},{"en":"The technical use appears in the lever: effort acts on one arm, the load on the other.","cn":"技术义出现在杠杆里：施力作用于一端，负载作用于另一端。"},{"en":"Relatives outside the word still carry the same root: fortify, fortitude, comfort.","cn":"词外的同族词仍然带着同一词根：加固、坚毅、安慰。"}],"abstract":[{"en":"Picture a hand squeezing water out of a cloth until the drops stop.","cn":"想象一只手把布里的水拧出来，直到不再滴。"},{"en":"Picture a rope pulled taut between two posts, humming with the strain.","cn":"想象一根绳子在两根柱子之间被拉紧，绷得发出声。"},{"en":"Picture a candle burned down to a stub because it was kept lit all night.","cn":"想象一支蜡烛因为整夜点着，只剩下一小截。"}]},"examples":[{"en":"It took a full day of effort to clear the blocked channel.","cn":"清理这条堵塞的水道花了整整一天的力气。"},{"en":"The rescue effort involved boats, dogs and six villages.","cn":"这次救援行动动用了船只、犬只与六个村庄的人手。"},{"en":"A lever lets a small effort lift a heavy load.","cn":"杠杆使小小的作用力能抬起沉重的负载。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「一夫」推车——一个人使出全身力气推车 → 努力、费力","word":"effort"},"root":"古法语 esforz「力气、奋力」→ 俗拉丁重构形式 exfortiare「使出力气」→ 拉丁 fortis「强壮、有力」；fortis 更深来源不确定。","sensesIntro":{"en":"Eight senses follow one movement: strength is drawn out of a body, counted as a try, then read into the thing made, into the group that shares it, into the machine that measures it, into the size of the demand, into a whole nation's campaign and finally into the praise given to a losing attempt.","cn":"八个义项沿同一个动作展开：力气从身体里被抽出，先被数成一次尝试，再被读进做出的东西、共担的群体、量它的机械、需求的大小、举国的动员，最后读进给失败尝试的那份称许。"},"semanticMap":{"core":{"en":"CORE IMAGE: a body braced against a loaded cart, strength visibly leaving it and entering the work.","cn":"核心意象：一具身体抵着装满货物的车，力气看得见地从身体里流出，进入那件活里。"},"chain":["EXERT","SPEND","COUNT THE TRY","PRODUCE","SHARE","MEASURE"],"branches":[{"senses":"01 · 06","en":"THE SUPPLY AND ITS SIZE: energy itself, and the amount of it a task calls for.","cn":"储备与其分量：力气本身，以及一件事要调用多少。"},{"senses":"02 · 08","en":"THE COUNTED TRY: one attempt, and the same attempt judged generous even when it fails.","cn":"被数出的尝试：一次尝试，以及这次尝试即便落空也被评得宽厚。"},{"senses":"03","en":"THE THING MADE: labour can be read back out of the result.","cn":"做出的东西：劳动可以从成果里被读回来。"},{"senses":"04 · 07","en":"THE SHARED CAMPAIGN: many bodies push one aim, from a rescue to a whole nation.","cn":"共担的行动：许多身体推同一个目标，从一次救援到一个国家。"},{"senses":"05","en":"THE MEASURED FORCE: mechanics turns the body's push into a quantity on one arm of a lever.","cn":"被量住的力：力学把身体的推力化成一个落在杠杆一端的量。"}]},"affixes":{"intro":{"en":"Effort is a noun taken whole from Old French, so it has no live prefixes for English speakers; what grows from it are suffixes and a root that still builds other words.","cn":"这个词是从古法语整体借入的名词，对英语使用者来说没有可拆的活前缀；从它长出来的是后缀，以及一个仍在构成别的词的词根。"},"latinIntro":{"en":"Latin fortis 'strong' also gives fortify, fortitude and comfort; the suffix -less and -ful build the two opposite adjectives from the noun.","cn":"拉丁 fortis「强壮」还衍生出 fortify、fortitude 与 comfort；后缀 -less 与 -ful 从名词造出两个相反的形容词。"},"items":[{"word":"fortis","structure":"fortis (Latin adjective, 'strong, firm')","meaning":"strong; firm","meaningCN":"强壮的；坚固的","example":"The root supplies the sense of strength.","exampleCN":"这个词根提供「力量」的意思。"},{"word":"effort","structure":"Old French esforz, noun of esforcier","meaning":"exertion; a try","meaningCN":"用力；一次尝试","example":"The effort cost them a whole day.","exampleCN":"这份努力花了他们一整天。"},{"word":"effortful","structure":"effort + -ful (full of)","meaning":"requiring strain","meaningCN":"需要费力的","example":"An effortful climb ended at the ridge.","exampleCN":"一段费力的攀登在岭上结束。"},{"word":"effortfully","structure":"effortful + -ly (adverb)","meaning":"with visible strain","meaningCN":"费力地","example":"She breathed effortfully on the last stretch.","exampleCN":"最后一段她呼吸得很费力。"},{"word":"effortless","structure":"effort + -less (without)","meaning":"showing no strain","meaningCN":"不费力的","example":"His stroke looked effortless.","exampleCN":"他的划水看起来毫不费力。"},{"word":"effortlessly","structure":"effortless + -ly (adverb)","meaning":"without strain","meaningCN":"毫不费力地","example":"The glider rose effortlessly.","exampleCN":"滑翔机毫不费力地升了上去。"},{"word":"effortlessness","structure":"effortless + -ness (quality)","meaning":"the quality of seeming easy","meaningCN":"不费力这一特质","example":"The effortlessness was the result of years of drill.","exampleCN":"这种毫不费力是多年苦练的结果。"},{"word":"fortify","structure":"fortis + facere (to make)","meaning":"to make strong","meaningCN":"使坚固；增强","example":"They fortified the bank against the current.","exampleCN":"他们加固了堤岸以抗水流。"},{"word":"fortitude","structure":"fortis + -tudo (noun of quality)","meaning":"strength of mind","meaningCN":"坚毅","example":"She met the loss with fortitude.","exampleCN":"她以坚毅面对这次损失。"},{"word":"comfort","structure":"com- + fortis","meaning":"that which strengthens","meaningCN":"使人强健之物；安慰","example":"The blanket gave the child comfort.","exampleCN":"这条毯子给了孩子安慰。"}],"latinEntries":[{"word":"fortis","structure":"fortis, forte (adjective, third declension)","meaning":"strong, firm, brave","meaningCN":"强壮的；坚固的；勇敢的"},{"word":"fortitudo","structure":"fortitudo, fortitudinis (f., third declension)","meaning":"strength, courage","meaningCN":"力量；勇气"},{"word":"exfortiare","structure":"exfortiare (reconstructed Vulgar Latin verb, first conjugation)","meaning":"to put forth strength","meaningCN":"使出力气"}]}},{"word":"endeavor","ipa_uk":"/ɪnˈdev.ər/","ipa_us":"/ɪnˈdev.ɚ/","definition_zh":"努力；认真而持续的尝试；一项事业；尽力去做","definition_en":"a serious and determined attempt, or to try hard to achieve something","core_image":"一个人独自把一块大石往山顶推，每推一段就用绳子把石头拴在树上歇口气","scene":"为了让村里的孩子有书读，几位老师花了七年筹钱建起一间图书室。The whole endeavor began with a borrowed shelf and forty books.","sceneCN":"这里 endeavor 指「认真而持续的一项事业」（第 2 个义项：需要长期投入的工程）；句意为这整桩事业是从一只借来的书架和四十本书开始的。图中可辨识物件：山顶的大石、拴石的绳子、借来的木架、摊开的书。","pos":[{"tag":"n.","zh":"努力；认真的尝试；事业；工程"},{"tag":"vi.","zh":"努力；尽力（后接不定式）"}],"collocations":[{"phrase":"a joint endeavor","zh":"共同的努力；合作事业"},{"phrase":"scientific endeavor","zh":"科学探索事业"},{"phrase":"endeavor to do","zh":"努力去做"},{"phrase":"a worthwhile endeavor","zh":"值得一做的事业"},{"phrase":"human endeavor","zh":"人类的探索与奋斗"},{"phrase":"in an endeavor to","zh":"为了努力做到……"}],"forms":[{"label":"单数","form":"endeavor"},{"label":"复数","form":"endeavors"},{"label":"三单（he/she/it）","form":"endeavors"},{"label":"过去式","form":"endeavored"},{"label":"过去分词","form":"endeavored"},{"label":"现在分词","form":"endeavoring"},{"label":"英式拼写","form":"endeavour"}],"derivatives":[{"word":"endeavoring","pos":"adj./n.","zh":"由动词加现在分词后缀构成，语义由「努力去做」转为「正在努力的」"},{"word":"endeavorer","pos":"n.","zh":"在动词后加表示施动者的名词后缀构成，语义由「努力」转为「努力做事的人」"},{"word":"endeavour","pos":"n./v.","zh":"英式拼写变体，语义与美式形式完全相同，仅地域书写习惯不同"}],"senses":[{"no":"01","title":"A sustained serious attempt","titleCN":"认真而持续的尝试","definition":"an attempt that is carried on with care and persistence rather than made once and dropped","definitionCN":"以认真与持久的方式进行的尝试，而非只做一次就放下","example":"Rescuing the stranded climbers was a long endeavor in bad weather.","exampleCN":"在恶劣天气里营救被困登山者，是一次漫长的努力。","why":"the word began as the phrase in duty, so an endeavor carries a sense of obligation: the attempt is owed, not merely wanted.","whyCN":"这个词最初是「在义务之中」的意思，因此一次努力带着义务感：这件事是欠着的，不只是想要做的。"},{"no":"02","title":"An undertaking or enterprise","titleCN":"一项事业、一桩工程","definition":"a project or line of work that people commit themselves to over time","definitionCN":"人们长期投入的工程或工作方向","example":"The whole endeavor began with a borrowed shelf and forty books.","exampleCN":"这整桩事业是从一只借来的书架和四十本书开始的。","why":"once an attempt is large enough to organize people and resources, the noun shifts from the try to the thing being built.","whyCN":"当一次尝试大到要组织人与资源，名词就从「那次尝试」转向「正在建起的东西」。"},{"no":"03","title":"Organized collective work","titleCN":"有组织的集体探索","definition":"the shared work of a group, a field or a society aimed at advancing knowledge or conditions","definitionCN":"一个群体、一个领域或一个社会为推动知识或境况而共同从事的工作","example":"Space flight is the costliest endeavor our species has attempted.","exampleCN":"太空飞行是我们的物种尝试过的最昂贵的集体事业。","why":"duty shared by many becomes an enterprise with an institution behind it, which is why the word suits science and exploration.","whyCN":"义务被许多人分担，就变成有机构支撑的事业，因此这个词适合科学与探索。"},{"no":"04","title":"A lifelong pursuit","titleCN":"一生的志业","definition":"the main work or cause to which a person gives a whole life","definitionCN":"一个人倾其一生的主要工作或志业","example":"Teaching the deaf was her life's endeavor.","exampleCN":"教聋童读书是她一生的志业。","why":"the note of duty reaches its height here: the work is not a task but a calling that owns the person.","whyCN":"义务感在这里达到顶点：这活不是一项任务，而是占有一个人的召唤。"},{"no":"05","title":"To try earnestly","titleCN":"尽力去做（较正式的动词用法）","definition":"to make an earnest attempt at something, often in a formal or polite register","definitionCN":"认真地尝试做某事，常用于正式或客气的语域","example":"We endeavor to answer every letter within a week.","exampleCN":"我们尽力在一周内回复每一封信。","why":"as a verb the word keeps the same duty: the attempt is presented as something one owes to the other party.","whyCN":"作动词时仍是同一份义务：这次尝试被呈现为对另一方所欠之事。"},{"no":"06","title":"Strive against difficulty","titleCN":"顶着困难奋力争取","definition":"to struggle toward a goal while obstacles are actively in the way","definitionCN":"在障碍实际挡路时，仍朝着目标挣扎前行","example":"The engineers endeavored to keep the line open through the storm.","exampleCN":"工程师奋力使线路在风暴中保持通畅。","why":"effort that meets resistance is the original picture: the stone is heavy, but it is still pushed uphill.","whyCN":"遇到阻力的努力才是原初图景：石头很重，却仍被往山上推。"},{"no":"07","title":"A demanding long task","titleCN":"需要长期投入的艰巨任务","definition":"a task that demands prolonged commitment before any result shows","definitionCN":"在见到任何结果之前就要求长久投入的任务","example":"Restoring the salt marsh was a twenty-year endeavor.","exampleCN":"恢复这片盐沼是一项耗时二十年的艰巨任务。","why":"duration is the measure here: the work is named by the years it swallows, not by any single push.","whyCN":"这里的尺度是时间：这项活以它吞掉的年头来命名，而不是以某一次推力。"},{"no":"08","title":"An attempt judged worthy","titleCN":"值得敬重的一次尝试（不论成败）","definition":"an attempt praised for its seriousness even when it does not reach its aim","definitionCN":"即使没有达到目标，也因其认真而受到称许的一次尝试","example":"The failed vaccine trial was still a noble endeavor.","exampleCN":"那次失败的疫苗试验仍是一次高尚的努力。","why":"because duty is what is measured, an attempt can be honoured even when its result is nothing.","whyCN":"因为衡量的对象是义务，所以一次尝试即便毫无结果，也可以受到敬重。"}],"etymology":{"intro":{"en":"Endeavor comes from the Middle English phrase in dever 'in duty', from Old French devoir 'duty', which rests on Latin debere 'to owe', built on de- 'from' and habere 'to have'. The deeper origin of habere is not settled. Dates are approximate.","cn":"该词来自中古英语短语 in dever「在义务之中」，其源头是古法语 devoir「义务」，再上溯到拉丁 debere「欠、应尽」，由 de-「自」与 habere「持有」构成。habere 的更深来源尚无定论，年代均为约数。"},"items":[{"era":"LATIN HABERE","en":"Habere meant 'to have, to hold'. Its deeper origin is uncertain; the link sometimes proposed to a root for 'to grasp' is a hypothesis rather than a demonstrated derivation.","cn":"habere 意为「拥有、持有」。其更深来源不确定；有人把它与表示「抓握」的词根相联系，那只是假说，并非已证实的派生。"},{"era":"LATIN DEBERE","en":"De- 'from' plus habere produced debere 'to owe, to be under obligation', literally to have something taken from oneself toward another.","cn":"de-「自」加 habere 构成 debere「欠、负有义务」，字面意思是「有东西须从自己这里取走交给别人」。"},{"era":"OLD FRENCH DEVOIR","en":"Old French devoir 'duty, that which is owed' carried the obligation into everyday use, and the phrase in dever was built from it.","cn":"古法语 devoir「义务、所欠之物」把这份义务带入日常使用，短语 in dever 即由此构成。"},{"era":"MIDDLE ENGLISH","en":"Middle English speakers heard in dever as one word and reshaped it into the verb and noun endeavor, keeping the sense of putting oneself to a duty.","cn":"中古英语使用者把 in dever 听成一个词，并改造成动词与名词形式，保留了「把自己放到义务上」的意思。"},{"era":"MODERN USE","en":"By the eighteenth century the word had widened from a moral duty to any serious attempt or enterprise, and the American spelling dropped the u.","cn":"到十八世纪，这个词从道德义务扩展到任何认真的尝试或事业，美式拼写则省去了字母 u。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin of habere, exact date of the reshaping): no precise first citation is recorded for the modern business sense, and any Indo-European form offered for habere is a reconstruction.","cn":"来源不确定（habere 的更深来源与词形整合的确切年代）：现代「事业」义没有确切的最早书证；凡为 habere 给出的印欧语形式均属重构形式。"}]},"similar":{"note":{"en":"Group one separates words that resemble endeavor but rest on another root; group two separates near synonyms by what they measure.","cn":"第一组区分形近而异源的词；第二组按衡量的对象区分近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"endeavour","ipa":"/ɪnˈdevə/","tag":"spelling variant","definition":"The British spelling of the same word, with no difference in meaning or pronunciation beyond the vowel ending.","definitionCN":"同一个词的英式拼写，除词尾元音读法外，意义与读音没有差别。"},{"word":"devoir","ipa":"/deˈvwɑː/","tag":"the French source","definition":"The French noun for duty or an act of courtesy; it is the ancestor rather than a rival of endeavor.","definitionCN":"法语中表示义务或礼貌之举的名词；它是该词的祖先，而不是竞争对手。"},{"word":"debt","ipa":"/det/","tag":"shares the root","definition":"From Latin debitum 'something owed', the same debere behind duty: a sum one is obliged to pay.","definitionCN":"来自拉丁 debitum「所欠之物」，与 duty 同出 debere：一笔必须偿付的款。"},{"word":"debit","ipa":"/ˈdebɪt/","tag":"shares the root","definition":"The accounting entry for what is owed or taken out, again from debitum, with the silent obligation made numeric.","definitionCN":"账目上表示欠下或支出的记录，同样出自 debitum，把那笔义务变成了数字。"},{"word":"devote","ipa":"/dɪˈvəʊt/","tag":"different root","definition":"From de- plus vovere 'to vow': to set something apart by a vow, which is dedication rather than duty.","definitionCN":"由 de- 加 vovere「发誓」构成：以誓言把某物划归专用，说的是奉献，而非义务。"}]},{"heading":"NEAR MEANING","entries":[{"word":"effort","ipa":"/ˈefət/","tag":"the energy spent","definition":"Names the strength used; endeavor names the duty-bound attempt that spends it.","definitionCN":"指投入的力气；而该词指那份带着义务感的尝试，是它花掉了力气。"},{"word":"attempt","ipa":"/əˈtempt/","tag":"neutral try","definition":"A plain try whose outcome is still open; it carries no note of duty or scale.","definitionCN":"平实的尝试，结果尚未分晓；不带义务感或规模感。"},{"word":"enterprise","ipa":"/ˈentəpraɪz/","tag":"the project itself","definition":"A large project or business venture; it names the structure, while endeavor names the commitment inside it.","definitionCN":"大型项目或商业事业；指那套结构，而该词指其中的投入。"},{"word":"venture","ipa":"/ˈventʃə/","tag":"risk attached","definition":"An undertaking that carries risk of loss; endeavor has no such commercial edge.","definitionCN":"带有损失风险的举动；该词没有这层商业意味。"},{"word":"strive","ipa":"/straɪv/","tag":"the verb of struggle","definition":"To struggle hard toward something; it is the plain verb that endeavor often replaces in formal prose.","definitionCN":"朝某目标奋力挣扎；在正式文章里，常被该词替换的正是这个平实动词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The word grew out of the phrase in duty, so an endeavor is a task one feels owed to finish.","cn":"这个词从「在义务之中」长出来，因此一次努力是一件让人觉得欠着必须做完的事。"},{"en":"The family runs endeavor, endeavors, endeavored, endeavoring, endeavorer.","cn":"同族词覆盖单复数名词、三个动词形态与施动者名词。"},{"en":"Fixed phrases mark the scale: a joint endeavor, scientific endeavor, human endeavor.","cn":"固定搭配标出规模：共同的努力、科学事业、人类的奋斗。"},{"en":"The Latin ancestor of duty and debt is the same verb meaning to owe, which is why effort here feels obligatory.","cn":"duty 与 debt 的拉丁祖先同为「欠」这个动词，这就是为什么这里的努力带着必须做的味道。"},{"en":"The formal verb pattern is endeavor to do, as in we endeavor to reply within a week.","cn":"正式动词句式为「努力去做」，如「我们尽力在一周内回复」。"}],"abstract":[{"en":"Picture a rope tied to a boulder so the climb can be resumed after rest.","cn":"想象一根绳子把巨石拴住，好让人歇过之后继续往上推。"},{"en":"Picture a lamp left burning in a window for years because someone must keep watch.","cn":"想象一盏灯在窗里亮了多年，因为总得有人守着。"},{"en":"Picture a signature at the bottom of a promise that took a lifetime to keep.","cn":"想象一个签名落在一份要用一生去兑现的承诺末尾。"}]},"examples":[{"en":"They endeavored to keep the archive dry through the monsoon.","cn":"他们尽力让档案在季风季节保持干燥。"},{"en":"The mapping endeavor took three generations of surveyors.","cn":"这项测绘事业用了三代测量员。"},{"en":"Every endeavor to reopen the mine failed on the same rock layer.","cn":"每一次重开矿井的尝试都在同一层岩石上失败。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「in 得我」——在心里觉得「这事得我做」，于是认真去做 → 努力、事业","word":"endeavor"},"root":"中古英语 in dever「在义务中」→ 古法语 devoir「义务」→ 拉丁 debere「欠、应尽」= de-（自）+ habere（持有）；habere 更深来源不确定。","sensesIntro":{"en":"Eight senses follow one line: a duty is taken up, it grows into a project, then into shared work and finally into a life's calling; from there the word turns into the verb of trying and ends as praise for an attempt that did not land.","cn":"八个义项沿一条线展开：先把一份义务接过来，它长成工程，再长成共同的探索，最后长成一生志业；由此这个词又转为「尽力去做」的动词，最后成为对未竟尝试的称许。"},"semanticMap":{"core":{"en":"CORE IMAGE: a person tied to a heavy stone by duty, resting, then pushing again.","cn":"核心意象：一个人被义务拴在巨石上，歇一歇，再推一次。"},"chain":["TAKE UP A DUTY","TRY WITH CARE","GROW INTO A PROJECT","SHARE THE WORK","DEVOTE A LIFE","JUDGE THE TRY"],"branches":[{"senses":"01 · 05","en":"THE DUTY AND THE TRY: the same obligation appears as a noun and as a verb of earnest attempt.","cn":"义务与尝试：同一份义务，一个以名词出现，一个以认真尝试的动词出现。"},{"senses":"02 · 03","en":"FROM TRY TO STRUCTURE: one person's commitment becomes a project, then an institution.","cn":"从尝试到结构：一个人的投入变成一项工程，再变成一个机构。"},{"senses":"04","en":"A WHOLE LIFE: the duty grows until it owns the person who carries it.","cn":"整整一生：义务一直长，直到它占有了背着它的人。"},{"senses":"06","en":"RESISTANCE MET: the stone is heavy and still goes uphill.","cn":"遇上阻力：石头很重，却仍往山上去。"},{"senses":"07 · 08","en":"MEASURED BY YEARS, THEN BY WORTH: the work is counted in time, and the try is counted in honour.","cn":"先以年头计，再以价值计：这项活按时间算，这次尝试按体面算。"}]},"affixes":{"intro":{"en":"Endeavor is a whole phrase reshaped into one word, so its history sits inside it; what English adds are suffixes of person and participle.","cn":"这个词由一整个短语压成一个词，历史就藏在词里；英语在其上加的是表示人与分词的后缀。"},"latinIntro":{"en":"Latin habere 'to have' also gives habit, exhibit and inhibit; debere gives debt and debit, which keep the sense of what is owed.","cn":"拉丁 habere「持有」还衍生出 habit、exhibit 与 inhibit；debere 衍生出 debt 与 debit，保留了「所欠」的意思。"},"items":[{"word":"de-","structure":"de- (Latin prefix, 'from, away')","meaning":"from; away","meaningCN":"自；离开","example":"The prefix marks what is taken from one side.","exampleCN":"这个前缀标出从一方取走的东西。"},{"word":"habere","structure":"habere (Latin verb, 'to have, hold')","meaning":"to have; to hold","meaningCN":"拥有；持有","example":"The root supplies the idea of holding.","exampleCN":"这个词根提供「持有」的意思。"},{"word":"debere","structure":"de- + habere","meaning":"to owe, be obliged","meaningCN":"欠；负有义务","example":"What is held from another is owed to another.","exampleCN":"从别人那里拿着的，就是欠别人的。"},{"word":"endeavor","structure":"in + dever, from devoir (duty)","meaning":"to put oneself to a duty","meaningCN":"把自己放到义务上；努力","example":"They endeavor to finish by winter.","exampleCN":"他们尽力在冬天前完成。"},{"word":"endeavored","structure":"endeavor + -ed (past tense)","meaning":"tried earnestly in the past","meaningCN":"过去认真地尝试过","example":"She endeavored to hide her disappointment.","exampleCN":"她努力掩藏失望。"},{"word":"endeavoring","structure":"endeavor + -ing (participle)","meaning":"in the middle of trying","meaningCN":"正在努力之中","example":"The crew is endeavoring to clear the pass.","exampleCN":"工人们正努力清开山口。"},{"word":"endeavorer","structure":"endeavor + -er (person who acts)","meaning":"one who tries hard","meaningCN":"努力做事的人","example":"Every endeavorer needs a rest day.","exampleCN":"每个努力做事的人都需要休息日。"},{"word":"debt","structure":"debitum, past participle of debere","meaning":"what is owed","meaningCN":"所欠的债","example":"The debt was repaid in full.","exampleCN":"这笔债已全额偿还。"},{"word":"duty","structure":"Old French deu, past participle of devoir","meaning":"what one ought to do","meaningCN":"应尽之事；义务","example":"The night watch is a duty, not a choice.","exampleCN":"守夜是一项义务，不是选择。"},{"word":"devoir","structure":"Old French devoir, from debere","meaning":"duty; an act of courtesy","meaningCN":"义务；礼貌之举","example":"He paid his devoirs to the host.","exampleCN":"他向主人尽了礼数。"}],"latinEntries":[{"word":"habere","structure":"habere, habui, habitum (verb, second conjugation)","meaning":"to have, hold","meaningCN":"拥有；持有"},{"word":"debere","structure":"debere, debui, debitum (verb, second conjugation)","meaning":"to owe, be under obligation","meaningCN":"欠；负有义务"},{"word":"debitum","structure":"debitum, debiti (n., second declension)","meaning":"a debt, that which is owed","meaningCN":"债务；所欠之物"},{"word":"devotio","structure":"devotio, devotionis (f., third declension)","meaning":"a vow, dedication","meaningCN":"誓愿；奉献"}]}},{"word":"accomplishment","ipa_uk":"/əˈkʌm.plɪʃ.mənt/","ipa_us":"/əˈkɑːm.plɪʃ.mənt/","definition_zh":"完成；取得的成果；值得称道的成就；才艺素养","definition_en":"something that has been done successfully, especially after effort, or the act of completing it","core_image":"最后一块石砖被放进拱顶中央，脚手架开始一层层拆下，整座门廊终于合拢","scene":"图纸上的礼堂修了四年，最后一块拱顶石落位那天，工匠们把脚手架拆了下来。Finishing the vault was the accomplishment everyone had worked toward.","sceneCN":"这里 accomplishment 指「经过努力做成的具体成果」（第 2 个义项：已完成的成就）；句意为把拱顶封好是所有人一直努力要完成的成果。图中可辨识物件：落位的拱顶石、正在拆除的脚手架、合拢的门廊、卷起的图纸。","pos":[{"tag":"n.","zh":"完成；成就；成果；才艺"}],"collocations":[{"phrase":"a major accomplishment","zh":"一项重大成就"},{"phrase":"a sense of accomplishment","zh":"成就感"},{"phrase":"proud of one's accomplishments","zh":"为自己的成就自豪"},{"phrase":"accomplishment of a goal","zh":"目标的达成"},{"phrase":"artistic accomplishments","zh":"艺术方面的才艺"},{"phrase":"record one's accomplishments","zh":"记录个人成就"}],"forms":[{"label":"单数","form":"accomplishment"},{"label":"复数","form":"accomplishments"},{"label":"动词","form":"accomplish"},{"label":"动词三单","form":"accomplishes"},{"label":"动词过去式","form":"accomplished"},{"label":"动词现在分词","form":"accomplishing"},{"label":"形容词（有造诣的）","form":"accomplished"}],"derivatives":[{"word":"accomplish","pos":"v.","zh":"基础动词，来自拉丁语「把东西填满」，语义为「完成、实现」"},{"word":"accomplished","pos":"adj.","zh":"由过去分词转为形容词，语义由「已完成」转为「技艺娴熟、有造诣的」"},{"word":"accomplishable","pos":"adj.","zh":"在动词后加表示「可以」的形容词后缀构成，语义由「完成」转为「可完成的」"},{"word":"unaccomplished","pos":"adj.","zh":"加否定前缀构成，语义由「已完成」转为「未完成的」"},{"word":"accomplisher","pos":"n.","zh":"在动词后加表示施动者的名词后缀构成，语义由「完成」转为「完成者」"}],"senses":[{"no":"01","title":"The act of completing","titleCN":"完成某个任务的行为","definition":"the act of finishing a task or bringing a plan to its end","definitionCN":"把一项任务做完，或把一个计划推进到终点的行为","example":"The accomplishment of the bridge took eleven years.","exampleCN":"这座桥的建成分外用了十一年。","why":"accomplish rests on Latin complere 'to fill up', so the noun names the moment when a thing is filled out and complete.","whyCN":"其动词词根意为「填满」，因此这个名词指向某物被填满、变得完整的那一刻。"},{"no":"02","title":"A completed result","titleCN":"已经做成的成果","definition":"a concrete thing or outcome that now exists because the work is done","definitionCN":"因为工作做完而如今确实存在的具体产物或结果","example":"Finishing the vault was the accomplishment everyone had worked toward.","exampleCN":"把拱顶封好，是所有人一直努力要完成的成果。","why":"the same filling-up can be looked at as a thing rather than a moment, and then the noun means the finished object.","whyCN":"同一个「填满」的动作，可以看作一件事物而不是一个时刻，此时名词就指做成的成品。"},{"no":"03","title":"A notable achievement","titleCN":"值得称道的成就","definition":"an achievement that is worth naming with pride, usually one that took real difficulty","definitionCN":"值得带着自豪说出的成就，通常来之不易","example":"Learning to read at sixty was her proudest accomplishment.","exampleCN":"六十岁学会读书，是她最自豪的成就。","why":"once a result is hard-won, the word takes on a social shine, and people list their accomplishments as proof of worth.","whyCN":"一旦成果来之不易，这个词就带上了社会光彩，人们会把成就列举出来作为自身价值的凭据。"},{"no":"04","title":"A cultivated skill","titleCN":"修养出来的才艺","definition":"a skill in music, language or manners that has been polished through training","definitionCN":"经过训练打磨的音乐、语言或礼仪方面的技能","example":"Her accomplishments included the violin and three languages.","exampleCN":"她的才艺包括小提琴和三门语言。","why":"the sense of completing something applied to a person's education: a finished skill is one that has been filled out by practice.","whyCN":"「完成」的意思被用到人的教养上：一项完成的技艺，就是被练习填满的技艺。"},{"no":"05","title":"The state of having attained","titleCN":"达到目标后的状态","definition":"the condition of having reached an aim, seen as a standing rather than an event","definitionCN":"已经抵达目标的那种处境，被看作一种状态而非一次事件","example":"There was quiet accomplishment in the room after the vote passed.","exampleCN":"表决通过后，屋里弥漫着一种安静的达成感。","why":"a completed act leaves a settled state behind it, and English lets the noun name that state as well.","whyCN":"完成的行为会在身后留下一种定了的状态，英语允许这个名词也指那种状态。"},{"no":"06","title":"Fulfilment of an obligation","titleCN":"对义务或承诺的履行完毕","definition":"the carrying out of a duty, promise or requirement to the full","definitionCN":"把义务、承诺或要求完整地执行到底","example":"Accomplishment of the treaty terms fell to the incoming minister.","exampleCN":"履行条约条款的担子落到了新上任的部长身上。","why":"Latin complere was used for fulfilling a duty, and law and diplomacy kept that precise use.","whyCN":"拉丁语中「填满」一词本来也用于履行义务，法律与外交保存了这一精确用法。"},{"no":"07","title":"A recorded attainment","titleCN":"被记下的一项具体成绩","definition":"a concrete item on a record of study or work, countable and verifiable","definitionCN":"学习或工作记录上一条具体、可数、可核对的成绩","example":"The file lists each accomplishment with a date beside it.","exampleCN":"档案里每条成绩旁边都标着日期。","why":"institutions turn achievements into countable entries, and the plural then means the list rather than any one deed.","whyCN":"机构把成就变成可数的条目，复数形式于是指那份清单，而不是任何一件具体的事。"},{"no":"08","title":"Full realization of a design","titleCN":"设计被完整实现的程度","definition":"the degree to which an idea or design has been fully realized in fact","definitionCN":"一个想法或设计在事实上被完整实现的程度","example":"The building is judged by the accomplishment of its plan, not its size.","exampleCN":"评判这座建筑看的是它的设计实现得如何，而不是它的体量。","why":"here the filling-up is abstract: the question is whether the plan has been filled out by the building.","whyCN":"这里的「填满」是抽象的：问题在于建筑设计是否被实物填满。"}],"etymology":{"intro":{"en":"Accomplishment derives from the verb accomplish, which comes through Old French acomplir from Latin ad- 'to' plus complere 'to fill up', itself com- 'together, completely' plus plere 'to fill'. The deeper origin of plere is not settled. Dates are approximate.","cn":"该词来自动词 accomplish，后者经古法语 acomplir 上溯到拉丁 ad-「向」加 complere「填满」，而 complere 又由 com-「共同、完全」与 plere「填」构成。plere 的更深来源尚无定论，年代均为约数。"},"items":[{"era":"LATIN PLERE","en":"Plere meant 'to fill'. Its deeper origin is uncertain; the comparison with a root for 'full' is a hypothesis rather than a demonstrated derivation.","cn":"plere 意为「填满」。其更深来源不确定；把它与表示「满」的词根相比对，那只是假说，并非已证实的派生。"},{"era":"LATIN COMPLERE","en":"Com- 'completely' plus plere gave complere 'to fill up, to make whole, to fulfil', the verb behind complete and complement as well.","cn":"com-「完全」加 plere 构成 complere「填满、使完整、履行」，也是 complete 与 complement 的源头。"},{"era":"LATIN AD-","en":"Ad- 'to, toward' was added to mark the direction of the filling: the work is filled up to its intended end.","cn":"前缀 ad-「向」标出填充的方向：工作被填到它应该抵达的终点。"},{"era":"OLD FRENCH ACOMPLIR","en":"Old French acomplir 'to fulfil, finish' carried the verb into English, and the noun suffix -ment was added inside English.","cn":"古法语 acomplir「履行、完成」把这个动词带入英语，名词后缀则是在英语内部加上去的。"},{"era":"SOCIAL SENSE","en":"From the seventeenth century accomplishments meant the polished skills of an educated person, a use that survives in talk of a person's accomplishments.","cn":"从十七世纪起，复数形式指受过教育者打磨过的才艺，这一用法至今仍见于谈论某人的各项所长。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin of plere): no exact first citation is recorded for the modern sense of a notable achievement, and any Indo-European form offered for plere is a reconstruction.","cn":"来源不确定（plere 的更深来源）：现代「显著成就」义没有确切的最早书证；凡为 plere 给出的印欧语形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds look-alikes whose root splits into two different families; group two holds near synonyms that measure success differently.","cn":"第一组是形近、但词根分属两条不同脉络的词；第二组是按衡量成功方式区分近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"compliment","ipa":"/ˈkɒmplɪmənt/","tag":"same root, other path","definition":"Praise given politely; it came through Italian and French courtesy rather than through the filling-up verb, so it means flattery, not completion.","definitionCN":"礼貌给出的称赞；它经意大利语与法语中的礼节用法而来，不走「填满」那条线，因此指恭维而非完成。"},{"word":"complement","ipa":"/ˈkɒmplɪmənt/","tag":"same root, the filling one","definition":"That which completes a whole by filling what is missing; this is the direct relative of the filling-up verb.","definitionCN":"补足所缺而使整体完整之物；它是「填满」那个动词的直接同族词。"},{"word":"accomplished","ipa":"/əˈkʌmplɪʃt/","tag":"participle turned adjective","definition":"Highly skilled through training; the finished work has become a personal quality.","definitionCN":"经训练而技艺高超的；完成的功夫变成了人的品质。"},{"word":"complete","ipa":"/kəmˈpliːt/","tag":"shares complere","definition":"Whole, with nothing missing; it states the result, while accomplishment names the deed or the thing done.","definitionCN":"完整、无所缺；它陈述结果，而该词指那件事或做成的东西。"},{"word":"comply","ipa":"/kəmˈplaɪ/","tag":"same root, obedience","definition":"To obey a rule or request; from the same filling-up verb, but the filling is of a requirement.","definitionCN":"服从规则或请求；同出「填满」那个动词，只是被填满的是一项要求。"}]},{"heading":"NEAR MEANING","entries":[{"word":"achievement","ipa":"/əˈtʃiːvmənt/","tag":"success by effort","definition":"Something reached by effort, especially against obstacles; it stresses the reaching rather than the finishing.","definitionCN":"靠努力尤其顶着障碍达到的事；强调「达到」，而非「做完」。"},{"word":"attainment","ipa":"/əˈteɪnmənt/","tag":"formal reached level","definition":"The reaching of a standard or level, often in education; it is cooler and more official than accomplishment.","definitionCN":"达到某个标准或水平，多用于教育；比该词更冷静、更官方。"},{"word":"feat","ipa":"/fiːt/","tag":"single striking deed","definition":"One impressive act requiring skill or daring; it is singular and dramatic, unlike a long accomplishment.","definitionCN":"一次需要技巧或胆量的惊人举动；单次而戏剧化，不同于长期的成就。"},{"word":"deed","ipa":"/diːd/","tag":"what was done","definition":"A thing done, judged morally rather than technically; it reports the act without weighing its difficulty.","definitionCN":"做过的一件事，多按道德而非技术来评判；只报告行为，不衡量难度。"},{"word":"success","ipa":"/səkˈses/","tag":"favourable outcome","definition":"The favourable outcome of an attempt; it names the result, while accomplishment names the completed work.","definitionCN":"尝试获得的有利结果；指结果，而该词指完成的工作本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The root means to fill up: a task is accomplished when nothing is left missing.","cn":"词根意思是「填满」：一件事被填得不再缺任何东西，就是完成了。"},{"en":"The family runs accomplish, accomplished, accomplishment, accomplishable, accomplisher.","cn":"同族词覆盖动词、形容词、名词、可能式形容词与施动者名词。"},{"en":"Fixed phrases mark the pride: a major accomplishment, a sense of accomplishment, proud of one's accomplishments.","cn":"固定搭配标出自豪：重大成就、成就感、为自己的成就自豪。"},{"en":"The polite word compliment went through courtesy, not through filling, which is why it never means completion.","cn":"表示礼貌称赞的那个形近词走的是礼节之路，而不是「填满」之路，所以它从不表示完成。"},{"en":"The plural is the résumé sense: accomplishments are the entries one lists.","cn":"复数形式是履历义：成就就是一条条列出来的项目。"}],"abstract":[{"en":"Picture the keystone sliding into place and all the scaffolding coming down.","cn":"想象拱顶石滑进位置，所有脚手架被拆下。"},{"en":"Picture a jar filled to the brim so that not one grain more will fit.","cn":"想象一只罐子满到罐口，再多一粒都装不进。"},{"en":"Picture a signature on the last page of a long report, written slowly.","cn":"想象一份长报告最后一页上的签名，写得很慢。"}]},"examples":[{"en":"The restoration of the organ counts as a remarkable accomplishment.","cn":"这台管风琴的修复算得上一项了不起的成就。"},{"en":"He felt a quiet sense of accomplishment after the last exam was graded.","cn":"最后一门考试批完后，他心里有一种安静的成就感。"},{"en":"Accomplishment of the plan depended on one small supplier.","cn":"这个计划能否完成，取决于一家小供应商。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「a 块砖，com 一起，plish 拼上」——把砖一块块拼到位，事情就完成了 → 成就","word":"accomplishment"},"root":"拉丁 ad-（向）+ complere「填满」= com-（完全）+ plere「填」；plere 更深来源不确定。英语 accomplish + -ment。","sensesIntro":{"en":"Eight senses follow one filling-up: a task is filled to its end, the filled thing remains, then pride turns it into an achievement, education turns it into a skill, law turns it into a fulfilled duty and the record turns it into an entry.","cn":"八个义项沿一次「填满」展开：任务被填到终点，填成的东西留了下来，自豪把它变成成就，教养把它变成才艺，法律把它变成履行的义务，档案把它变成一条记录。"},"semanticMap":{"core":{"en":"CORE IMAGE: a last stone closing an arch, with nothing left unfilled.","cn":"核心意象：最后一块石头把拱门合拢，再没有未填之处。"},"chain":["FILL","COMPLETE THE ACT","LEAVE A RESULT","TAKE PRIDE","POLISH A SKILL","RECORD IT"],"branches":[{"senses":"01 · 02","en":"THE MOMENT AND THE THING: the same filling seen as an event and as its product.","cn":"时刻与实物：同一次填满，一处看作事件，一处看作产物。"},{"senses":"03 · 05","en":"PRIDE AND SETTLED STATE: a hard-won result leaves a standing behind it.","cn":"自豪与既定状态：来之不易的结果在身后留下一种处境。"},{"senses":"04","en":"POLISHED SKILL: training fills out a person rather than a task.","cn":"打磨过的技艺：训练填满的是人，而不是任务。"},{"senses":"06","en":"OBLIGATION FILLED: what gets filled is a duty or a promise.","cn":"被填满的义务：填的是一项义务或承诺。"},{"senses":"07 · 08","en":"COUNTED AND REALIZED: entries in a file, and a design made actual in stone.","cn":"被计数与被实现：档案里的条目，以及被石头落实的设计。"}]},"affixes":{"intro":{"en":"The word is a Latin verb with a prepositional prefix plus a suffix added in English, so both halves read clearly.","cn":"这个词是一个带介词前缀的拉丁动词，再在英语中加后缀，两半都读得很清楚。"},"latinIntro":{"en":"Latin plere 'to fill' gives complete, complement, supplement and deplete; ad- 'to' appears in adapt, adhere and adjacent.","cn":"拉丁 plere「填」衍生出 complete、complement、supplement 与 deplete；ad-「向」见于 adapt、adhere 与 adjacent。"},"items":[{"word":"ad-","structure":"ad- (Latin prefix, 'to, toward')","meaning":"to; toward","meaningCN":"向；朝","example":"The prefix points the action at its end.","exampleCN":"这个前缀把动作指向它的终点。"},{"word":"plere","structure":"plere (Latin verb, 'to fill')","meaning":"to fill","meaningCN":"填满","example":"The root carries the sense of filling.","exampleCN":"这个词根带着「填」的意思。"},{"word":"complere","structure":"com- + plere","meaning":"to fill up, make whole","meaningCN":"填满；使完整","example":"The cistern was filled to the brim before dawn.","exampleCN":"天亮前蓄水池被灌得满满的。"},{"word":"accomplish","structure":"ad- + complere (verb)","meaning":"to finish, carry out","meaningCN":"完成；实现","example":"They accomplished the survey in one season.","exampleCN":"他们在一个季节里完成了勘测。"},{"word":"accomplishment","structure":"accomplish + -ment (action, result)","meaning":"the act or result of finishing","meaningCN":"完成的行为或结果","example":"The accomplishment took eleven years.","exampleCN":"这项完成用了十一年。"},{"word":"accomplished","structure":"accomplish + -ed (participle as adjective)","meaning":"skilled, fully trained","meaningCN":"技艺娴熟的","example":"She is an accomplished cellist.","exampleCN":"她是一位造诣很高的大提琴手。"},{"word":"accomplishable","structure":"accomplish + -able (can be)","meaning":"able to be done","meaningCN":"可以完成的","example":"The plan is accomplishable within a year.","exampleCN":"这个计划能在一年内完成。"},{"word":"unaccomplished","structure":"un- + accomplish + -ed","meaning":"not yet achieved","meaningCN":"尚未完成的","example":"The unaccomplished part needs a second crew.","exampleCN":"未完成的部分需要第二支队伍。"},{"word":"supplement","structure":"sub- + plere + -ment","meaning":"something added to fill a gap","meaningCN":"补足所缺之物；补充","example":"A supplement filled the missing pages.","exampleCN":"一份补充材料补齐了缺页。"},{"word":"deplete","structure":"de- + plere","meaning":"to empty out","meaningCN":"耗尽；抽空","example":"The dry winter depleted the reservoir.","exampleCN":"干旱的冬天耗尽了水库。"}],"latinEntries":[{"word":"plere","structure":"plere, plevi, pletum (verb, second conjugation)","meaning":"to fill","meaningCN":"填满"},{"word":"complere","structure":"complere, complevi, completum (verb, second conjugation)","meaning":"to fill up, complete","meaningCN":"填满；完成"},{"word":"complementum","structure":"complementum, complementi (n., second declension)","meaning":"that which completes","meaningCN":"使完整之物"},{"word":"adimplere","structure":"adimplere, adimplevi, adimpletum (verb, second conjugation)","meaning":"to fill up, fulfil","meaningCN":"填满；履行"}]}},{"word":"failure","ipa_uk":"/ˈfeɪl.jər/","ipa_us":"/ˈfeɪl.jɚ/","definition_zh":"失败；失败的一次尝试；故障失灵；未履行；衰退；歉收；倒闭","definition_en":"a lack of success in doing something, or an instance of something going wrong","core_image":"一座桥的模型在承重测试中从中间弯下去，砝码落进水池","scene":"模型桥在承重测试里从中间弯折，砝码掉进水池，记录员在表格上写下一行。The failure of the model came from one joint that was glued too thinly.","sceneCN":"这里 failure 指「未能达成目标的一次失败」（第 1 个义项：事情没有成功）；句意为模型的失败源于一个粘得太薄的接点。图中可辨识物件：弯折的桥面、落水的砝码、写下一行的表格、太薄的胶接点。","pos":[{"tag":"n.","zh":"失败；失败的事；故障；未履行；衰退；歉收；倒闭"}],"collocations":[{"phrase":"end in failure","zh":"以失败告终"},{"phrase":"a failure to do","zh":"未能做到某事"},{"phrase":"heart failure","zh":"心力衰竭"},{"phrase":"crop failure","zh":"作物歉收"},{"phrase":"power failure","zh":"停电；供电故障"},{"phrase":"failure rate","zh":"故障率；失败率"},{"phrase":"learn from failure","zh":"从失败中学习"}],"forms":[{"label":"单数","form":"failure"},{"label":"复数","form":"failures"},{"label":"动词","form":"fail"},{"label":"动词三单","form":"fails"},{"label":"动词过去式","form":"failed"},{"label":"动词现在分词","form":"failing"}],"derivatives":[{"word":"fail","pos":"v.","zh":"基础动词，来自拉丁语「使人失望」，语义为「未做到、失灵」"},{"word":"failing","pos":"n./prep.","zh":"由现在分词转为名词，语义由「正在失效」转为「缺点」或「若无……的话」"},{"word":"failed","pos":"adj.","zh":"由过去分词转为形容词，语义由「已未成功」转为「已告失败的」"},{"word":"fail-safe","pos":"adj.","zh":"由动词与表示「安全」的词复合而成，语义由「失灵」转为「失灵时仍不致危险」"},{"word":"unfailing","pos":"adj.","zh":"加否定前缀与形容词后缀构成，语义由「会失灵」转为「从不失灵、可靠」"}],"senses":[{"no":"01","title":"Lack of success","titleCN":"没有成功这件事","definition":"the fact of not achieving what was attempted or expected","definitionCN":"没有达成所尝试或所期望之事的事实","example":"The failure of the model came from one joint that was glued too thinly.","exampleCN":"模型的失败源于一个粘得太薄的接点。","why":"fail descends from a Latin verb meaning to disappoint or let down, so failure begins as a gap between promise and result.","whyCN":"这个词的动词来自拉丁语「使人失望、辜负」，因此失败最初就是承诺与结果之间的落差。"},{"no":"02","title":"A failed attempt or thing","titleCN":"一次失败的尝试或一件失败之作","definition":"a particular attempt, work or person that did not succeed","definitionCN":"某一个没有成功的尝试、作品或人","example":"The first three prototypes were failures, but the fourth held.","exampleCN":"前三个样品都失败了，第四个撑住了。","why":"the abstract gap can be counted when each attempt leaves its own gap, which is how the noun becomes plural.","whyCN":"当每一次尝试都留下自己的落差，抽象的落差就可以计数，名词于是有了复数。"},{"no":"03","title":"Mechanical breakdown","titleCN":"机械或系统的故障","definition":"a point at which a machine, structure or system stops working as it should","definitionCN":"机器、结构或系统停止正常工作的那个点","example":"A seal failure flooded the pump room.","exampleCN":"一处密封失效淹了泵房。","why":"a device that does not do its job has also let someone down, so the same word covers broken parts.","whyCN":"一台没做好本职的装置同样辜负了人，因此同一个词也用于损坏的部件。"},{"no":"04","title":"Omission of a duty","titleCN":"该做而未做","definition":"the neglect or omission of something that ought to have been done","definitionCN":"应当做却没有做的那种疏忽或遗漏","example":"His failure to report the leak made the damage worse.","exampleCN":"他没有上报渗漏，使损失更严重。","why":"here the gap is moral rather than mechanical: what is missing is an act that was owed.","whyCN":"这里的落差是道德性的而非机械性的：缺的是一件本来欠着的行动。"},{"no":"05","title":"Waning of a bodily function","titleCN":"身体机能的衰竭","definition":"the gradual or sudden stopping of an organ's proper function","definitionCN":"某个器官正常功能的逐渐或突然停止","example":"The patient was treated for kidney failure.","exampleCN":"病人因肾衰竭接受治疗。","why":"an organ that stops working is described as failing in the same sense as a machine, because both are expected to perform.","whyCN":"器官停止运作与机器停止运作用的是同一个「失灵」，因为两者都被期待要发挥作用。"},{"no":"06","title":"A crop that does not come","titleCN":"作物歉收","definition":"a season in which the harvest falls far below what was expected","definitionCN":"收成远低于预期的那个季节","example":"Two years of crop failure emptied the granaries.","exampleCN":"两年歉收掏空了谷仓。","why":"the harvest is the result the season promised, and when it does not arrive, the same word names the shortfall.","whyCN":"收成是这一季所承诺的结果，它没有到来时，同一个词就指那份短缺。"},{"no":"07","title":"Collapse of a business","titleCN":"企业倒闭","definition":"the closing of a firm because it can no longer meet its obligations","definitionCN":"公司因无法再履行义务而关闭","example":"The bank's failure froze credit across the region.","exampleCN":"这家银行的倒闭冻结了整个地区的信贷。","why":"an institution is expected to keep standing, so its collapse is a failure in the plain sense of not holding up.","whyCN":"机构被期待站立得住，因此它的倒塌就是最朴素意义上的「没撑住」。"},{"no":"08","title":"A mark below the pass line","titleCN":"未达及格线的成绩","definition":"a grade or judgement showing that work did not reach the required standard","definitionCN":"表明作业或表现未达到规定标准的评分或判定","example":"One failure in the lab module kept him from graduating.","exampleCN":"实验课的一次不及格使他没能毕业。","why":"schools measure against a line, and anything under it repeats the original gap between what was required and what was given.","whyCN":"学校拿一条线来衡量，线下的任何结果都重复了最初那道「要求与交付」之间的落差。"}],"etymology":{"intro":{"en":"Failure comes from fail, which entered English through Old French faillir 'to be lacking, to fall short', from a Vulgar Latin verb reconstructed as fallire, an altered form of Latin fallere 'to deceive, disappoint'. The deeper origin of fallere is not settled. Dates are approximate.","cn":"该词来自动词 fail，后者经古法语 faillir「欠缺、不足」进入英语，其源头是一个被重构为 fallire 的俗拉丁动词，那是拉丁 fallere「欺骗、使人失望」的变形。fallere 的更深来源尚无定论，年代均为约数。"},"items":[{"era":"LATIN FALLERE","en":"Fallere meant 'to deceive, trick, disappoint'. Its deeper origin is uncertain; the proposals that link it to a root for 'to stumble' remain hypotheses rather than demonstrated derivations.","cn":"fallere 意为「欺骗、蒙骗、使人失望」。其更深来源不确定；把它与表示「绊倒」的词根相联系的看法仍属假说，并非已证实的派生。"},{"era":"VULGAR LATIN FALLIRE","en":"A spoken-Latin form reconstructed as fallire shifted the verb toward 'to be missing, to come short'; the form is a reconstruction rather than an attested word.","cn":"一个被重构为 fallire 的口语拉丁形式，把动词的意思转向「缺失、不足」；这一形式属重构，并非有书证的词。"},{"era":"OLD FRENCH FAILLIR","en":"Old French faillir meant both to lack and to give way, and it supplied English with fail, failing and failure.","cn":"古法语 faillir 兼指「缺少」与「支撑不住」，并给英语提供了动词、分词与名词三种形态。"},{"era":"MIDDLE ENGLISH","en":"Middle English used fail for a person who lets others down and for a plan that does not hold, and the noun failure followed in the sixteenth century.","cn":"中古英语用这个动词既指辜负他人的人，也指撑不住的计划；名词形式在十六世纪随后出现。"},{"era":"TECHNICAL SENSES","en":"Engineering and medicine widened the word in the nineteenth and twentieth centuries to seals, pumps, organs and power supplies.","cn":"工程与医学在十九、二十世纪把这个词扩展到密封件、泵、器官与供电。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin of fallere and the exact spoken form): no precise first citation is recorded for the engineering sense, and any Indo-European form offered for fallere is a reconstruction.","cn":"来源不确定（fallere 的更深来源与那个口语形式的确切面貌）：工程义没有确切的最早书证；凡为 fallere 给出的印欧语形式均属重构形式。"}]},"similar":{"note":{"en":"Group one separates look-alikes that share the Latin root but drifted apart; group two separates near synonyms by what exactly went wrong.","cn":"第一组区分同出拉丁词根却各自漂走的形近词；第二组按「究竟哪里出了错」区分近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"false","ipa":"/fɔːls/","tag":"shares fallere","definition":"Untrue or disloyal, from the same deceiving verb: the deceit sits in the content, not in the outcome.","definitionCN":"不真实或不忠，同出那个表示「欺骗」的动词：欺诈落在内容里，而不是结果里。"},{"word":"fault","ipa":"/fɔːlt/","tag":"shares fallere","definition":"A defect or a blameworthy act, again from the same root, but it names the flaw rather than the collapse.","definitionCN":"缺陷或该受责备的行为，同样出自这个词根，但它指那个瑕疵，而非崩塌本身。"},{"word":"fallible","ipa":"/ˈfæləbl/","tag":"shares fallere","definition":"Capable of being wrong; it describes a standing liability to error, not an actual miss.","definitionCN":"有犯错可能的；描述一种随时会错的属性，而不是一次实际的落空。"},{"word":"default","ipa":"/dɪˈfɔːlt/","tag":"shares the French branch","definition":"A failure to do what is required, especially to pay or to appear; it is the legal cousin of failure.","definitionCN":"未做应做之事，尤指未付款或未到场；是 failure 在法律上的近亲。"},{"word":"fell","ipa":"/fel/","tag":"different root","definition":"To cut down a tree, from Old English fellan; the resemblance is accidental and has nothing to do with the deceiving verb.","definitionCN":"砍倒树木，来自古英语 fellan；形似只是偶然，与那个表示「欺骗」的动词无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"defeat","ipa":"/dɪˈfiːt/","tag":"beaten by another","definition":"A loss in a contest against an opponent; failure needs no rival, only an unmet aim.","definitionCN":"在与他人的较量中落败；而 failure 不必有对手，只需目标未达。"},{"word":"flop","ipa":"/flɒp/","tag":"informal public failure","definition":"A product or show that fails publicly and conspicuously; it adds ridicule that failure does not.","definitionCN":"公开而显眼地失败的产品或演出；比 failure 多了一层被嘲笑的意味。"},{"word":"collapse","ipa":"/kəˈlæps/","tag":"structural fall","definition":"A sudden falling in of a structure or system; failure can be slow, while collapse is abrupt.","definitionCN":"结构或系统突然塌下；failure 可以是缓慢的，而 collapse 是骤然发生的。"},{"word":"shortfall","ipa":"/ˈʃɔːtfɔːl/","tag":"a measured gap","definition":"The amount by which a total falls short of what was needed; failure says the aim was missed, shortfall says by how much.","definitionCN":"总量低于所需之数的那部分；failure 说目标未达，shortfall 说差了多少。"},{"word":"mishap","ipa":"/ˈmɪshæp/","tag":"minor accident","definition":"A small unlucky accident with limited consequences; it is far lighter than failure.","definitionCN":"后果有限的小意外；分量远轻于 failure。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The Latin verb meant to disappoint, so failure is first of all a promise that did not come true.","cn":"那个拉丁动词意为「使人失望」，所以失败首先是没能兑现的承诺。"},{"en":"The family runs fail, failing, failure, failed, unfailing, fail-safe.","cn":"同族词覆盖动词、名词、形容词、否定式与复合式。"},{"en":"Fixed phrases mark the kinds: heart failure, crop failure, power failure, failure rate.","cn":"固定搭配标出种类：心力衰竭、作物歉收、停电、故障率。"},{"en":"The same root sits in false, fault and fallible, all about deceiving or being wrong.","cn":"同一词根见于 false、fault 与 fallible，都与「欺瞒」或「出错」有关。"},{"en":"Business and law say a firm fails, or defaults on a loan, both naming a duty not met.","cn":"商业与法律说一家公司倒闭，或拖欠贷款，两者都指未尽的义务。"}],"abstract":[{"en":"Picture a bridge model sagging in the middle while the weights drop into the water.","cn":"想象一座桥梁模型在中间弯下去，砝码落进水里。"},{"en":"Picture a ladder one rung short of the roof, so the climb simply stops.","cn":"想象一架梯子离屋檐差一级，往上爬就到这里为止。"},{"en":"Picture a letter returned unopened because the address was never right.","cn":"想象一封信因地址从来就不对而被原样退回。"}]},"examples":[{"en":"The experiment ended in failure after the seal cracked.","cn":"密封件开裂后，实验以失败告终。"},{"en":"His failure to answer the letter cost him the post.","cn":"他未回那封信，因此失去了职位。"},{"en":"Repeated crop failure drove the villagers to the coast.","cn":"连年歉收迫使村民迁往沿海。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「非了」——事情「非了」、没成 → 失败","word":"failure"},"root":"古法语 faillir「欠缺、撑不住」→ 俗拉丁重构形式 fallire → 拉丁 fallere「欺骗、使人失望」；fallere 更深来源不确定。","sensesIntro":{"en":"Eight senses follow one gap: what was promised does not arrive, and that gap is then counted as one attempt, found in a machine, in an omitted duty, in an organ, in a harvest, in a firm and finally in a mark on a page.","cn":"八个义项沿同一道落差展开：承诺的东西没有到来，这道落差随后被数成一次尝试，并在机器、被漏掉的义务、器官、收成、公司，最后在一张纸上的分数里被找到。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sagging bridge model and a weight falling into water.","cn":"核心意象：弯下去的桥梁模型与落进水里的砝码。"},"chain":["EXPECT","FALL SHORT","SHOW THE GAP","COUNT THE ATTEMPT","BREAK DOWN","LEAVE A MARK"],"branches":[{"senses":"01 · 04","en":"THE GAP ITSELF: an unmet aim and an act that was never performed are the same shortfall seen from two sides.","cn":"落差本身：未达的目标与从未做出的行动，是同一道短缺的两面。"},{"senses":"02 · 08","en":"COUNTED GAPS: one failed attempt, one failing mark, each with its own measure.","cn":"被数出的落差：一次失败尝试、一个不及格的分数，各自带着自己的尺度。"},{"senses":"03 · 07","en":"THINGS THAT STOP HOLDING: a seal, a pump, a bank, all expected to stand and none of them standing.","cn":"撑不住的东西：密封件、泵、银行，都被期待立住，却都没立住。"},{"senses":"05","en":"THE BODY'S OWN BREAKDOWN: an organ that stops performing is a machine that fails.","cn":"身体自身的失灵：器官停止履职，就是一台失灵机器。"},{"senses":"06","en":"THE SEASON THAT GIVES NOTHING: the harvest is the promise, and the empty granary is the gap.","cn":"一无所给的季节：收成就是那个承诺，空谷仓就是那道落差。"}]},"affixes":{"intro":{"en":"Failure is a noun built in English on a borrowed French verb, so the suffix is the only clearly English part; the root still organizes a whole family of words about being wrong.","cn":"这个词是英语在借入的法语动词上加后缀构成的，后缀是唯一明显属于英语的部分；词根仍然组织起一整族关于「出错」的词。"},"latinIntro":{"en":"Latin fallere 'to deceive' gives false, fault, fallible and fallacy; the noun suffix -ure marks a state or an act, as in departure and closure.","cn":"拉丁 fallere「欺骗」衍生出 false、fault、fallible 与 fallacy；名词后缀 -ure 标示状态或行为，如 departure 与 closure。"},"items":[{"word":"fail","structure":"Old French faillir, from Vulgar Latin fallire","meaning":"to come short, give way","meaningCN":"不足；撑不住","example":"The pump failed at midnight.","exampleCN":"泵在半夜失灵了。"},{"word":"failure","structure":"fail + -ure (state, act)","meaning":"the state of falling short","meaningCN":"未达的状态；失败","example":"The failure taught them where to reinforce.","exampleCN":"这次失败让他们知道该在哪里加固。"},{"word":"failing","structure":"fail + -ing (noun use)","meaning":"a weakness, or the absence of something","meaningCN":"缺点；若无某物","example":"Patience was never his failing.","exampleCN":"耐心从来不是他的缺点。"},{"word":"failed","structure":"fail + -ed (participle as adjective)","meaning":"that has not succeeded","meaningCN":"已告失败的","example":"The failed crop left the field bare.","exampleCN":"失败的庄稼让田里空着。"},{"word":"unfailing","structure":"un- + fail + -ing","meaning":"never giving way","meaningCN":"从不失灵的；可靠的","example":"Her unfailing calm steadied the room.","exampleCN":"她那从不失的镇定稳住了全场。"},{"word":"fail-safe","structure":"fail + safe (compound adjective)","meaning":"designed to be harmless when it fails","meaningCN":"失灵时仍不致危险的","example":"The valve is fail-safe by design.","exampleCN":"这个阀门按设计是失灵也安全的。"},{"word":"false","structure":"fallere + -se (adjective)","meaning":"untrue, disloyal","meaningCN":"虚假的；不忠的","example":"The false signature voided the deed.","exampleCN":"伪造的签名使这份契据失效。"},{"word":"fault","structure":"fallere + -tum (noun)","meaning":"a defect, a blame","meaningCN":"缺陷；过错","example":"The fault lay in the weld.","exampleCN":"问题出在焊缝上。"},{"word":"fallible","structure":"fallere + -ible (can be)","meaning":"able to err","meaningCN":"会犯错的","example":"Every fallible witness was cross-checked.","exampleCN":"每位可能出错的证人都被交叉核对。"},{"word":"fallacy","structure":"fallere + -acia (noun of quality)","meaning":"a deceptive argument","meaningCN":"谬见；谬误","example":"The argument rested on a familiar fallacy.","exampleCN":"这个论证建立在一个常见的谬误上。"}],"latinEntries":[{"word":"fallere","structure":"fallere, fefelli, falsum (verb, third conjugation)","meaning":"to deceive, disappoint","meaningCN":"欺骗；使人失望"},{"word":"falsus","structure":"falsus, falsa, falsum (adjective)","meaning":"false, deceptive","meaningCN":"虚假的；欺人的"},{"word":"fallacia","structure":"fallacia, fallaciae (f., first declension)","meaning":"deceit, a trick","meaningCN":"欺骗；诡计"},{"word":"fallibilis","structure":"fallibilis, fallibile (adjective, third declension)","meaning":"liable to err","meaningCN":"容易出错的"}]}},{"word":"succeed","ipa_uk":"/səkˈsiːd/","ipa_us":"/səkˈsiːd/","definition_zh":"成功；达到目的；继任；接着发生；继承","definition_en":"to achieve what one has been trying to do, or to come next after someone or something","core_image":"接力赛中，前一棒的人交棒之后，下一棒的人从同一条跑道上继续往前冲","scene":"接力赛最后一棒接过来时队伍还落后两步，跑者一路追到终点线前才反超。She succeeded where three earlier runners had fallen behind.","sceneCN":"这里 succeed 指「达成想要的结果」（第 1 个义项：努力之后成功）；句意为前面三位跑者都落后了，而她成功了。图中可辨识物件：交接的接力棒、终点线、落后的两步距离、同一条跑道。","pos":[{"tag":"vi.","zh":"成功；达到目的；接着发生；继任；继承"},{"tag":"vt.","zh":"接替（某人）；紧随（某事）之后"}],"collocations":[{"phrase":"succeed in doing","zh":"成功做到某事"},{"phrase":"succeed to the throne","zh":"继承王位"},{"phrase":"succeed as director","zh":"接任主管之职"},{"phrase":"succeed against the odds","zh":"在逆境中成功"},{"phrase":"succeed one another","zh":"彼此相继"},{"phrase":"if at first you do not succeed","zh":"如果一开始没有成功"}],"forms":[{"label":"三单（he/she/it）","form":"succeeds"},{"label":"过去式","form":"succeeded"},{"label":"过去分词","form":"succeeded"},{"label":"现在分词","form":"succeeding"},{"label":"名词（成功）","form":"success"},{"label":"形容词（成功的）","form":"successful"},{"label":"名词（继任者）","form":"successor"}],"derivatives":[{"word":"success","pos":"n.","zh":"由动词加表示结果的名词后缀构成，语义由「接着走」转为「走出来的结果」，再转为「好结果」"},{"word":"successful","pos":"adj.","zh":"由名词加表示「充满」的形容词后缀构成，语义由「好结果」转为「带有好结果的」"},{"word":"succession","pos":"n.","zh":"由动词加表示过程的名词后缀构成，语义由「接着来」转为「接连相续的次序」"},{"word":"successive","pos":"adj.","zh":"由名词加形容词后缀构成，语义由「相续」转为「一个接一个的」"},{"word":"successor","pos":"n.","zh":"由动词加表示施动者的名词后缀构成，语义由「接替」转为「接替职位的人」"},{"word":"succeeding","pos":"adj.","zh":"由现在分词转为形容词，语义由「接着」转为「随后的」"}],"senses":[{"no":"01","title":"Reach the intended aim","titleCN":"达到想要的结果","definition":"to achieve the result one set out to achieve, especially after effort or risk","definitionCN":"达成自己一开始想要的结果，尤指经过努力或风险之后","example":"She succeeded where three earlier runners had fallen behind.","exampleCN":"前面三位跑者都落后了，而她成功了。","why":"the Latin verb meant to come next or to go under, and a plan that comes out well is one that follows smoothly to its end.","whyCN":"那个拉丁动词意为「接在后面」或「走在下面」，而一个顺利走到底的计划，就是一路顺接而下的计划。"},{"no":"02","title":"Take over an office","titleCN":"接替某个职位","definition":"to take the place of someone in an office, role or title","definitionCN":"在某职位、角色或头衔上取代某人的位置","example":"She succeeded her teacher as head of the department.","exampleCN":"她接替老师成为系主任。","why":"this is the literal old sense: one person comes directly after another in the same seat.","whyCN":"这是最字面的旧义：一个人紧接另一个人，坐上同一把椅子。"},{"no":"03","title":"Follow in time","titleCN":"在时间上接着发生","definition":"to come immediately after something else in time or order","definitionCN":"在时间或次序上紧接在某事之后","example":"A quiet year succeeded the years of war.","exampleCN":"战乱之年之后紧接而来的是一个安静的年头。","why":"the word kept its Latin shape here: whatever succeeds simply follows, with no judgement about whether it is good.","whyCN":"这里保留了拉丁语的原形：接在后面的事只是接在后面，并不评判它好坏。"},{"no":"04","title":"Turn out well","titleCN":"结果顺利、奏效","definition":"to have a favourable outcome, said of a plan, a method or an event","definitionCN":"取得有利的结果，用于计划、方法或事件","example":"The new irrigation scheme succeeded in its second season.","exampleCN":"新的灌溉方案在第二个季节奏效了。","why":"a plan that follows through without snagging looks like success, so the neutral sense of following gained a positive tone.","whyCN":"一个一路顺接、不被绊住的计划看起来就像成功，于是中性的「接着」带上了褒义。"},{"no":"05","title":"Inherit a title or property","titleCN":"继承头衔或财产","definition":"to inherit a title, an estate or a right when the previous holder dies or leaves","definitionCN":"前一位持有者去世或离开时，继承头衔、产业或权利","example":"He succeeded to the estate at nineteen.","exampleCN":"他十九岁时继承了这处产业。","why":"inheritance is succession in its legal form: the heir steps into the place the dead person vacated.","whyCN":"继承是「接续」在法律上的形态：继承人走进逝者空出的位置。"},{"no":"06","title":"Come next in a sequence","titleCN":"在序列中紧接其后","definition":"to occupy the position immediately after another item in a series","definitionCN":"在一串事物中占据紧接另一项之后的位置","example":"In the catalogue, the letter S succeeds R.","exampleCN":"在目录里，字母 S 排在 R 之后。","why":"this is succession without any human actor: order itself is doing the following.","whyCN":"这是不涉及人的接续：是次序本身在「跟着」。"},{"no":"07","title":"Work as intended","titleCN":"方法或药物起效","definition":"to produce the intended effect, said of a treatment, a technique or a device","definitionCN":"产生预期效果，用于疗法、技术或装置","example":"The vaccine succeeded in every trial group.","exampleCN":"这种疫苗在每个试验组都奏效了。","why":"the test of a method is whether it reaches its aim, which is the plain sense of the word applied to tools.","whyCN":"检验一种方法，就是看它有没有抵达目标，这正是这个词用在工具上的朴素意思。"},{"no":"08","title":"Win acceptance in the market","titleCN":"在市场上受欢迎","definition":"to gain public approval or commercial acceptance, said of a product or a work","definitionCN":"获得公众认可或商业上的接受，用于产品或作品","example":"The small electric car succeeded in cities where parking is scarce.","exampleCN":"这款小型电动车在车位稀缺的城市里大受欢迎。","why":"a product's aim is to be bought, so meeting that aim counts as success in the ordinary sense.","whyCN":"产品的目标就是被买走，达成这个目标自然算成功。"}],"etymology":{"intro":{"en":"Succeed comes from Latin succedere 'to come next, to go under, to follow', built on sub- 'under, close to' and cedere 'to go, to yield'. The deeper origin of cedere is not settled. Dates are approximate.","cn":"该词来自拉丁 succedere「接在后面、走到下面、跟随」，由 sub-「在下、贴近」与 cedere「走、让」构成。cedere 的更深来源尚无定论，年代均为约数。"},"items":[{"era":"LATIN CEDERE","en":"Cedere meant 'to go, to move, to yield'. Its deeper origin is uncertain; the link sometimes proposed to a root for 'to set out' is a hypothesis rather than a demonstrated derivation.","cn":"cedere 意为「走、移动、退让」。其更深来源不确定；有人把它与表示「出发」的词根相联系，那只是假说，并非已证实的派生。"},{"era":"LATIN SUCCEDERE","en":"Sub- 'close to, under' plus cedere gave succedere 'to go under, to come next, to take another's place'.","cn":"sub-「贴近、在下」加 cedere 构成 succedere「走到下面、接在后面、取代他人位置」。"},{"era":"LATIN SUCCESSUS","en":"The fourth-declension noun successus meant 'a following, an outcome', with no praise attached; a good or bad outcome was still to be specified.","cn":"第四变格名词 successus 意为「接续、结果」，本身不含褒贬；结果是好是坏还需另说。"},{"era":"ENGLISH ARRIVAL","en":"English took the verb in the fifteenth century, first for coming after someone in an office, then for following in time.","cn":"英语在十五世纪吸收了这个动词，先指在职位上接替某人，再指在时间上接续。"},{"era":"POSITIVE SHIFT","en":"By the sixteenth century a favourable outcome was called a success, and the verb followed, so that succeeding now usually means doing well.","cn":"到十六世纪，有利的结果被称为 success，动词也随之跟进，于是「成功」成了今天最常用的意思。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin of cedere and the exact date of the positive shift): no precise citation fixes the moment when following became prospering, and any Indo-European form offered for cedere is a reconstruction.","cn":"来源不确定（cedere 的更深来源与褒义转向的确切年代）：没有确切书证能定住「接续」变为「兴旺」的那一刻；凡为 cedere 给出的印欧语形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds Latin verbs built on the same cedere root that learners constantly mix up; group two holds near synonyms of doing well.","cn":"第一组是同出 cedere 词根、学习者常混的拉丁动词；第二组是表示「做得好」的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"proceed","ipa":"/prəˈsiːd/","tag":"forward, not after","definition":"Pro- 'forward' plus cedere: to go on or move ahead, with no idea of taking a place or of prospering.","definitionCN":"由 pro-「向前」加 cedere 构成：继续前行或推进，不含「接位」或「兴旺」。"},{"word":"exceed","ipa":"/ɪkˈsiːd/","tag":"beyond the limit","definition":"Ex- 'out, beyond' plus cedere: to go past a limit or a number.","definitionCN":"由 ex-「出、越」加 cedere 构成：超出某个界限或数目。"},{"word":"concede","ipa":"/kənˈsiːd/","tag":"yield fully","definition":"Com- 'completely' plus cedere 'to yield': to give way, admit or grant, which is the yielding side of the root.","definitionCN":"由 com-「完全」加 cedere「让」构成：让步、承认或给予，正是词根「让」的那一面。"},{"word":"recede","ipa":"/rɪˈsiːd/","tag":"go back","definition":"Re- 'back' plus cedere: to move away or withdraw, as water from a shore.","definitionCN":"由 re-「向后」加 cedere 构成：退去或撤回，如潮水离岸。"},{"word":"access","ipa":"/ˈækses/","tag":"different prefix, same root","definition":"Ad- 'to' plus cedere: a coming toward or an approach, hence a way in; it is a relative but has no sense of following.","definitionCN":"由 ad-「向」加 cedere 构成：走近、接近，因而指进入之路；同族但不含「接续」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"achieve","ipa":"/əˈtʃiːv/","tag":"reach by effort","definition":"To reach a goal through effort; it points straight at the aim, while succeed also reports how the attempt turned out.","definitionCN":"靠努力达到目标；直接指向目标，而 succeed 还报告这次尝试的结果如何。"},{"word":"flourish","ipa":"/ˈflʌrɪʃ/","tag":"grow well","definition":"To grow vigorously and do well over time; it describes continuing health, not a single win.","definitionCN":"茁壮成长、长期兴旺；描述持续的兴旺，而非一次获胜。"},{"word":"thrive","ipa":"/θraɪv/","tag":"do well in conditions","definition":"To grow strong in given conditions, as a plant or a business; it stresses conditions more than aims.","definitionCN":"在既定条件下长得强健，如植物或企业；比目标更强调条件。"},{"word":"prevail","ipa":"/prɪˈveɪl/","tag":"win out over opposition","definition":"To win out against opposition or to be widespread; it implies a contest that succeed does not.","definitionCN":"战胜对手或普遍通行；含有 succeed 所没有的较量意味。"},{"word":"inherit","ipa":"/ɪnˈherɪt/","tag":"receive from a predecessor","definition":"To receive property or a title from someone who died; it names the gift, while succeeding names the taking of the place.","definitionCN":"从逝者那里接受财产或头衔；指那份所得，而 succeed 指接上位子这个动作。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"A prefix meaning next to plus a root meaning to go: to go right into the place someone else has left.","cn":"表示「紧接」的前缀加表示「走」的词根：直接走进别人离开的那个位置。"},{"en":"The family runs succeed, success, successful, succession, successive, successor.","cn":"同族词覆盖动词、名词、形容词、过程名词、相续形容词与继任者名词。"},{"en":"Fixed phrases mark the two branches: succeed in doing, and succeed to the throne.","cn":"固定搭配标出两条支脉：成功做到某事，以及继承王位。"},{"en":"The same root gives proceed, exceed, concede, recede and access, each with its own prefix direction.","cn":"同一词根还给出 proceed、exceed、concede、recede 与 access，各自带着自己的前缀方向。"},{"en":"The noun successor keeps the oldest sense alive: the one who comes next.","cn":"名词 successor 保留了最古老的意思：接在后面那个人。"}],"abstract":[{"en":"Picture a baton passed from a tired hand into a fresh one on the same track.","cn":"想象接力棒从一只疲惫的手交到一只新鲜的手里，还在同一条跑道上。"},{"en":"Picture a chair still warm from the person who has just stood up.","cn":"想象一把椅子还留着刚站起来那人的余温。"},{"en":"Picture a page turning to the next chapter without a pause.","cn":"想象书页不停地翻到下一章。"}]},"examples":[{"en":"The second attempt succeeded because the team changed the glue.","cn":"第二次尝试成功了，因为团队换了胶。"},{"en":"She succeeded to the chair after twelve years as deputy.","cn":"做了十二年副手之后，她继任了主席之位。"},{"en":"One calm decade succeeded the long quarrel.","cn":"长久争吵之后紧接而来的是平静的十年。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「success 得」——一路顺着接到得手的结果 → 成功、继任","word":"succeed"},"root":"拉丁 succedere「接在后、走到下面」= sub-（贴近、在下）+ cedere「走、让」；cedere 更深来源不确定。","sensesIntro":{"en":"Eight senses follow one motion: a runner takes the place just vacated and moves on, and that single motion is then applied to aims, offices, time, methods, inheritance, order, treatments and markets.","cn":"八个义项沿同一个动作展开：跑者接进刚空出的位置再往前跑，这个动作随后被用于目标、职位、时间、方法、继承、次序、疗法与市场。"},"semanticMap":{"core":{"en":"CORE IMAGE: a fresh runner taking the baton in the place the tired one has just left.","cn":"核心意象：疲惫者刚离开的位置上，新的跑者接过接力棒。"},"chain":["COME AFTER","TAKE THE PLACE","CARRY ON","REACH THE AIM","TURN OUT WELL","BE ACCEPTED"],"branches":[{"senses":"03 · 06","en":"PURE ORDER: one thing follows another, with no person and no praise involved.","cn":"纯粹的次序：一个接一个，既不涉及人，也不带褒贬。"},{"senses":"02 · 05","en":"TAKING A VACATED PLACE: an office or an estate passes to the next holder.","cn":"接进空出的位置：职位或产业传给下一位持有者。"},{"senses":"01 · 04","en":"CARRYING ON TO THE END: the plan that follows through is the plan that turns out well.","cn":"一路做到底：顺接而下的计划，就是结果顺利的计划。"},{"senses":"07","en":"THE TOOL THAT REACHES ITS AIM: a treatment or technique proves itself by working.","cn":"抵达目标的工具：疗法或技术以「起效」证明自己。"},{"senses":"08","en":"THE MARKET'S VERDICT: a product reaches its aim when buyers accept it.","cn":"市场的判决：产品被买家接受，就是抵达了目标。"}]},"affixes":{"intro":{"en":"The word is a Latin verb with a prepositional prefix, and both halves build many English words, so the family reads clearly by parts.","cn":"这个词是一个带介词前缀的拉丁动词，两半都构成许多英语词，因此整个词族可以按部件读出。"},"latinIntro":{"en":"Cedere 'to go' gives proceed, exceed, concede, recede, access and secede; sub- appears in submit, suppress and substructure.","cn":"拉丁 cedere「走」衍生出 proceed、exceed、concede、recede、access 与 secede；sub- 见于 submit、suppress 与 substructure。"},"items":[{"word":"sub-","structure":"sub- (Latin prefix, 'under, close to')","meaning":"under; close after","meaningCN":"在下；紧接其后","example":"The prefix places one thing just after another.","exampleCN":"这个前缀把一物放在另一物紧后。"},{"word":"cedere","structure":"cedere (Latin verb, 'to go, yield')","meaning":"to go; to give way","meaningCN":"走；退让","example":"The root carries both motion and yielding.","exampleCN":"这个词根同时带着「行进」与「让步」。"},{"word":"succedere","structure":"sub- + cedere","meaning":"to come next, take a place","meaningCN":"接续；接位","example":"One officer came next to another.","exampleCN":"一位官员紧接在另一位之后上任。"},{"word":"succeed","structure":"succedere passing into English","meaning":"to follow, to do well","meaningCN":"接续；成功","example":"The plan succeeded in its first year.","exampleCN":"这个计划在第一年就成功了。"},{"word":"success","structure":"succeed + -ess (result noun)","meaning":"an outcome, especially a good one","meaningCN":"结果，尤指好结果","example":"The success surprised the designers.","exampleCN":"这次成功让设计者意外。"},{"word":"successful","structure":"success + -ful (full of)","meaning":"having a good outcome","meaningCN":"取得好结果的","example":"A successful trial led to a larger study.","exampleCN":"一次成功的试验引出了更大规模的研究。"},{"word":"succession","structure":"succeed + -ion (process noun)","meaning":"the act of following in order","meaningCN":"接连相续的过程","example":"The succession of directors was orderly.","exampleCN":"主管的更替井然有序。"},{"word":"successive","structure":"succession + -ive (adjective)","meaning":"following one after another","meaningCN":"一个接一个的","example":"Three successive winters were dry.","exampleCN":"接连三个冬天都很干。"},{"word":"successor","structure":"succeed + -or (person who acts)","meaning":"one who takes the place","meaningCN":"接位者；继任者","example":"The successor kept the same schedule.","exampleCN":"继任者沿用了同一份日程。"},{"word":"proceed","structure":"pro- + cedere","meaning":"to go forward","meaningCN":"继续前行","example":"The convoy proceeded north at dusk.","exampleCN":"车队在黄昏向北推进。"}],"latinEntries":[{"word":"cedere","structure":"cedere, cessi, cessum (verb, third conjugation)","meaning":"to go, yield","meaningCN":"走；退让"},{"word":"succedere","structure":"succedere, successi, successum (verb, third conjugation)","meaning":"to come next, take a place","meaningCN":"接续；接位"},{"word":"successus","structure":"successus, successus (m., fourth declension)","meaning":"a following, an outcome","meaningCN":"接续；结果"},{"word":"successio","structure":"successio, successionis (f., third declension)","meaning":"a succeeding, succession","meaningCN":"接续；继承"}]}},{"word":"success","ipa_uk":"/səkˈses/","ipa_us":"/səkˈses/","definition_zh":"成功；取得好结果的成就；名利地位；成功的人或事；有利结果","definition_en":"the achieving of a desired aim, or the favourable outcome of an attempt","core_image":"终点线上方垂下一根带子，跑者在最后一刻把它撞断","scene":"最后一棒跑到终点时，那根带子被胸口撞断，场边的记分牌翻到新的数字。The success came after four seasons of losses.","sceneCN":"这里 success 指「达成目标后取得的好结果」（第 1 个义项：事情成功）；句意为这次成功是在连续四个赛季失利之后才来的。图中可辨识物件：被撞断的终点带、翻动的记分牌、跑者的胸口、最后一个弯道。","pos":[{"tag":"n.","zh":"成功；成就；成功的人或事；有利结果"}],"collocations":[{"phrase":"achieve success","zh":"取得成功"},{"phrase":"a success story","zh":"成功的经历；励志范例"},{"phrase":"the key to success","zh":"成功的关键"},{"phrase":"meet with success","zh":"获得成功"},{"phrase":"an overnight success","zh":"一夜成名；突然成功"},{"phrase":"success rate","zh":"成功率"},{"phrase":"a resounding success","zh":"巨大的成功"}],"forms":[{"label":"单数","form":"success"},{"label":"复数","form":"successes"},{"label":"动词","form":"succeed"},{"label":"形容词","form":"successful"},{"label":"副词","form":"successfully"},{"label":"名词（继任者）","form":"successor"}],"derivatives":[{"word":"successful","pos":"adj.","zh":"由名词加表示「充满」的形容词后缀构成，语义由「好结果」转为「带有好结果的」"},{"word":"successfully","pos":"adv.","zh":"在形容词后加副词后缀构成，语义由「成功的」转为「以成功的方式」"},{"word":"successfulness","pos":"n.","zh":"在形容词后加名词后缀构成，语义由「成功的」转为「成功的程度」"},{"word":"unsuccessful","pos":"adj.","zh":"加否定前缀构成，语义由「成功的」转为「未成功的」"},{"word":"successor","pos":"n.","zh":"由动词词干加表示施动者的后缀构成，语义由「接替」转为「继任者」"}],"senses":[{"no":"01","title":"Achieving a desired aim","titleCN":"达成想要的目标","definition":"the reaching of an aim that one has worked or hoped for","definitionCN":"达成一个自己努力过或期盼过的目标","example":"The success came after four seasons of losses.","exampleCN":"这次成功是在连续四个赛季失利之后才来的。","why":"the Latin noun first meant simply an outcome; a good outcome was so often meant that the word ended up carrying the praise itself.","whyCN":"这个拉丁名词最初只指「结果」；好结果太常被指代，于是这个词最终把褒义也承担下来。"},{"no":"02","title":"A person or thing that succeeds","titleCN":"成功的人或成功之作","definition":"a person, product or work that has won wide approval","definitionCN":"赢得了广泛认可的人、产品或作品","example":"The little bakery became a success within a year.","exampleCN":"这家小面包店一年之内就成了成功之作。","why":"the abstract result is then compressed into the thing that produced it, so one can call a shop a success.","whyCN":"抽象的结果随后被压缩进产生它的那件东西里，于是人们可以直接把一家店称为成功。"},{"no":"03","title":"Prosperity and standing","titleCN":"名利与地位","definition":"wealth, status or professional standing gained through continued achievement","definitionCN":"通过持续成就获得的财富、地位或职业声望","example":"Success changed the family's address and its manners.","exampleCN":"名利改变了这家人的住址与举止。","why":"when good outcomes pile up, the word shifts from each win to the social condition that results from them.","whyCN":"当好结果不断堆积，这个词就从每一次获胜转向由这些胜利造成的处境。"},{"no":"04","title":"A favourable outcome","titleCN":"有利的结果","definition":"the good result of a particular event, plan or treatment","definitionCN":"某个事件、计划或疗法所带来的好结果","example":"The success of the surgery depended on how early it was done.","exampleCN":"手术能否有好的结果，取决于做得多早。","why":"this is the oldest layer of the meaning, still visible when people speak of the success of a single operation.","whyCN":"这是词义最古老的一层，人们在说某一次手术的结果时仍能看见它。"},{"no":"05","title":"An outcome without praise","titleCN":"中性的结果（旧义）","definition":"the result of an affair, good or bad, as the word was used before its meaning narrowed","definitionCN":"一件事的结果，好坏皆可，即词义收窄之前的用法","example":"In older prose, the success of the embassy meant simply how it turned out.","exampleCN":"在较早的散文中，使馆之行的「结果」只指它最后怎样了。","why":"the modern sense is a narrowing of this neutral one, and historians keep the older use alive.","whyCN":"现代义是这条中性义收窄的结果，治史者仍让旧用法活着。"},{"no":"06","title":"A popular show or work","titleCN":"广受欢迎的作品或演出","definition":"an entertainment or publication that draws a large audience or strong sales","definitionCN":"吸引大量观众或销量强劲的娱乐作品或出版物","example":"The first night was a success, and the run was extended.","exampleCN":"首演很成功，演出场次因此延长。","why":"for a show, the aim is an audience, so a full house is the aim reached.","whyCN":"对演出而言，目标就是观众，坐满就是目标达成。"},{"no":"07","title":"Attainment in study or work","titleCN":"学业或事业上的成绩","definition":"recognized achievement in a course of study or a career","definitionCN":"在学业或职业生涯中被承认的成就","example":"Her success in the entrance exam opened the laboratory to her.","exampleCN":"她在入学考试中的成功为她打开了实验室的门。","why":"institutions grade people against aims, and the word follows the grading into schools and careers.","whyCN":"机构按目标给人评分，这个词就随评分进入学校与职场。"},{"no":"08","title":"A following in order","titleCN":"接续、相继（古义）","definition":"the act of coming after in time or rank, the sense the Latin noun carried into English","definitionCN":"在时间或位次上接于其后，这是拉丁名词带入英语时的意思","example":"The chronicle records the success of kings in unbroken order.","exampleCN":"这部编年史按不间断的次序记录了历代国王的相继。","why":"before it meant doing well, the word meant coming next, and a few formal contexts still preserve that skeleton.","whyCN":"在表示「做得好」之前，这个词表示「接在后面」，少数正式语境至今仍存留着这副骨架。"}],"etymology":{"intro":{"en":"Success comes from Latin successus 'a following, an outcome', from succedere 'to come next', built on sub- 'under, close to' and cedere 'to go, yield'. The deeper origin of cedere is not settled. Dates are approximate.","cn":"该词来自拉丁 successus「接续、结果」，其动词 succedere「接在后面」由 sub-「在下、贴近」与 cedere「走、让」构成。cedere 的更深来源尚无定论，年代均为约数。"},"items":[{"era":"LATIN CEDERE","en":"Cedere meant 'to go, to yield'. Its deeper origin is uncertain; the tie proposed to a root for 'to set out' remains a hypothesis, not a demonstrated derivation.","cn":"cedere 意为「走、退让」。其更深来源不确定；把它与表示「出发」的词根相联系，仍属假说，并非已证实的派生。"},{"era":"LATIN SUCCESSUS","en":"Successus was a fourth-declension noun meaning 'a following, a result'; nothing in it yet praised the result.","cn":"successus 是第四变格名词，意为「接续、结果」；其中还没有任何称赞结果的成分。"},{"era":"OLD FRENCH SUCCES","en":"Old French succes brought the noun into English in the sixteenth century, still close to the sense of an outcome.","cn":"古法语 succes 在十六世纪把这个名词带入英语，仍贴近「结果」的意思。"},{"era":"NARROWING","en":"By the seventeenth century the word was used mostly for good outcomes, and the neutral sense survived only in set phrases.","cn":"到十七世纪，这个词主要用于好结果，中性义只活在一些固定说法里。"},{"era":"COMMERCIAL SENSE","en":"The nineteenth century applied it to shows, books and firms, so that a hit could be called a success outright.","cn":"十九世纪把它用于演出、书与公司，于是一部走红的作品可以直接被称为成功。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin of cedere and the dating of the narrowing): no citation fixes exactly when praise became fixed in the word, and any Indo-European form offered for cedere is a reconstruction.","cn":"来源不确定（cedere 的更深来源与词义收窄的年代）：没有书证能确定褒义何时固定在词里；凡为 cedere 给出的印欧语形式均属重构形式。"}]},"similar":{"note":{"en":"Group one separates look-alikes that share the root but point elsewhere; group two separates words for a good result by the scale they assume.","cn":"第一组区分同根但指向别处的形近词；第二组按预设的规模区分表示「好结果」的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"succession","ipa":"/səkˈseʃən/","tag":"same root, order only","definition":"The process of following in order, as of heirs or directors; it keeps the old sense without any praise.","definitionCN":"按次序接续的过程，如继承人更替；保留了旧义，不含褒奖。"},{"word":"successor","ipa":"/səkˈsesə/","tag":"same root, the person","definition":"The person who takes the next place; it names the actor, not the outcome.","definitionCN":"接下一位子的人；指那位行动者，而非结果。"},{"word":"successive","ipa":"/səkˈsesɪv/","tag":"same root, adjective","definition":"Following one after another in a series, with no suggestion of doing well.","definitionCN":"在一串中逐个相接，不含「做得好」的意思。"},{"word":"excess","ipa":"/ɪkˈses/","tag":"different prefix","definition":"Ex- 'beyond' plus cedere: an amount beyond what is needed or allowed.","definitionCN":"由 ex-「越出」加 cedere 构成：超出所需或所许的量。"},{"word":"secede","ipa":"/sɪˈsiːd/","tag":"different prefix","definition":"Se- 'apart' plus cedere: to withdraw from a union, going away rather than coming next.","definitionCN":"由 se-「分开」加 cedere 构成：退出某个联合体，是走开而非接续。"}]},{"heading":"NEAR MEANING","entries":[{"word":"achievement","ipa":"/əˈtʃiːvmənt/","tag":"the deed itself","definition":"Something accomplished through effort; it names the deed, while success names the favourable state of affairs.","definitionCN":"通过努力做成的事；指那件事，而 success 指有利的局面。"},{"word":"victory","ipa":"/ˈvɪktəri/","tag":"defeat of a rival","definition":"A win over an opponent in a contest or war; success needs no opponent.","definitionCN":"在比赛或战争中战胜对手；success 不必有对手。"},{"word":"triumph","ipa":"/ˈtraɪəmf/","tag":"large and celebrated","definition":"A great and celebrated victory; it is public and emphatic, far louder than plain success.","definitionCN":"伟大而受庆祝的胜利；公开而强烈，比普通的成功响亮得多。"},{"word":"prosperity","ipa":"/prɒˈsperəti/","tag":"lasting wealth","definition":"A continuing condition of wealth and well-being; it is the long form of what success can bring.","definitionCN":"财富与福祉持续的状态；是 success 可能带来的长久形态。"},{"word":"hit","ipa":"/hɪt/","tag":"informal popular work","definition":"A product or show that sells very well; a colloquial relative of the entertainment sense.","definitionCN":"卖得极好的产品或演出；是娱乐义的口语近亲。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The Latin noun first meant only an outcome, and the good outcome slowly took the word over.","cn":"那个拉丁名词最初只指结果，后来好结果慢慢占满了这个词。"},{"en":"The family runs succeed, success, successful, successfully, successor, succession.","cn":"同族词覆盖动词、名词、形容词、副词、继任者与接续过程。"},{"en":"Fixed phrases mark the kinds: achieve success, the key to success, success rate, a resounding success.","cn":"固定搭配标出类型：取得成功、成功的关键、成功率、巨大的成功。"},{"en":"The same root gives proceed, exceed, concede and access, each pointing a different way.","cn":"同一词根还给出 proceed、exceed、concede 与 access，各自指向不同方向。"},{"en":"Formal writing still says an embassy met with success, meaning simply how it turned out.","cn":"正式文章仍说一次出使「有了结果」，只指它最后怎样。"}],"abstract":[{"en":"Picture a tape breaking across a runner's chest at the finish line.","cn":"想象一条带子在终点线上被跑者的胸口撞断。"},{"en":"Picture a scoreboard flipping to a number nobody expected to see.","cn":"想象记分牌翻到一个谁也没料到会出现的数字。"},{"en":"Picture a small shop's name painted on a second window across town.","cn":"想象一家小店的招牌被画到了城里另一头的第二扇窗上。"}]},"examples":[{"en":"The campaign's success depended on one honest advertisement.","cn":"这场活动能否成功，取决于一则诚实的广告。"},{"en":"She was a success on stage long before she was a success in print.","cn":"她在舞台上成名，远早于她在出版界走红。"},{"en":"The success of the graft was measured after six months.","cn":"移植是否成功，在六个月后才被评定。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「萨克塞斯」——一路顺着走到底、撞断终点带 → 成功","word":"success"},"root":"拉丁 successus「接续、结果」← succedere「接在后面」= sub-（在下、贴近）+ cedere（走、让）；cedere 更深来源不确定。","sensesIntro":{"en":"Eight senses follow one line: a following becomes an outcome, the outcome turns good, the good outcome hardens into standing, and then the word can point at a person, a show, an exam or even back at the bare order it started from.","cn":"八个义项沿一条线展开：接续变成结果，结果转好，好结果硬化成地位，随后这个词可以指一个人、一场演出、一次考试，甚至回到它起步时那个赤裸的次序。"},"semanticMap":{"core":{"en":"CORE IMAGE: a finish tape broken at the chest, with the scoreboard turning over.","cn":"核心意象：终点带被胸口撞断，记分牌翻动。"},"chain":["FOLLOW","OUTCOME","GOOD OUTCOME","RECOGNITION","STANDING","THE THING ITSELF"],"branches":[{"senses":"05 · 08","en":"THE NEUTRAL SKELETON: following in order, before any praise was attached.","cn":"中性的骨架：在褒义附着之前的「按序接续」。"},{"senses":"01 · 04","en":"THE GOOD OUTCOME: an aim reached, and a single event that ends well.","cn":"好结果：目标达成，以及某一件事有个好结局。"},{"senses":"02 · 06","en":"THE THING THAT CARRIES IT: a shop, a book or a play becomes the success it had.","cn":"承载它的东西：一家店、一本书或一台戏，成了它所拥有的那次成功。"},{"senses":"03","en":"STANDING: repeated wins settle into wealth and status.","cn":"地位：反复获胜沉淀为财富与身份。"},{"senses":"07","en":"MEASURED ATTAINMENT: schools and careers grade the aim and call the grade a success.","cn":"被量出的达成：学校与职场给目标打分，并把那个分数叫成功。"}]},"affixes":{"intro":{"en":"Success is a Latin noun taken into English, and its suffix is no longer felt as a separate piece; the root, however, still organizes a large family of motion words.","cn":"这个词是从拉丁语整体借入英语的名词，后缀已不再被感觉为独立的部件；但词根仍然组织起一大族表示「行进」的词。"},"latinIntro":{"en":"Latin cedere 'to go, yield' underlies proceed, exceed, concede, recede, access and secede; the noun ending marked a fourth-declension abstract noun.","cn":"拉丁 cedere「走、让」支撑着 proceed、exceed、concede、recede、access 与 secede；那个名词词尾标示第四变格的抽象名词。"},"items":[{"word":"sub-","structure":"sub- (Latin prefix, 'under, close to')","meaning":"under; close after","meaningCN":"在下；紧接","example":"The prefix puts one thing right after another.","exampleCN":"这个前缀把一物紧放在另一物之后。"},{"word":"cedere","structure":"cedere (Latin verb, 'to go, yield')","meaning":"to go; to give way","meaningCN":"走；退让","example":"The root carries motion and yielding at once.","exampleCN":"这个词根同时带着行进与让步。"},{"word":"succedere","structure":"sub- + cedere","meaning":"to come next","meaningCN":"接在后面","example":"One reign came next to the last.","exampleCN":"一个朝代紧接上一个。"},{"word":"successus","structure":"successus (fourth-declension noun)","meaning":"a following, an outcome","meaningCN":"接续；结果","example":"The outcome was recorded without comment.","exampleCN":"这个结果被不加评论地记了下来。"},{"word":"success","structure":"successus passing into English","meaning":"a good outcome","meaningCN":"好结果；成功","example":"The success of the season surprised the growers.","exampleCN":"这一季的成功让种植者意外。"},{"word":"successful","structure":"success + -ful (full of)","meaning":"having good outcomes","meaningCN":"取得好结果的","example":"A successful graft needs clean tools.","exampleCN":"成功的嫁接需要干净的工具。"},{"word":"successfully","structure":"successful + -ly (adverb)","meaning":"in a way that reaches the aim","meaningCN":"成功地；顺利地","example":"The crew successfully sealed the hatch.","exampleCN":"船员成功地封住了舱口。"},{"word":"successfulness","structure":"successful + -ness (quality)","meaning":"the degree of doing well","meaningCN":"成功的程度","example":"Its successfulness varied by region.","exampleCN":"它的成功程度因地区而异。"},{"word":"unsuccessful","structure":"un- + successful","meaning":"not reaching the aim","meaningCN":"未成功的","example":"An unsuccessful search ended at dusk.","exampleCN":"一次未成功的搜寻在黄昏结束。"},{"word":"succession","structure":"succeed + -ion (process)","meaning":"orderly following","meaningCN":"按序接续","example":"The succession of chairs took a month.","exampleCN":"主席的更替用了一个月。"},{"word":"successor","structure":"succeed + -or (agent)","meaning":"one who comes next","meaningCN":"继任者","example":"The successor finished the survey.","exampleCN":"继任者完成了勘测。"}],"latinEntries":[{"word":"cedere","structure":"cedere, cessi, cessum (verb, third conjugation)","meaning":"to go, yield","meaningCN":"走；退让"},{"word":"succedere","structure":"succedere, successi, successum (verb, third conjugation)","meaning":"to come next","meaningCN":"接在后面"},{"word":"successus","structure":"successus, successus (m., fourth declension)","meaning":"a following, an outcome","meaningCN":"接续；结果"},{"word":"successio","structure":"successio, successionis (f., third declension)","meaning":"succession, a following on","meaningCN":"接续；承继"}]}},{"word":"successful","ipa_uk":"/səkˈses.fəl/","ipa_us":"/səkˈses.fəl/","definition_zh":"成功的；达成目标的；事业有成的；畅销受欢迎的；奏效的","definition_en":"having achieved what was wanted, or producing the result that was intended","core_image":"一只箭正中靶心，箭尾的羽毛还在轻轻颤","scene":"第二轮试射时箭终于扎进靶心，教练在纸上把这一格圈了起来。The third design was successful where the first two had cracked under load.","sceneCN":"这里 successful 指「达成了想要的结果」（第 1 个义项：目标达成）；句意为第三个设计成功了，而前两个在承重时就开裂。图中可辨识物件：扎在靶心的箭、颤动的羽尾、被圈起的一格记录纸、开裂的前两个样品。","pos":[{"tag":"adj.","zh":"成功的；有成就的；奏效的；顺利的"}],"collocations":[{"phrase":"a successful attempt","zh":"一次成功的尝试"},{"phrase":"highly successful","zh":"非常成功的"},{"phrase":"a successful career","zh":"成功的事业"},{"phrase":"successful in doing","zh":"成功做到某事"},{"phrase":"commercially successful","zh":"商业上成功的"},{"phrase":"a successful outcome","zh":"成功的结果"}],"forms":[{"label":"原级","form":"successful"},{"label":"比较级","form":"more successful"},{"label":"最高级","form":"most successful"},{"label":"副词","form":"successfully"},{"label":"名词（成功）","form":"success"},{"label":"否定式","form":"unsuccessful"}],"derivatives":[{"word":"successfully","pos":"adv.","zh":"在形容词后加副词后缀构成，语义由「成功的」转为「以成功的方式」"},{"word":"successfulness","pos":"n.","zh":"在形容词后加名词后缀构成，语义由「成功的」转为「成功的程度」"},{"word":"unsuccessful","pos":"adj.","zh":"加否定前缀构成，语义由「成功的」转为「未成功的」"},{"word":"success","pos":"n.","zh":"基础名词，语义为「好结果」，是本形容词的构词起点"}],"senses":[{"no":"01","title":"Reaching the intended aim","titleCN":"达到原本想要的结果","definition":"having done what one set out to do, so that the aim is met","definitionCN":"完成了原本打算做的事，因此目标得以达成","example":"The third design was successful where the first two had cracked under load.","exampleCN":"第三个设计成功了，而前两个在承重时就开裂。","why":"the suffix means full of, so a successful attempt is one filled with the outcome it aimed at.","whyCN":"后缀意为「充满」，因此一次成功的尝试就是被它所瞄准的结果填满的尝试。"},{"no":"02","title":"Established in a career","titleCN":"事业有成、功成名就","definition":"having reached wealth, rank or public respect through one's work","definitionCN":"通过工作获得财富、地位或公众尊重","example":"A successful architect came back to draw the village hall for free.","exampleCN":"一位功成名就的建筑师回来，免费为村里画礼堂的图。","why":"when a person rather than an attempt is described, the word measures a whole life against its aims.","whyCN":"当被描述的是一个人而不是一次尝试时，这个词是拿整个一生去对照它的目标。"},{"no":"03","title":"Selling or drawing well","titleCN":"畅销、受欢迎","definition":"winning strong sales or large audiences, said of a product or a work","definitionCN":"取得强劲销量或大量观众，用于产品或作品","example":"The atlas was successful enough to fund a second edition.","exampleCN":"这本地图集足够畅销，足以支撑出第二版。","why":"for a product the aim is acceptance, so measurable acceptance is the aim reached.","whyCN":"对产品而言，目标就是被接受，因此可量出的接受度就是目标达成。"},{"no":"04","title":"Working as a method should","titleCN":"方法或药物确实奏效","definition":"producing the intended effect reliably, said of a method, drug or technique","definitionCN":"可靠地产生预期效果，用于方法、药物或技术","example":"The treatment was successful in nine cases out of ten.","exampleCN":"这种疗法在十例中有九例奏效。","why":"efficacy is the aim of a tool, and the adjective simply reports that the aim was reached.","whyCN":"有效是工具的目标，这个形容词只是报告目标已经达成。"},{"no":"05","title":"Ending well for an event","titleCN":"事情结尾顺利","definition":"having a favourable ending, said of a meeting, a season or a venture","definitionCN":"有好的收尾，用于会议、赛季或一场事业","example":"The harvest fair was successful despite the rain.","exampleCN":"尽管下雨，丰收集市仍然办得顺利。","why":"an event also has a hoped-for shape, and reaching that shape is what the word records.","whyCN":"一场活动也有它被期待的样子，抵达那个样子就是这个词记下的事。"},{"no":"06","title":"Judged a success by others","titleCN":"被别人评定为成功","definition":"regarded by others as having gone well, whether or not one agrees","definitionCN":"被别人看作办得不错，无论自己是否同意","example":"By every external measure the campaign was successful.","exampleCN":"按一切外部标准衡量，这场活动都是成功的。","why":"success is also a public verdict, so the adjective can report the judgement of others.","whyCN":"成功也是一种公开的判决，因此这个形容词可以转述别人的判断。"},{"no":"07","title":"Meeting social expectations","titleCN":"符合社会期待的成功","definition":"matching the standard of a good life or a good arrangement held by a community","definitionCN":"符合一个社群所持的「好生活」或「好安排」的标准","example":"Their long marriage was successful by the standards of the village.","exampleCN":"按村里的标准，他们长久的婚姻是成功的。","why":"the word borrows the community's own definition of a good outcome and applies it to a life arrangement.","whyCN":"这个词借用了社群自己对「好结果」的定义，并把它套在一种生活安排上。"},{"no":"08","title":"Proceeding safely to the intended point","titleCN":"医疗上顺利进展到预期节点","definition":"continuing safely to the point expected, said of a pregnancy, a graft or a transplant","definitionCN":"安全地推进到所预期的节点，用于妊娠、移植或移植物","example":"The graft was successful and the new skin held.","exampleCN":"移植成功了，新皮肤存活下来。","why":"medicine borrows the word for the body's own aims, where success means the tissue keeps living.","whyCN":"医学把这个词借去指身体自身的目标，在那里成功就是组织继续活着。"}],"etymology":{"intro":{"en":"Successful is success plus the Old English suffix -ful 'full of', which is native English rather than Latin. Success itself comes from Latin successus 'a following, an outcome', from succedere 'to come next'. Dates are approximate.","cn":"successful 是名词 success 加上古英语后缀 -ful「充满」，这个后缀是英语本族成分而非拉丁成分。success 本身来自拉丁 successus「接续、结果」，其动词意为「接在后面」。年代均为约数。"},"items":[{"era":"OLD ENGLISH -FUL","en":"The suffix -ful meant 'full of, having the quality of', and it turned nouns into adjectives such as hopeful and careful.","cn":"后缀 -ful 意为「充满、具有……性质」，它把名词变成形容词，如 hopeful 与 careful。"},{"era":"LATIN SUCCESSUS","en":"Successus meant 'a following, a result'; the good-result sense narrowed in English rather than in Latin.","cn":"successus 意为「接续、结果」；「好结果」这一层是在英语里收窄出来的，而不是在拉丁语里。"},{"era":"SIXTEENTH CENTURY","en":"The adjective appeared soon after the noun settled into its favourable sense, so it has always meant doing well rather than merely following.","cn":"这个形容词在名词固定为褒义之后不久出现，因此它一直表示「做得好」，而不是仅仅「接在后面」。"},{"era":"COMMERCIAL USE","en":"The nineteenth century applied the adjective to shows, books and firms, which is where the selling sense comes from.","cn":"十九世纪把这个形容词用于演出、书与公司，畅销义即由此而来。"},{"era":"MEDICAL USE","en":"Clinical writing took the word for grafts and pregnancies, measuring success by whether the tissue keeps living.","cn":"临床写作把这个词用于移植物与妊娠，以组织是否继续存活来衡量成功。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (exact first date of the adjective): no precise citation is recorded for the medical use, and the dating of the noun's narrowing rests on surviving printed sources only.","cn":"来源不确定（形容词确切的最早年代）：医学用法没有确切书证；名词褒义化的年代只能依据留存下来的印刷材料推断。"}]},"similar":{"note":{"en":"Group one separates the look-alikes that share the success family; group two separates adjectives that praise results in different ways.","cn":"第一组区分同属 success 词族的形近词；第二组按赞美结果的方式区分形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"successive","ipa":"/səkˈsesɪv/","tag":"order, not praise","definition":"Following one after another; it shares the root but says nothing about doing well.","definitionCN":"一个接一个地相继；同根，但完全不含「做得好」。"},{"word":"succession","ipa":"/səkˈseʃən/","tag":"the process","definition":"The orderly following of people or things into a place; it is a noun of order.","definitionCN":"人或物按次序接位的过程；是表示次序的名词。"},{"word":"successor","ipa":"/səkˈsesə/","tag":"the next person","definition":"The one who takes the place left open; again no praise is implied.","definitionCN":"接下空位的那个人；同样不含褒义。"},{"word":"unsuccessful","ipa":"/ˌʌnsəkˈsesfəl/","tag":"the negation","definition":"The plain negation: the aim was not reached, with no suggestion of disgrace.","definitionCN":"直接的否定式：目标未达，不含羞辱意味。"},{"word":"sufficient","ipa":"/səˈfɪʃənt/","tag":"different root","definition":"From Latin sufficere 'to supply what is needed': enough, not achieved; the resemblance is misleading.","definitionCN":"来自拉丁 sufficere「供给所需」：足够，而非达成；形近容易误导。"}]},{"heading":"NEAR MEANING","entries":[{"word":"prosperous","ipa":"/ˈprɒspərəs/","tag":"wealthy over time","definition":"Flourishing in wealth or activity over a period; it describes a standing condition, not one win.","definitionCN":"在一段时间里财富或事业兴旺；描述持续的处境，而非一次获胜。"},{"word":"effective","ipa":"/ɪˈfektɪv/","tag":"does the job","definition":"Producing the intended effect, especially of a method or a rule; it is narrower and more technical.","definitionCN":"产生预期效果，尤用于方法或规则；范围更窄，更技术化。"},{"word":"fruitful","ipa":"/ˈfruːtfəl/","tag":"yields much","definition":"Producing plenty of results, as a discussion or a season; it stresses abundance rather than a single aim.","definitionCN":"产出大量结果，如讨论或一季；强调丰盛，而非单一目标。"},{"word":"triumphant","ipa":"/traɪˈʌmfənt/","tag":"celebrated","definition":"Victorious and openly celebrated; it adds ceremony and noise to the plain fact of succeeding.","definitionCN":"获胜并公开庆祝的；在「成功」这一事实之上加了仪式与声势。"},{"word":"favourable","ipa":"/ˈfeɪvərəbl/","tag":"points the right way","definition":"Advantageous or promising, said of conditions; it describes the wind, not the arrival.","definitionCN":"条件有利或有希望；描述的是风向，而不是抵达。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The suffix is native English and means full of, so a successful try is full of its own aim.","cn":"后缀是英语本族成分，意为「充满」，因此一次成功的尝试是被它自己的目标填满的。"},{"en":"The family runs success, successful, successfully, unsuccessful, successor, succession.","cn":"同族词覆盖名词、形容词、副词、否定式、继任者与接续过程。"},{"en":"Fixed phrases mark the fields: a successful career, commercially successful, successful in doing.","cn":"固定搭配标出领域：成功的事业、商业上成功、成功做到某事。"},{"en":"The look-alike sufficient belongs to a different Latin verb, so it means enough rather than achieved.","cn":"形近的 sufficient 出自另一个拉丁动词，所以它是「足够」，不是「达成」。"},{"en":"Clinical writing uses the adjective for grafts, where success means the tissue stays alive.","cn":"临床写作把这个形容词用于移植物，那里的成功就是组织继续存活。"}],"abstract":[{"en":"Picture an arrow standing in the centre ring with its feathers still shaking.","cn":"想象一支箭扎在靶心，羽尾还在颤。"},{"en":"Picture a key turning without any need to try it a second time.","cn":"想象一把钥匙一次就转开，不必再试第二次。"},{"en":"Picture a plant rooted in new soil because the cutting took hold.","cn":"想象一株植物在新土里扎了根，因为插条活了。"}]},"examples":[{"en":"The second launch was successful after the valve was redesigned.","cn":"阀门重新设计后，第二次发射成功了。"},{"en":"She had a successful practice and still took night calls.","cn":"她的事业很成功，却仍然接夜里的电话。"},{"en":"The graft was successful, and the orchard replanted the row.","cn":"嫁接成功了，果园重新补种了这一行。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「success 满」——被结果装满 → 成功的","word":"successful"},"root":"success（拉丁 successus「接续、结果」）+ 古英语后缀 -ful「充满」；后缀为英语本族成分。","sensesIntro":{"en":"Eight senses follow one measure: something is held against the aim it was made for, and the adjective reports whether the two met, whether the thing is a plan, a person, a book, a drug, an event, a public judgement, a marriage or a graft.","cn":"八个义项沿同一把尺展开：拿一件东西去对照它被造出来的目标，这个形容词报告两者是否吻合，而这件东西可以是计划、人、书、药、事件、公众评判、婚姻或移植物。"},"semanticMap":{"core":{"en":"CORE IMAGE: an arrow in the centre ring, the aim and the result made one.","cn":"核心意象：箭扎在靶心，目标与结果合成一个。"},"chain":["SET THE AIM","TRY","MEET IT","PROVE IT WORKS","BE ACCEPTED","BE JUDGED"],"branches":[{"senses":"01 · 05","en":"THE AIM MET: an attempt or an event arrives at the shape it was meant to have.","cn":"目标达成：一次尝试或一场活动抵达了它本该有的样子。"},{"senses":"02 · 07","en":"A LIFE MEASURED: a person or a marriage is held against a standard, sometimes the neighbours' standard.","cn":"被衡量的生活：人或婚姻被对照某个标准，有时是邻里的标准。"},{"senses":"03 · 06","en":"THE PUBLIC VERDICT: sales figures and outside opinion decide the matter.","cn":"公众判决：销量与外部意见来决定这件事。"},{"senses":"04","en":"THE TOOL PROVES ITSELF: a drug or method succeeds by reliably doing its job.","cn":"工具自证：药或方法靠可靠地履职来证明自己。"},{"senses":"08","en":"THE BODY'S AIM: tissue staying alive is success in the clinic.","cn":"身体的目标：组织继续存活，就是临床上的成功。"}]},"affixes":{"intro":{"en":"The word joins a Latin noun to a native English suffix, so one half is borrowed and the other is homegrown.","cn":"这个词把拉丁名词与英语本族后缀接在一起，一半是借来的，一半是本地的。"},"latinIntro":{"en":"Latin cedere 'to go' gives succeed, proceed, exceed and access; the native suffix -ful also builds hopeful, careful and painful.","cn":"拉丁 cedere「走」衍生出 succeed、proceed、exceed 与 access；本族后缀 -ful 还构成 hopeful、careful 与 painful。"},"items":[{"word":"-ful","structure":"-ful (Old English suffix, 'full of')","meaning":"full of; having the quality of","meaningCN":"充满；具有……性质","example":"A hopeful letter arrived the same week.","exampleCN":"同一周来了一封充满希望的信。"},{"word":"success","structure":"Latin successus (noun)","meaning":"an outcome, especially a good one","meaningCN":"结果，尤指好结果","example":"The success of the trial was announced.","exampleCN":"试验的成功被公布了。"},{"word":"successful","structure":"success + -ful","meaning":"having a good outcome","meaningCN":"取得好结果的","example":"The second design was successful.","exampleCN":"第二个设计成功了。"},{"word":"successfully","structure":"successful + -ly (adverb)","meaning":"in a way that meets the aim","meaningCN":"成功地","example":"The crew successfully landed the probe.","exampleCN":"团队成功让探测器着陆。"},{"word":"successfulness","structure":"successful + -ness (quality)","meaning":"the degree of meeting aims","meaningCN":"达成目标的程度","example":"Its successfulness was uneven across regions.","exampleCN":"它达标的程度在各地区并不均衡。"},{"word":"unsuccessful","structure":"un- + successful","meaning":"not meeting the aim","meaningCN":"未达成目标的","example":"An unsuccessful bid left the hall unbuilt.","exampleCN":"一次未成功的投标使礼堂没能建成。"},{"word":"succeed","structure":"Latin succedere (verb)","meaning":"to come next, to do well","meaningCN":"接续；成功","example":"They succeeded on the fourth attempt.","exampleCN":"他们在第四次尝试时成功了。"},{"word":"succession","structure":"succeed + -ion (process)","meaning":"orderly following","meaningCN":"按序接续","example":"The succession of wardens was unbroken.","exampleCN":"管理人的更替从未中断。"},{"word":"successive","structure":"succession + -ive (adjective)","meaning":"one after another","meaningCN":"一个接一个的","example":"Three successive nights were frosty.","exampleCN":"接连三个夜晚都结了霜。"}],"latinEntries":[{"word":"cedere","structure":"cedere, cessi, cessum (verb, third conjugation)","meaning":"to go, yield","meaningCN":"走；退让"},{"word":"succedere","structure":"succedere, successi, successum (verb, third conjugation)","meaning":"to come next","meaningCN":"接在后面"},{"word":"successus","structure":"successus, successus (m., fourth declension)","meaning":"a following, a result","meaningCN":"接续；结果"}]}},{"word":"ambitious","ipa_uk":"/æmˈbɪʃ.əs/","ipa_us":"/æmˈbɪʃ.əs/","definition_zh":"有雄心的；渴望成就的；目标宏大的；野心过大的","definition_en":"wanting very much to succeed or to achieve something great","core_image":"一个人站在山脚，抬头估量远处那座比周围都高的峰","scene":"刚入职的年轻人给自己定下三年做成两件事的目标，还主动申请最难的片区。The new agent was ambitious enough to ask for the hardest territory.","sceneCN":"这里 ambitious 指「渴望成就、向上争取」（第 1 个义项：有进取的渴望）；句意为这位新人有足够的雄心，主动要下最难做的片区。图中可辨识物件：远处的最高峰、山脚的测量标记、被圈出的最难片区。","pos":[{"tag":"adj.","zh":"有雄心的；有野心的；目标宏大的；需要极大投入的"}],"collocations":[{"phrase":"an ambitious plan","zh":"宏大的计划"},{"phrase":"highly ambitious","zh":"雄心极大的"},{"phrase":"ambitious for one's children","zh":"对子女寄予厚望"},{"phrase":"an ambitious young lawyer","zh":"一位有抱负的年轻律师"},{"phrase":"an ambitious target","zh":"高难度的目标"},{"phrase":"politically ambitious","zh":"在政治上有野心的"}],"forms":[{"label":"原级","form":"ambitious"},{"label":"比较级","form":"more ambitious"},{"label":"最高级","form":"most ambitious"},{"label":"名词","form":"ambition"},{"label":"副词","form":"ambitiously"},{"label":"否定式","form":"unambitious"}],"derivatives":[{"word":"ambition","pos":"n.","zh":"基础名词，来自拉丁语「四处走动拉票」，语义为「争取、抱负」"},{"word":"ambitiously","pos":"adv.","zh":"在形容词后加副词后缀构成，语义由「有雄心的」转为「以有雄心的方式」"},{"word":"ambitiousness","pos":"n.","zh":"在形容词后加名词后缀构成，语义由「有雄心的」转为「有雄心的程度」"},{"word":"unambitious","pos":"adj.","zh":"加否定前缀构成，语义由「有雄心的」转为「不图进取的」"}],"senses":[{"no":"01","title":"Wanting to achieve greatly","titleCN":"渴望取得大成就","definition":"strongly wanting to succeed, rise or achieve something difficult","definitionCN":"强烈地想要成功、上升，或做成一件难事","example":"The new agent was ambitious enough to ask for the hardest territory.","exampleCN":"这位新人有足够的雄心，主动要下最难做的片区。","why":"the Latin source meant going around to canvass for votes, so ambition has always been a reaching outward for support and position.","whyCN":"这个词的拉丁语源意为「四处走动拉选票」，因此抱负一直是一种向外伸手争取支持与位置的动作。"},{"no":"02","title":"Grand in scale","titleCN":"规模宏大","definition":"large and bold in design, often more than is strictly necessary","definitionCN":"设计上宏大而大胆，常超出实际所需","example":"The city approved an ambitious plan for a park twice the size of the old one.","exampleCN":"市里批准了一个宏大的计划，公园面积是旧园的两倍。","why":"the desire to be seen achieving shows in the size of the plan rather than in the person's feeling.","whyCN":"那份想被看见成就的渴望，会显现在计划的体量上，而不是显示在人的感受里。"},{"no":"03","title":"Demanding great commitment","titleCN":"要求极大投入","definition":"requiring far more work, money or time than a modest version would","definitionCN":"比常规版本要求多得多的工、钱或时间","example":"It was an ambitious schedule for a crew of six.","exampleCN":"对一支六人的队伍来说，这份进度表要求太高了。","why":"a plan that reaches high costs more, so the adjective comes to describe the burden as well as the aim.","whyCN":"目标定得高，代价也就更大，因此这个形容词既描述目标，也描述那份负担。"},{"no":"04","title":"Enterprising in a good sense","titleCN":"积极进取（褒义）","definition":"showing energetic drive to improve one's position, viewed with approval","definitionCN":"表现出改善自身处境的旺盛干劲，且带赞许","example":"An ambitious apprentice learns two trades in the same workshop.","exampleCN":"一个有进取心的学徒在同一间作坊里学两门手艺。","why":"the same outward reaching can be praised when it produces wider skill and better work.","whyCN":"同一份向外的争取，在它带来更广的手艺与更好的活时，会被称赞。"},{"no":"05","title":"Grasping beyond one's due","titleCN":"野心越过界限（贬义）","definition":"seeking power or advantage beyond what is proper or fair","definitionCN":"谋求超出正当或公平范围的权力与好处","example":"His ambitious maneuver cost him the trust of the council.","exampleCN":"他那番野心过大的操作让他失去了议会的信任。","why":"when the reaching crosses what others allow, the same drive is read as a fault.","whyCN":"当这只手伸过别人允许的界线，同一股干劲就被读成缺陷。"},{"no":"06","title":"Eager for a specific thing","titleCN":"为某人某事殷切期盼","definition":"eager for a particular person or thing to do well, often used with for","definitionCN":"热切希望某个具体的人或事做得好，后面常接一个表示对象的介词","example":"The coach was ambitious for the youngest swimmers.","exampleCN":"教练对这些最小的泳手寄予厚望。","why":"the reaching can be aimed at another person's rise rather than one's own.","whyCN":"这只手可以伸向别人的上升，而不是自己的。"},{"no":"07","title":"Designed to impress","titleCN":"为显气派而设","definition":"built or written on a scale meant to signal importance","definitionCN":"按一种意在标示重要的规模来建造或书写","example":"The station hall had an ambitious ceiling that leaked in rain.","exampleCN":"车站大厅的天花板造得很有气派，下雨却会漏。","why":"scale is used as a message, so the adjective can describe architecture rather than appetite.","whyCN":"规模被当作一种讯息使用，因此这个形容词可以描述建筑，而不是胃口。"},{"no":"08","title":"Attempting more than can be done","titleCN":"揽下过多而难以完成","definition":"undertaking more tasks or promises than the available means can carry","definitionCN":"揽下的任务或承诺超过现有条件能承载的量","example":"An ambitious first draft tried to answer three questions at once.","exampleCN":"一份急于求成的初稿想同时回答三个问题。","why":"the same upward push, applied to a draft or a workload, overshoots what the means can hold.","whyCN":"同一股向上推的劲，用在稿子或工作量上，就超出了条件所能撑住的范围。"}],"etymology":{"intro":{"en":"Ambitious comes from ambition, which comes through Old French from Latin ambitio 'a going around, a canvassing for office', from ambire 'to go around', built on ambi- 'around' and ire 'to go'. Dates are approximate.","cn":"这个形容词来自名词 ambition，后者经古法语上溯到拉丁 ambitio「绕行、为求官职四处奔走」，其动词 ambire「绕行」由 ambi-「环绕」与 ire「走」构成。年代均为约数。"},"items":[{"era":"LATIN IRE","en":"Ire meant 'to go'. Its forms are irregular and very old; the deeper origin of the verb is not settled.","cn":"ire 意为「走」。它的变位不规则且非常古老；这个动词更深的来源尚无定论。"},{"era":"LATIN AMBIRE","en":"Ambi- 'around' plus ire gave ambire 'to go around', used of candidates walking around to solicit votes.","cn":"ambi-「环绕」加 ire 构成 ambire「绕行」，用于候选人四处走动拉票。"},{"era":"LATIN AMBITIO","en":"The noun ambitio named that going around, and by extension the desire for honour that drove it.","cn":"名词 ambitio 指这种绕行奔走，并引申指驱使人奔走的那份求名之心。"},{"era":"OLD FRENCH","en":"Old French ambicion passed the noun into English, still close to the political picture of courting support.","cn":"古法语 ambicion 把这个名词带入英语，仍贴近争取支持的政治图景。"},{"era":"ADJECTIVE","en":"The adjective ambitious was formed on the noun and widened to cover plans, buildings and schedules as well as people.","cn":"形容词是在名词上构成的，其适用范围从人扩展到计划、建筑与日程。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin of ire, exact first date of the adjective): no precise citation marks the widening to buildings, and any Indo-European form offered for ire is a reconstruction.","cn":"来源不确定（ire 的更深来源与形容词确切的最早年代）：没有确切书证标出它何时扩展到建筑；凡为 ire 给出的印欧语形式均属重构形式。"}]},"similar":{"note":{"en":"Group one separates look-alikes built with the same around- prefix but a different verb; group two separates words of striving by their moral colour.","cn":"第一组区分同用「环绕」前缀但动词不同的形近词；第二组按道德色彩区分表示「争取」的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"ambiguous","ipa":"/æmˈbɪɡjuəs/","tag":"different verb","definition":"Ambi- 'around' plus agere 'to drive': driven two ways at once, hence unclear. It is not built on ire and has nothing to do with desire.","definitionCN":"由 ambi-「环绕」加 agere「驱动」构成：被同时往两个方向推，因而含混。它并非由 ire 构成，与渴望无关。"},{"word":"ambience","ipa":"/æmˈbiəns/","tag":"different root","definition":"From ambire in its older sense of surrounding: the atmosphere around a place, with no drive toward achievement.","definitionCN":"出自 ambire 更早的「环绕」义：一个地方周围的气氛，不含向上争取的劲头。"},{"word":"ambition","ipa":"/æmˈbɪʃən/","tag":"the noun behind it","definition":"The desire itself; the adjective reports the person who carries it.","definitionCN":"那份渴望本身；形容词报告的是怀着它的人。"},{"word":"ambit","ipa":"/ˈæmbɪt/","tag":"bounds, not desire","definition":"The scope or limits of something, from the same going-around verb but used for extent rather than longing.","definitionCN":"某事物的范围或界限，同出那个「绕行」动词，却用于范围而非渴望。"},{"word":"unambitious","ipa":"/ˌʌnæmˈbɪʃəs/","tag":"the negation","definition":"Without drive for advancement; it can be neutral or mildly critical, not a synonym of lazy.","definitionCN":"没有上进心；可中性也可略带批评，并不等于懒惰。"}]},{"heading":"NEAR MEANING","entries":[{"word":"aspiring","ipa":"/əˈspaɪərɪŋ/","tag":"hoping to enter","definition":"Hoping to become something, often used of beginners; it stresses the wish rather than the drive.","definitionCN":"希望成为某种人，多用于初入行者；强调愿望而非干劲。"},{"word":"driven","ipa":"/ˈdrɪvən/","tag":"compelled from inside","definition":"Compelled by an inner pressure to keep working; the source is need, not a chosen aim.","definitionCN":"被内在压力逼着不停工作；源头是需求，而非自选的目标。"},{"word":"enterprising","ipa":"/ˌentəˈpraɪzɪŋ/","tag":"bold in starting things","definition":"Ready to start new ventures and take risks; it looks at initiative rather than at rank.","definitionCN":"乐于开创并承担风险；看的是主动性，而不是位次。"},{"word":"greedy","ipa":"/ˈɡriːdi/","tag":"purely negative","definition":"Wanting far more than one needs, especially of money or food; it is appetite without the reach for honour.","definitionCN":"想要远超所需之物，尤指钱或食物；是贪欲，不含求名的那份伸手。"},{"word":"pretentious","ipa":"/prɪˈtenʃəs/","tag":"show over substance","definition":"Claiming more importance or culture than is really there; it shares the impressive-scale sense but judges it harshly.","definitionCN":"自称的重要或修养超过实际；与「气派规模」那一义相通，但评判更严厉。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The Latin picture is a candidate walking around the square asking for votes, which is where ambition begins.","cn":"拉丁语的图景是候选人在广场上四处走动拉票，抱负正是从这里开始的。"},{"en":"The family runs ambition, ambitious, ambitiously, ambitiousness, unambitious.","cn":"同族词覆盖名词、形容词、副词、程度名词与否定式。"},{"en":"Fixed phrases mark the fields: an ambitious plan, an ambitious target, politically ambitious.","cn":"固定搭配标出领域：宏大的计划、高难度的目标、政治上有野心。"},{"en":"The look-alike ambiguous uses a different verb for driving, so it means unclear rather than eager.","cn":"形近的 ambiguous 用的是另一个表示「驱动」的动词，所以它是含混而非急切。"},{"en":"Scale is the visible sign: ambitious buildings, ambitious schedules, ambitious first drafts.","cn":"规模是看得见的标志：气派的建筑、赶工的日程、急于求成的初稿。"}],"abstract":[{"en":"Picture a hand reaching for a rung that is one step higher than the foot can reach.","cn":"想象一只手去抓一格比脚能够到的高度更高的横档。"},{"en":"Picture a map with a route drawn past the edge of the paper.","cn":"想象一张地图，路线一直画到纸的边缘之外。"},{"en":"Picture a flag planted on a peak still hidden by cloud.","cn":"想象一面旗插在还被云遮住的山顶上。"}]},"examples":[{"en":"The foundation set an ambitious target of planting a million trees.","cn":"基金会定下了种一百万棵树的高目标。"},{"en":"He was ambitious for his students rather than for himself.","cn":"他为学生而非为自己寄予厚望。"},{"en":"An ambitious renovation ran out of money at the roof.","cn":"一次过于宏大的翻修在屋顶阶段就没钱了。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「俺必想上」——我心里一定要往上走 → 有雄心的","word":"ambitious"},"root":"拉丁 ambitio「绕行、四处拉票」← ambire「绕行」= ambi-（环绕）+ ire（走）；ire 的更深来源不确定。","sensesIntro":{"en":"Eight senses follow one gesture: a hand reaches beyond where the person now stands, and the adjective then judges either the reach, the plan, the cost, the drive, the overreach, the hope for another, the showy scale or the overload.","cn":"八个义项沿同一个动作展开：一只手伸到人现在所站之处以外，这个形容词随后评判那只手、那份计划、那笔代价、那股干劲、那次越界、对他人的期许、显摆的规模，或揽得过多。"},"semanticMap":{"core":{"en":"CORE IMAGE: a climber at the foot of the slope eyeing a summit higher than the rest.","cn":"核心意象：山脚的攀登者望着比周围都高的峰顶。"},"chain":["REACH OUT","WANT TO RISE","PLAN BIG","COST MORE","OVERREACH","BE JUDGED"],"branches":[{"senses":"01","en":"THE REACH ITSELF: the plain desire to rise, named with neither praise nor blame.","cn":"伸出的手本身：想上升的朴素愿望，既无褒也无贬。"},{"senses":"02 · 03","en":"BIG AND COSTLY: the same wish shows up as a large plan and as a heavy bill.","cn":"大而贵：同一份愿望，一处显现为宏大的计划，一处显现为沉重的代价。"},{"senses":"04 · 05","en":"TWO VERDICTS: the reach is praised as enterprise or blamed as overreach.","cn":"两种判决：这只手或被赞为进取，或被责为越界。"},{"senses":"06","en":"REACHING FOR ANOTHER: the hand is stretched toward someone else's rise.","cn":"伸向别人：这只手朝别人的上升伸去。"},{"senses":"07 · 08","en":"SCALE AS MESSAGE: impressive ceilings and overloaded drafts both overshoot what is needed.","cn":"规模即讯息：气派的天花板与超载的初稿，都超出了所需。"}]},"affixes":{"intro":{"en":"The word is a Latin noun plus an English adjective suffix; the prefix and the verb are both still productive in English.","cn":"这个词是一个拉丁名词加一个英语形容词后缀；其中的前缀与动词在英语里仍有构成力。"},"latinIntro":{"en":"Latin ire 'to go' gives exit, circuit and initial; ambi- appears in ambivalent, ambidextrous and ambient.","cn":"拉丁 ire「走」衍生出 exit、circuit 与 initial；ambi- 见于 ambivalent、ambidextrous 与 ambient。"},"items":[{"word":"ambi-","structure":"ambi- (Latin prefix, 'around, on both sides')","meaning":"around; both","meaningCN":"环绕；两侧","example":"The prefix puts the action on every side.","exampleCN":"这个前缀把动作放到四面八方。"},{"word":"ire","structure":"ire (Latin verb, 'to go')","meaning":"to go","meaningCN":"走","example":"The root supplies the motion.","exampleCN":"这个词根提供动作。"},{"word":"ambire","structure":"ambi- + ire","meaning":"to go around","meaningCN":"绕行","example":"Candidates walked around the square for votes.","exampleCN":"候选人在广场上绕行拉票。"},{"word":"ambitio","structure":"ambire + -tio (noun of action)","meaning":"a canvassing, a seeking of honour","meaningCN":"奔走拉票；求取荣誉","example":"The honour was sought by long canvassing.","exampleCN":"这份荣誉靠长期奔走争取。"},{"word":"ambition","structure":"ambitio passing into French and English","meaning":"a strong desire to rise","meaningCN":"上升的强烈愿望","example":"Her ambition was to run the laboratory.","exampleCN":"她的抱负是管理这个实验室。"},{"word":"ambitious","structure":"ambition + -ous (full of)","meaning":"full of the desire to rise","meaningCN":"充满上升愿望的","example":"The plan was ambitious but funded.","exampleCN":"这个计划宏大，但拿到了经费。"},{"word":"ambitiously","structure":"ambitious + -ly (adverb)","meaning":"in a reaching manner","meaningCN":"以有雄心的方式","example":"They ambitiously doubled the target.","exampleCN":"他们把目标雄心勃勃地翻了一倍。"},{"word":"ambitiousness","structure":"ambitious + -ness (quality)","meaning":"the degree of drive","meaningCN":"雄心的程度","example":"Her ambitiousness showed early.","exampleCN":"她的雄心很早就显露出来。"},{"word":"unambitious","structure":"un- + ambitious","meaning":"without drive to rise","meaningCN":"不图上升的","example":"An unambitious budget was approved.","exampleCN":"一份不图进取的预算获批。"},{"word":"ambivalent","structure":"ambi- + valere (to be worth)","meaning":"feeling two ways at once","meaningCN":"同时怀有两种感受的","example":"He was ambivalent about the transfer.","exampleCN":"他对这次调动犹豫不决。"}],"latinEntries":[{"word":"ire","structure":"ire, ivi or ii, itum (verb, irregular fourth conjugation)","meaning":"to go","meaningCN":"走"},{"word":"ambire","structure":"ambire, ambivi, ambitum (verb, fourth conjugation)","meaning":"to go around, canvass","meaningCN":"绕行；拉票"},{"word":"ambitio","structure":"ambitio, ambitionis (f., third declension)","meaning":"a canvassing, ambition","meaningCN":"奔走；抱负"},{"word":"ambitus","structure":"ambitus, ambitus (m., fourth declension)","meaning":"a going around, a circuit","meaningCN":"绕行；周界"}]}},{"word":"aspiration","ipa_uk":"/ˌæs.pɪˈreɪ.ʃən/","ipa_us":"/ˌæs.pəˈreɪ.ʃən/","definition_zh":"志向；渴望达到的目标；送气发音；吸入；抽吸；一丝气息","definition_en":"a strong hope or aim to achieve something, or the act of breathing something in","core_image":"一个人站在海边深吸一口气，眼睛望着对岸还看不见的灯光","scene":"她把想去对岸读书的念头写在信的末尾，写完又对着窗外深吸了一口气。Her aspiration to study abroad survived two failed applications.","sceneCN":"这里 aspiration 指「想要达到的目标与渴望」（第 1 个义项：志向上的愿望）；句意为她想出国读书的志向挺过了两次申请失败。图中可辨识物件：写满字的信纸、窗外对岸的灯光、被吸进胸腔的一口气、两次退回的信封。","pos":[{"tag":"n.","zh":"志向；渴望；送气音；吸入；抽吸"},{"tag":"n. (phonetics)","zh":"（语音学）送气"}],"collocations":[{"phrase":"career aspirations","zh":"职业志向"},{"phrase":"aspiration to do","zh":"做某事的志向"},{"phrase":"the aspirations of a community","zh":"一个群体的共同期盼"},{"phrase":"aspiration pneumonia","zh":"吸入性肺炎"},{"phrase":"aspirated consonant","zh":"送气辅音"},{"phrase":"high aspirations","zh":"很高的志向"}],"forms":[{"label":"单数","form":"aspiration"},{"label":"复数","form":"aspirations"},{"label":"动词","form":"aspire"},{"label":"动词三单","form":"aspires"},{"label":"动词过去式","form":"aspired"},{"label":"形容词","form":"aspirational"},{"label":"形容词（送气的）","form":"aspirated"}],"derivatives":[{"word":"aspire","pos":"v.","zh":"基础动词，来自拉丁语「向某处呼气」，语义为「渴望、立志」"},{"word":"aspirational","pos":"adj.","zh":"由名词加形容词后缀构成，语义由「志向」转为「以志向为标榜的」"},{"word":"aspirated","pos":"adj.","zh":"由过去分词转为形容词，语义由「送气」转为「带送气的」"},{"word":"aspirant","pos":"n.","zh":"由动词词干加表示人的后缀构成，语义由「渴望」转为「追求某职位的人」"}],"senses":[{"no":"01","title":"A hoped-for aim","titleCN":"想要达到的目标","definition":"a strong hope or ambition to achieve something in the future","definitionCN":"对未来取得某物所抱的强烈希望或志向","example":"Her aspiration to study abroad survived two failed applications.","exampleCN":"她想出国读书的志向挺过了两次申请失败。","why":"the Latin verb meant to breathe toward something, so an aspiration is a breath aimed at a distant object.","whyCN":"那个拉丁动词意为「朝某物呼气」，因此志向就是一缕朝远处目标呼出的气。"},{"no":"02","title":"Longing for high rank","titleCN":"对高位或大成就的渴望","definition":"a desire for a high position, honour or a distinguished place","definitionCN":"对高职位、荣誉或显要位置的渴求","example":"His aspiration to the chair was known to everyone but him.","exampleCN":"他想坐主席位子的心思，除了他自己，人人都知道。","why":"breathing toward a seat of honour is the social form of the same reach.","whyCN":"朝着荣誉之位呼一口气，是同一份伸手在社会层面的形态。"},{"no":"03","title":"Breath released in speech","titleCN":"说话时的送气","definition":"the audible burst of breath that follows some consonants, as in the p of pin","definitionCN":"某些辅音之后可听见的一股气流，如某些词首那个辅音之后的气","example":"The teacher marked the aspiration after the t with a small hook.","exampleCN":"老师在那个辅音之后用一个小钩标出送气。","why":"the phonetic sense is the literal one: breath pushed out at the moment of speaking.","whyCN":"语音义是最字面的用法：说话那一刻把气推出来。"},{"no":"04","title":"Drawing foreign matter into the lungs","titleCN":"异物被吸入肺里","definition":"the entry of food, liquid or other matter into the airway and lungs","definitionCN":"食物、液体或其他物质进入气道与肺部","example":"The nurse watched for aspiration during the night feed.","exampleCN":"夜间喂食时护士一直留意有无误吸。","why":"here breathing in becomes dangerous because what is drawn in does not belong in the lungs.","whyCN":"这里的「吸」变得危险，因为被吸进去的东西不该在肺里。"},{"no":"05","title":"Removal by suction","titleCN":"用抽吸取出","definition":"the use of suction to draw fluid or tissue out of a cavity","definitionCN":"用负压把液体或组织从腔体中吸出","example":"The aspiration of the cyst took less than a minute.","exampleCN":"囊肿的抽吸不到一分钟就完成了。","why":"the same drawing motion is turned to medical use, where breath is replaced by a pump.","whyCN":"同一个「吸」的动作被转作医疗用途，只是呼气换成了泵。"},{"no":"06","title":"Drawing fluid up a tube","titleCN":"机械抽吸液体","definition":"the lifting of liquid by reduced pressure in an engine, pump or laboratory line","definitionCN":"在发动机、泵或实验管路中借压差把液体吸上来","example":"Fuel aspiration failed when the line cracked.","exampleCN":"管路开裂后燃油抽吸失效。","why":"machines borrow the word because a pump also pulls matter toward itself by creating a void.","whyCN":"机器借用这个词，因为泵也靠制造空处把物质拉向自己。"},{"no":"07","title":"A breath of air","titleCN":"一丝气息、一阵微风","definition":"a single breath or a faint movement of air","definitionCN":"一次呼吸，或空气极轻微的流动","example":"An aspiration of wind came through the shutter and moved the ash.","exampleCN":"一丝风从百叶窗里进来，吹动了灰。","why":"the oldest physical layer survives in literary use, where the word means the air itself.","whyCN":"最古老的物理层在文学用法里留存，那里这个词指空气本身。"},{"no":"08","title":"Shared hopes of a group","titleCN":"一个群体共同的期盼","definition":"the collective hopes that a community or a generation holds for its future","definitionCN":"一个社群或一代人对自身未来所抱的共同希望","example":"The school was built on the aspirations of families who had never had one.","exampleCN":"这所学校建立于那些从未有过学校的家庭的期盼之上。","why":"many breaths aimed at one future add up to a public aspiration, which is how politics uses the word.","whyCN":"许多口气朝同一个未来呼出，就汇成一种公共期盼，政治语言正是这样用它的。"}],"etymology":{"intro":{"en":"Aspiration comes from Latin aspiratio 'a breathing upon', from aspirare 'to breathe toward', built on ad- 'to' and spirare 'to breathe'. The deeper origin of spirare is not settled. Dates are approximate.","cn":"该词来自拉丁 aspiratio「朝某物呼气」，其动词 aspirare「向……呼气」由 ad-「向」与 spirare「呼吸」构成。spirare 的更深来源尚无定论，年代均为约数。"},"items":[{"era":"LATIN SPIRARE","en":"Spirare meant 'to breathe, to blow'. Its deeper origin is uncertain; the comparison with a root for 'to blow' is a hypothesis rather than a demonstrated derivation.","cn":"spirare 意为「呼吸、吹」。其更深来源不确定；把它与表示「吹」的词根相比对，只是假说，并非已证实的派生。"},{"era":"LATIN ASPIRARE","en":"Ad- 'to' plus spirare gave aspirare 'to breathe upon, to blow toward', and by metaphor to favour or to strive toward.","cn":"ad-「向」加 spirare 构成 aspirare「朝……呼气、向……吹」，并比喻为「眷顾」或「向往」。"},{"era":"LATIN ASPIRATIO","en":"The noun aspiratio named the breathing and, in grammar, the rough breathing marked over certain letters.","cn":"名词 aspiratio 指这股呼气，并在语法中指标在某些字母上的粗气符号。"},{"era":"ENGLISH ARRIVAL","en":"English took the noun in the fourteenth century, first for the grammatical sense of rough breathing.","cn":"英语在十四世纪吸收了这个名词，最早用于语法上的「粗气」义。"},{"era":"MODERN RISE","en":"From the sixteenth century the word was used for a hope directed at a high aim, and the medical suction sense followed in the nineteenth.","cn":"从十六世纪起，这个词用于指向高目标的希望；医学上的抽吸义在十九世纪随后出现。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin of spirare and the dating of the hopeful sense): no citation fixes the first use for ambition, and any Indo-European form offered for spirare is a reconstruction.","cn":"来源不确定（spirare 的更深来源与希望义的确切年代）：没有书证能定住它首次用于「抱负」的时间；凡为 spirare 给出的印欧语形式均属重构形式。"}]},"similar":{"note":{"en":"Group one separates look-alikes built on the breathing verb from words that only sound similar; group two separates kinds of longing.","cn":"第一组区分同出「呼吸」动词的形近词与只是读音相近的词；第二组区分不同类型的渴望。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"aspire","ipa":"/əˈspaɪə/","tag":"the verb behind it","definition":"To aim at something high; the noun is the state, the verb is the reaching.","definitionCN":"朝高处立志；名词是那个状态，动词是那次伸手。"},{"word":"inspiration","ipa":"/ˌɪnspəˈreɪʃən/","tag":"breathed in","definition":"In- 'into' plus spirare: a breathing in, hence the sudden idea that seems to arrive from outside.","definitionCN":"由 in-「入」加 spirare 构成：吸进来，因而指仿佛从外面到来的灵感。"},{"word":"expiration","ipa":"/ˌekspəˈreɪʃən/","tag":"breathed out","definition":"Ex- 'out' plus spirare: breathing out, and by extension the end of a period when time has run out.","definitionCN":"由 ex-「出」加 spirare 构成：呼出，并引申指期限走完的到期。"},{"word":"respiration","ipa":"/ˌrespəˈreɪʃən/","tag":"breathing repeatedly","definition":"Re- 'again' plus spirare: the whole cycle of breathing, with no aim attached.","definitionCN":"由 re-「再」加 spirare 构成：整个呼吸循环，不含目标。"},{"word":"aspersion","ipa":"/əˈspɜːʃən/","tag":"sprinkling, then blame","definition":"From the same sprinkling verb, but it means a casting of doubt or a slander, not a hope.","definitionCN":"同出那个「洒、喷」的动词，但意思是对人泼脏水、造谣中伤，而非希望。"}]},{"heading":"NEAR MEANING","entries":[{"word":"ambition","ipa":"/æmˈbɪʃən/","tag":"drive for position","definition":"A strong desire to rise in status or power; it is more worldly than aspiration.","definitionCN":"对地位或权力上升的强烈欲望；比 aspiration 更世俗。"},{"word":"goal","ipa":"/ɡəʊl/","tag":"the concrete end","definition":"A specific end point one works toward; it is the target itself, not the longing for it.","definitionCN":"努力所指向的具体终点；是目标本身，而不是对目标的渴望。"},{"word":"dream","ipa":"/driːm/","tag":"cherished and vague","definition":"A cherished wish, often distant and not yet planned; it is warmer and looser than aspiration.","definitionCN":"珍爱的愿望，往往遥远且尚无计划；比 aspiration 更温暖也更松散。"},{"word":"yearning","ipa":"/ˈjɜːnɪŋ/","tag":"ache of longing","definition":"A deep and often painful longing; it stresses the ache rather than the plan to achieve.","definitionCN":"深沉而常带痛感的渴望；强调那份渴，而不是实现它的计划。"},{"word":"intake","ipa":"/ˈɪnteɪk/","tag":"the physical drawing in","definition":"The amount taken into the body or a machine in a period; it is the plain physical relative of the suction sense.","definitionCN":"一段时间内进入身体或机器的量；是抽吸义最朴素的物理近亲。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The Latin verb means to breathe toward something, so a strong hope is a breath aimed at a far target.","cn":"那个拉丁动词意为「朝某物呼气」，因此一份强烈的希望就是一缕朝远处目标呼出的气。"},{"en":"The family runs aspire, aspiration, aspirant, aspirational, aspirated.","cn":"同族词覆盖动词、名词、追求者、愿景式形容词与送气形容词。"},{"en":"Fixed phrases mark the fields: career aspirations, aspiration pneumonia, aspirated consonant.","cn":"固定搭配标出领域：职业志向、吸入性肺炎、送气辅音。"},{"en":"The same breathing verb gives inspiration, expiration and respiration, each with its own prefix direction.","cn":"同一个「呼吸」动词还给出 inspiration、expiration 与 respiration，各自带有自己的前缀方向。"},{"en":"Medical suction keeps the physical picture: something is drawn out of a cavity by reduced pressure.","cn":"医学抽吸保留了物理图景：靠压差把某物从腔体中吸出。"}],"abstract":[{"en":"Picture a long breath held while looking across water at lights not yet reachable.","cn":"想象隔水望着还够不到的灯光时，长长地屏住一口气。"},{"en":"Picture a seed on a sill, leaning toward a window it cannot move to.","cn":"想象窗台上的一粒种子，朝它无法移动过去的窗子倾斜。"},{"en":"Picture a letter written and rewritten but never sent, kept in a drawer.","cn":"想象一封写了又改、始终没寄出的信，放在抽屉里。"}]},"examples":[{"en":"The scholarship matched her aspiration with a place at the college.","cn":"这笔奖学金让她的志向与一个学院名额对上了。"},{"en":"Rural families spoke of their aspirations for a clinic of their own.","cn":"乡下家庭谈起他们想要一所自己的诊所的期盼。"},{"en":"The doctor ordered suction to prevent aspiration during sleep.","cn":"医生安排了吸痰，以防睡眠中误吸。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「a 斯匹瑞」——朝远处深吸一口气再向前望 → 志向、渴望","word":"aspiration"},"root":"拉丁 aspiratio「呼气」← aspirare「向……呼气」= ad-（向）+ spirare（呼吸）；spirare 更深来源不确定。","sensesIntro":{"en":"Eight senses follow one breath: air is aimed at a far object and becomes a hope; the same air is aimed at a seat of honour, then at a consonant, then drawn into a lung, then pulled by a pump, then felt as a faint wind, and finally shared by a whole community.","cn":"八个义项沿同一口气展开：气朝远处目标呼出而成希望；同一口气再朝荣誉之位、朝一个辅音、进一只肺、被泵抽动、化作一丝风，最后被整个社群共同呼出。"},"semanticMap":{"core":{"en":"CORE IMAGE: a long breath drawn at the shore while looking at lights across the water.","cn":"核心意象：站在岸边望着对岸的灯光，长长吸一口气。"},"chain":["BREATHE","AIM THE BREATH","HOPE FOR MORE","SOUND THE BREATH","DRAW MATTER IN","SHARE THE HOPE"],"branches":[{"senses":"01 · 02","en":"THE BREATH AIMED HIGH: hope for an aim and hunger for a seat of honour.","cn":"朝高处呼出的气：对目标的希望，以及对荣誉之位的渴求。"},{"senses":"03","en":"THE BREATH HEARD: phonetics keeps the literal push of air.","cn":"被听见的气：语音学保留了最字面的推气。"},{"senses":"04 · 06","en":"MATTER DRAWN IN: what enters a lung and what a pump pulls up a line.","cn":"被吸进的物质：进入肺里的东西，与泵沿着管路抽上来的东西。"},{"senses":"05","en":"MATTER TAKEN OUT: clinical suction reverses the direction and removes.","cn":"被取出的物质：临床抽吸把方向反过来，取走东西。"},{"senses":"07 · 08","en":"FROM A GUST TO A GENERATION: one faint breath widens into the shared hopes of many.","cn":"从一阵微风到一代人：一丝微弱的气，扩展成许多人的共同期盼。"}]},"affixes":{"intro":{"en":"The word is a Latin verb plus a noun suffix, and the same prefix and verb build several common English words, so the family is easy to read by parts.","cn":"这个词是一个拉丁动词加名词后缀，同一个前缀与动词还构成若干常用英语词，因此这一族很容易按部件读出。"},"latinIntro":{"en":"Latin spirare 'to breathe' gives spirit, inspire, expire, respire and conspire; ad- 'to' appears in adapt, adjacent and admire.","cn":"拉丁 spirare「呼吸」衍生出 spirit、inspire、expire、respire 与 conspire；ad-「向」见于 adapt、adjacent 与 admire。"},"items":[{"word":"ad-","structure":"ad- (Latin prefix, 'to, toward')","meaning":"to; toward","meaningCN":"向；朝","example":"The prefix points the breath at an object.","exampleCN":"这个前缀把气指向某个对象。"},{"word":"spirare","structure":"spirare (Latin verb, 'to breathe, blow')","meaning":"to breathe","meaningCN":"呼吸；吹","example":"The root carries the breathing.","exampleCN":"这个词根带着呼吸这个动作。"},{"word":"aspirare","structure":"ad- + spirare","meaning":"to breathe upon, strive toward","meaningCN":"朝……呼气；向往","example":"The wind seemed to strive toward the cliff.","exampleCN":"那阵风仿佛朝崖上使劲。"},{"word":"aspiration","structure":"aspirare + -tio (noun of action)","meaning":"a breathing toward, a hope","meaningCN":"朝某处呼气；志向","example":"Her aspiration was to build a clinic.","exampleCN":"她的志向是建一所诊所。"},{"word":"aspire","structure":"aspirare passing into French and English","meaning":"to aim high","meaningCN":"立志；渴望","example":"He aspired to the vacant chair.","exampleCN":"他渴望那把空出的椅子。"},{"word":"aspirant","structure":"aspire + -ant (person who acts)","meaning":"one who seeks a post","meaningCN":"谋求职位的人","example":"Ten aspirants sat the examination.","exampleCN":"十名求职者参加了考试。"},{"word":"aspirational","structure":"aspiration + -al (adjective)","meaning":"expressing or appealing to hopes","meaningCN":"标示志向的；励志的","example":"The poster was aspirational rather than factual.","exampleCN":"这张海报是励志的，而不是写实的。"},{"word":"aspirated","structure":"aspirate + -ed (participle)","meaning":"pronounced with a burst of breath","meaningCN":"带送气发音的","example":"The aspirated consonant was hard for the children.","exampleCN":"这个送气辅音让孩子们觉得难。"},{"word":"inspiration","structure":"in- + spirare + -tion","meaning":"a breathing in, a sudden idea","meaningCN":"吸入；灵感","example":"The design came in a single inspiration.","exampleCN":"这个设计来自一次顿悟。"},{"word":"expiration","structure":"ex- + spirare + -tion","meaning":"breathing out, the end of a term","meaningCN":"呼出；到期","example":"The lease reached expiration in June.","exampleCN":"租约在六月到期。"},{"word":"spirit","structure":"spiritus, from spirare","meaning":"breath, vital principle","meaningCN":"气息；精神","example":"The spirit of the place was quiet.","exampleCN":"这个地方的气息很安静。"}],"latinEntries":[{"word":"spirare","structure":"spirare, spiravi, spiratum (verb, first conjugation)","meaning":"to breathe, blow","meaningCN":"呼吸；吹"},{"word":"aspirare","structure":"aspirare, aspiravi, aspiratum (verb, first conjugation)","meaning":"to breathe upon, strive toward","meaningCN":"朝……呼气；向往"},{"word":"aspiratio","structure":"aspiratio, aspirationis (f., third declension)","meaning":"a breathing, a rough breathing","meaningCN":"呼气；粗气符号"},{"word":"spiritus","structure":"spiritus, spiritus (m., fourth declension)","meaning":"breath, spirit","meaningCN":"气息；精神"}]}},{"word":"aspire","ipa_uk":"/əˈspaɪər/","ipa_us":"/əˈspaɪr/","definition_zh":"立志；渴望达到；谋求职位；向往","definition_en":"to desire strongly to achieve something high or to become a certain kind of person","core_image":"一个孩子趴在窗台上，看远处塔楼的尖顶，一直看到脖子发酸","scene":"她十六岁那年看完一本关于深海的书，从此决定要做海洋生物学家。She aspired to study the deep sea years before any university had replied.","sceneCN":"这里 aspire 指「立志要达到某个高目标」（第 1 个义项：朝高处立志）；句意为在还没有任何大学回信之前，她早已立志研究深海。图中可辨识物件：远处的塔尖、被翻旧的深海书、窗台的手印、尚未拆封的回信。","pos":[{"tag":"vi.","zh":"立志；渴望（与 to、after 搭配）"},{"tag":"vt.","zh":"（语音学）以送气方式发音"}],"collocations":[{"phrase":"aspire to do","zh":"立志去做"},{"phrase":"aspire to a post","zh":"谋求某个职位"},{"phrase":"aspire after honour","zh":"渴求荣誉"},{"phrase":"aspire to become","zh":"渴望成为"},{"phrase":"aspiring artist","zh":"有志向的艺术家"},{"phrase":"aspire to greatness","zh":"向往卓越"}],"forms":[{"label":"三单（he/she/it）","form":"aspires"},{"label":"过去式","form":"aspired"},{"label":"过去分词","form":"aspired"},{"label":"现在分词","form":"aspiring"},{"label":"名词（志向）","form":"aspiration"},{"label":"名词（追求者）","form":"aspirant"}],"derivatives":[{"word":"aspiration","pos":"n.","zh":"由动词加表示行为的名词后缀构成，语义由「朝高处呼气」转为「志向」"},{"word":"aspirant","pos":"n.","zh":"由动词词干加表示人的后缀构成，语义由「渴望」转为「谋求者」"},{"word":"aspiring","pos":"adj.","zh":"由现在分词转为形容词，语义由「正立志」转为「有志于进入某行的」"},{"word":"aspirational","pos":"adj.","zh":"由名词加形容词后缀构成，语义由「志向」转为「带有志向色彩的、励志的」"}],"senses":[{"no":"01","title":"Aim at a distant goal","titleCN":"朝远处的目标立志","definition":"to set one's hopes on a goal that lies well beyond present reach","definitionCN":"把希望放在一个远超出当下能力所及的目标上","example":"She aspired to study the deep sea long before any university had replied.","exampleCN":"在还没有任何大学回信之前，她早已立志研究深海。","why":"the Latin verb means to breathe toward something, so aspiring is aiming one's whole breath at a far object.","whyCN":"那个拉丁动词意为「朝某物呼气」，因此立志就是把整口气都朝一个远处的对象呼去。"},{"no":"02","title":"Seek a particular office","titleCN":"谋求某个职位","definition":"to try to obtain a post, title or place that others may also want","definitionCN":"试图取得一个别人也想要的职位、头衔或位子","example":"Three deputies aspired to the vacant chair.","exampleCN":"三位副手都想坐上那把空出的椅子。","why":"the Roman picture was a candidate walking around to court votes, and that political sense never left the word.","whyCN":"罗马的图景是候选人四处奔走拉票，那层政治意味从未离开这个词。"},{"no":"03","title":"Want to become a certain person","titleCN":"渴望成为某种人","definition":"to wish to turn oneself into a particular kind of person or worker","definitionCN":"希望把自己变成某一类人或某一种从业者","example":"He aspired to be a country doctor rather than a famous surgeon.","exampleCN":"他想做乡村医生，而不是名医。","why":"the aim is no longer a thing but an identity, and the same upward breath is directed at a self to be built.","whyCN":"目标不再是一件东西，而是一种身份，同一口向上的气被呼向一个待建成的自己。"},{"no":"04","title":"Emulate a standard","titleCN":"以更高的标准为榜样","definition":"to measure oneself against a model or a standard set by others","definitionCN":"拿自己与别人立下的榜样或标准相比照","example":"Her early drawings aspired to the plainness of the old masters.","exampleCN":"她早期的素描向往古代大师那种朴素。","why":"breathing toward a model is how skill is acquired: one imitates before one can invent.","whyCN":"朝榜样呼气正是技艺获得的途径：先模仿，才谈得上创造。"},{"no":"05","title":"Hope for an ideal condition","titleCN":"向往一种理想状态","definition":"to long for a better condition such as peace, fairness or quiet","definitionCN":"渴望更好的处境，如和平、公平或安宁","example":"The whole valley aspired to nothing more than a quiet winter.","exampleCN":"整个山谷向往的不过是一个安静的冬天。","why":"the object can be a condition rather than a possession, which is why the word suits public hopes.","whyCN":"对象可以是一种处境而非一件所有物，因此这个词适合表达公共的希望。"},{"no":"06","title":"Rise physically","titleCN":"向上高耸（古义）","definition":"to rise or tower upward, said of buildings, smoke or terrain in older prose","definitionCN":"向上升起或高耸，旧时用于建筑、烟或地形","example":"The spire aspired so high that the bells could be heard across the river.","exampleCN":"那尖顶高耸，钟声在河对岸都听得见。","why":"this is the plain physical sense of breathing upward, before the word was narrowed to desire.","whyCN":"这是「向上呼气」最朴素的物理义，出现在词义收窄为「渴望」之前。"},{"no":"07","title":"Pronounce with a breath","titleCN":"以送气方式发音","definition":"to utter a consonant with a audible puff of breath, as in the p of pin","definitionCN":"发音时带出一股听得见的气，如某些词里那个辅音之后的气","example":"In this dialect speakers aspire the t at the end of a word.","exampleCN":"在这个方言里，说话人会把词尾那个辅音发成送气音。","why":"phonetics kept the literal meaning, since the sound really is a breath pushed out.","whyCN":"语音学保留了字面意思，因为那个音确实就是被推出来的一口气。"},{"no":"08","title":"Long for something intensely","titleCN":"强烈渴求某物","definition":"to desire something intensely, often used with after in formal prose","definitionCN":"强烈地想要某物，正式文字中后面常接一个介词","example":"The exiled poet aspired after one more sight of the hills.","exampleCN":"流亡的诗人心心念念再看一眼那些山。","why":"when the object is out of reach, the verb carries pure longing rather than a plan.","whyCN":"当对象无法到手，这个动词就带着纯粹的渴，而不是一份计划。"}],"etymology":{"intro":{"en":"Aspire comes from Latin aspirare 'to breathe upon, to blow toward', built on ad- 'to' and spirare 'to breathe'. The deeper origin of spirare is not settled. Dates are approximate.","cn":"该词来自拉丁 aspirare「朝……呼气、向……吹」，由 ad-「向」与 spirare「呼吸」构成。spirare 的更深来源尚无定论，年代均为约数。"},"items":[{"era":"LATIN SPIRARE","en":"Spirare meant 'to breathe, to blow'. Its deeper origin is uncertain; the tie proposed to a root for 'to blow' is a hypothesis rather than a demonstrated derivation.","cn":"spirare 意为「呼吸、吹」。其更深来源不确定；把它与表示「吹」的词根相联系，只是假说，并非已证实的派生。"},{"era":"LATIN ASPIRARE","en":"Ad- 'to' plus spirare gave aspirare 'to breathe upon', and metaphorically to favour someone or to strive toward something.","cn":"ad-「向」加 spirare 构成 aspirare「朝……呼气」，并比喻为「眷顾某人」或「向往某物」。"},{"era":"POLITICAL SHADE","en":"Roman writers used the verb for courting support, so the word entered English with a political edge before it meant plain longing.","cn":"罗马作家用这个动词表示争取支持，因此这个词带着政治色彩进入英语，早于它表示单纯渴望。"},{"era":"FOURTEENTH CENTURY","en":"English took the verb in the fourteenth century, at first in the sense of rising or towering, then of hoping for high things.","cn":"英语在十四世纪吸收了这个动词，先表「升起、高耸」，再表「向往高处之物」。"},{"era":"PHONETIC USE","en":"Grammarians applied the same word to consonants pronounced with breath, which is the oldest physical layer kept in technical use.","cn":"语法学家把同一个词用于带气发音的辅音，这是最古老的物理层在技术用语中的保存。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin of spirare and the dating of the hopeful sense): no citation fixes when rising became longing, and any Indo-European form offered for spirare is a reconstruction.","cn":"来源不确定（spirare 的更深来源与希望义的确切年代）：没有书证能定住「升起」何时变成「渴望」；凡为 spirare 给出的印欧语形式均属重构形式。"}]},"similar":{"note":{"en":"Group one separates words built on the same breathing verb; group two separates verbs of wanting by how reachable the object is.","cn":"第一组区分同出「呼吸」动词的词；第二组按对象的可达程度区分表示「想要」的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"inspire","ipa":"/ɪnˈspaɪə/","tag":"breath drawn in","definition":"In- 'into' plus spirare: to breathe a feeling into someone, hence to fill them with enthusiasm.","definitionCN":"由 in-「入」加 spirare 构成：把某种感受吹进别人心里，因而指激发热情。"},{"word":"expire","ipa":"/ɪkˈspaɪə/","tag":"breath pushed out","definition":"Ex- 'out' plus spirare: to breathe out one's last breath, hence to come to an end.","definitionCN":"由 ex-「出」加 spirare 构成：呼出最后一口气，因而指终了、到期。"},{"word":"conspire","ipa":"/kənˈspaɪə/","tag":"breathing together","definition":"Com- 'together' plus spirare: to breathe as one, hence to plot together in secret.","definitionCN":"由 com-「共同」加 spirare 构成：同呼一口气，因而指暗中合谋。"},{"word":"perspire","ipa":"/pəˈspaɪə/","tag":"breathing through","definition":"Per- 'through' plus spirare: to breathe through the skin, that is, to sweat.","definitionCN":"由 per-「穿过」加 spirare 构成：透过皮肤呼气，也就是出汗。"},{"word":"asperity","ipa":"/əˈsperəti/","tag":"different root","definition":"From Latin asper 'rough': harshness of surface or manner, with no connection to breathing.","definitionCN":"来自拉丁 asper「粗糙」：表面或态度的粗硬，与呼吸无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"hope","ipa":"/həʊp/","tag":"open and unplanned","definition":"To want something with a real chance in view; it can be modest, while aspiring is always aimed high.","definitionCN":"在还看得见机会的情况下想要某事；可以很小，而立志总是朝高处。"},{"word":"wish","ipa":"/wɪʃ/","tag":"wanting without action","definition":"To want something, often without any plan to get it; it carries no effort.","definitionCN":"想要某物，往往没有任何获取的计划；不含努力。"},{"word":"long","ipa":"/lɒŋ/","tag":"emotional ache","definition":"To feel a deep and often painful desire; the feeling outweighs the aim.","definitionCN":"怀着深沉而常带痛的渴望；感受压过了目标。"},{"word":"seek","ipa":"/siːk/","tag":"active search","definition":"To try actively to find or obtain something; it names the activity rather than the ambition.","definitionCN":"积极地设法找到或取得；指活动，而不是抱负。"},{"word":"strive","ipa":"/straɪv/","tag":"effort against resistance","definition":"To struggle hard toward something; it stresses the exertion, while aspire stresses the height of the aim.","definitionCN":"奋力朝某处挣扎；强调使力，而 aspire 强调目标的高度。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Ad- 'to' plus spirare 'breathe': to breathe toward something far away.","cn":"ad-「向」加 spirare「呼吸」：朝远处某物呼出一口气。"},{"en":"The family runs aspire, aspiration, aspirant, aspiring, aspirational.","cn":"同族词覆盖动词、名词、谋求者、现在分词形容词与励志形容词。"},{"en":"Fixed phrases mark the objects: aspire to a post, aspire to become, aspire after honour.","cn":"固定搭配标出对象：谋求职位、渴望成为、渴求荣誉。"},{"en":"The political origin survives in aspirant, the person who wants the seat.","cn":"政治来源仍活在「谋求者」这个名词里，指那个想要位子的人。"},{"en":"Phonetics keeps the oldest sense: an aspirated consonant is a sound carrying a puff of breath.","cn":"语音学保留了最古老的意思：送气辅音就是带出一口气的音。"}],"abstract":[{"en":"Picture a child on a sill looking at a spire until the neck aches.","cn":"想象一个孩子趴在窗台上望着塔尖，直到脖子发酸。"},{"en":"Picture a kite pulling at the string before the wind has lifted it.","cn":"想象一只风筝在风还没把它托起时就已经把线拉紧。"},{"en":"Picture a seed leaning toward a light it cannot yet reach.","cn":"想象一粒种子朝它还够不到的光倾斜。"}]},"examples":[{"en":"Many young engineers aspire to work on the rover team.","cn":"许多年轻工程师立志进入火星车团队。"},{"en":"He aspired to the mayor's office for twelve years.","cn":"他谋求市长之位谋了十二年。"},{"en":"The village aspired after clean water more than after roads.","cn":"村民对干净用水的渴求胜过对道路的渴求。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「a 斯派尔」——一口气朝远处送去 → 立志、渴望","word":"aspire"},"root":"拉丁 aspirare「朝……呼气」= ad-（向）+ spirare（呼吸）；spirare 更深来源不确定。","sensesIntro":{"en":"Eight senses follow one breath: it is aimed at a goal, at an office, at an identity, at a model, at a condition, at the sky itself, at a consonant, and finally at something simply out of reach.","cn":"八个义项沿同一口气展开：这口气被呼向一个目标、一个职位、一种身份、一个榜样、一种处境、天空本身、一个辅音，最后呼向一件单纯够不到的东西。"},"semanticMap":{"core":{"en":"CORE IMAGE: a watcher at a window breathing toward a distant spire.","cn":"核心意象：窗前的观望者朝远处塔尖呼出一口气。"},"chain":["BREATHE TOWARD","SET A HIGH AIM","SEEK A PLACE","BUILD AN IDENTITY","IMITATE A MODEL","RISE AND LONG"],"branches":[{"senses":"01 · 05","en":"THE AIM AND THE CONDITION: a distant goal and a wished-for state are the same upward breath.","cn":"目标与处境：远处的目标与所盼的处境，是同一口向上的气。"},{"senses":"02","en":"THE CONTESTED SEAT: others want it too, and the political origin shows.","cn":"被争的位子：别人也想要，政治来源在此显现。"},{"senses":"03 · 04","en":"A SELF TO BUILD: a person and a model are both aims one grows toward.","cn":"待建的自己：人与榜样都是会长过去的靶子。"},{"senses":"06","en":"THE LITERAL RISE: stone and smoke go up before desire is meant.","cn":"字面的升起：在「渴望」之前，石头与烟先往上升。"},{"senses":"07 · 08","en":"BREATH WITHOUT AN OBJECT: a consonant's puff, and longing that has given up on arrival.","cn":"没有对象的气：辅音的那一口气，以及不再指望抵达的渴望。"}]},"affixes":{"intro":{"en":"The word is a Latin verb with a prepositional prefix, and both parts still build English words, so it reads clearly by morphemes.","cn":"这个词是一个带介词前缀的拉丁动词，两部分仍在构成英语词，因此可以按语素清楚读出。"},"latinIntro":{"en":"Latin spirare gives spirit, inspire, expire, respire and conspire; ad- 'to' appears in adapt, adhere and admire.","cn":"拉丁 spirare 衍生出 spirit、inspire、expire、respire 与 conspire；ad-「向」见于 adapt、adhere 与 admire。"},"items":[{"word":"ad-","structure":"ad- (Latin prefix, 'to, toward')","meaning":"to; toward","meaningCN":"向；朝","example":"The prefix gives the breath a direction.","exampleCN":"这个前缀给这口气一个方向。"},{"word":"spirare","structure":"spirare (Latin verb, 'to breathe')","meaning":"to breathe; to blow","meaningCN":"呼吸；吹","example":"The root is the breathing itself.","exampleCN":"这个词根就是呼吸本身。"},{"word":"aspirare","structure":"ad- + spirare","meaning":"to breathe upon","meaningCN":"朝……呼气","example":"The wind breathed upon the cliff.","exampleCN":"风朝崖壁吹去。"},{"word":"aspire","structure":"aspirare passing into French and English","meaning":"to aim high","meaningCN":"立志；向往","example":"She aspired to the research post.","exampleCN":"她立志争取这个研究职位。"},{"word":"aspiring","structure":"aspire + -ing (participle adjective)","meaning":"hoping to enter a field","meaningCN":"有志于进入某行的","example":"An aspiring novelist worked the night shift.","exampleCN":"一位有志写小说的人上夜班。"},{"word":"aspirant","structure":"aspire + -ant (person)","meaning":"a seeker of a post","meaningCN":"谋求职位者","example":"Four aspirants were shortlisted.","exampleCN":"四名谋求者进入候选名单。"},{"word":"aspiration","structure":"aspirare + -tion (noun of action)","meaning":"a hope, a breathing toward","meaningCN":"志向；朝某处呼气","example":"His aspiration was to teach in the hills.","exampleCN":"他的志向是在山里教书。"},{"word":"aspirational","structure":"aspiration + -al (adjective)","meaning":"appealing to hopes","meaningCN":"引发向往的","example":"The brochure was aspirational, not literal.","exampleCN":"这本宣传册是在引发向往，而非写实。"},{"word":"aspirate","structure":"aspirare + -ate (verb)","meaning":"to pronounce with breath","meaningCN":"送气发音","example":"Children aspirate the first consonant too strongly.","exampleCN":"孩子们把第一个辅音送气送得太重。"},{"word":"inspire","structure":"in- + spirare","meaning":"to breathe into","meaningCN":"吹入；激发","example":"The valley inspired the whole score.","exampleCN":"这条山谷激发了整部乐曲。"},{"word":"expire","structure":"ex- + spirare","meaning":"to breathe out, to end","meaningCN":"呼出；到期","example":"The permit expired in March.","exampleCN":"许可证在三月到期。"}],"latinEntries":[{"word":"spirare","structure":"spirare, spiravi, spiratum (verb, first conjugation)","meaning":"to breathe, blow","meaningCN":"呼吸；吹"},{"word":"aspirare","structure":"aspirare, aspiravi, aspiratum (verb, first conjugation)","meaning":"to breathe upon","meaningCN":"朝……呼气"},{"word":"aspiratio","structure":"aspiratio, aspirationis (f., third declension)","meaning":"a breathing, a rough breathing","meaningCN":"呼气；粗气符号"},{"word":"spiritus","structure":"spiritus, spiritus (m., fourth declension)","meaning":"breath, spirit","meaningCN":"气息；精神"}]}},{"word":"purpose","ipa_uk":"/ˈpɜː.pəs/","ipa_us":"/ˈpɝː.pəs/","definition_zh":"目的；意图；用途；决心；意义；宗旨","definition_en":"the reason for which something is done, made or exists","core_image":"木匠在工作台上把一块木板摆正，用粉线弹出一条笔直的线，才落下第一锯","scene":"开工之前，工头把图纸摊在木板上，用手指按住那条基准线，说明这块料为什么要留厚两毫米。The purpose of the extra thickness was to allow a second plane pass.","sceneCN":"这里 purpose 指「做某件事所依据的目的」（第 1 个义项：意图与目的）；句意为多留那两毫米是为了还能再刨一次。图中可辨识物件：摊开的图纸、按住基准线的手指、弹过粉线的木板、留下的余量。","pos":[{"tag":"n.","zh":"目的；意图；用途；决心；意义；宗旨"},{"tag":"vt.","zh":"（较少用）打算；意图"}],"collocations":[{"phrase":"the purpose of","zh":"……的目的"},{"phrase":"on purpose","zh":"故意地"},{"phrase":"serve a purpose","zh":"起到某种作用"},{"phrase":"fit for purpose","zh":"适合其用途的"},{"phrase":"a sense of purpose","zh":"目标感；意义感"},{"phrase":"to no purpose","zh":"毫无结果地"},{"phrase":"for the purpose of","zh":"为了……的目的"}],"forms":[{"label":"单数","form":"purpose"},{"label":"复数","form":"purposes"},{"label":"形容词（有目的的）","form":"purposeful"},{"label":"副词（故意地）","form":"purposely"},{"label":"形容词（无目的的）","form":"purposeless"},{"label":"名词（目的性）","form":"purposefulness"}],"derivatives":[{"word":"purposeful","pos":"adj.","zh":"由名词加表示「充满」的形容词后缀构成，语义由「目的」转为「有明确目的的」"},{"word":"purposely","pos":"adv.","zh":"由名词加副词后缀构成，语义由「意图」转为「故意地」"},{"word":"purposeless","pos":"adj.","zh":"加表示「缺少」的形容词后缀构成，语义由「目的」转为「没有目的的」"},{"word":"purpose-built","pos":"adj.","zh":"由名词与过去分词复合而成，语义由「用途」转为「专为某用途建造的」"},{"word":"multipurpose","pos":"adj.","zh":"加表示「多」的前缀构成，语义由「用途」转为「一物多用的」"}],"senses":[{"no":"01","title":"The reason for an act","titleCN":"做一件事的理由与意图","definition":"the reason one has in mind for doing something or for making something","definitionCN":"做某事或造某物时心里所抱的理由","example":"The purpose of the extra thickness was to allow a second plane pass.","exampleCN":"多留那两毫米，是为了还能再刨一次。","why":"the word comes from putting something forward, so a purpose is the aim a person sets in front of the work before starting it.","whyCN":"这个词来自「把某物摆到前面」，因此目的就是开工前把目标摆在工作前面的那件事。"},{"no":"02","title":"The function of a thing","titleCN":"某物所承担的用途","definition":"the job that an object or a part is designed to perform","definitionCN":"一件物件或部件被造出来所要承担的功能","example":"This room has outlived its original purpose as a laundry.","exampleCN":"这间屋子原本用作洗衣房，如今那个用途早已过去了。","why":"the aim moves from the maker's head into the made thing, where it becomes a function.","whyCN":"目标从造物者的脑子里移到被造之物里，在那里它就成了一种功能。"},{"no":"03","title":"Firmness of intention","titleCN":"意志上的坚定","definition":"resolute determination to carry out what one has decided","definitionCN":"把已经决定的事做到底的那份坚决","example":"He spoke with purpose and nobody interrupted.","exampleCN":"他说话带着决心，没人打断。","why":"a settled intention shows in the manner of speech, and the noun then names the firmness rather than the aim.","whyCN":"已定的意图会显现在说话的方式上，此时名词指的是那份坚定，而不是目标。"},{"no":"04","title":"Relevance to the matter","titleCN":"与正题的相关性","definition":"the quality of bearing on the question at hand, as in remarks that are to the purpose","definitionCN":"与眼前问题相干的品质，如「切题」的话","example":"Every question was to the purpose, and the meeting ended early.","exampleCN":"每个问题都切中正题，会议提前结束。","why":"what is aimed at the matter in hand is relevant, so a fixed phrase marks this older, narrower sense.","whyCN":"对准眼前事务的就是相关的，因此一个固定说法保存了这条更窄的旧义。"},{"no":"05","title":"Meaning in a life","titleCN":"人生的意义感","definition":"the sense that one's existence or work has a point worth serving","definitionCN":"觉得自己的存在或工作有一个值得效力的要点","example":"Teaching gave her a purpose she had not found in the laboratory.","exampleCN":"教书给了她一种在实验室里没找到的意义。","why":"when the aim is large enough to organize a life, the word shifts from a task to a reason for living.","whyCN":"当目标大到足以组织一生，这个词就从一项任务转为活着的理由。"},{"no":"06","title":"A stated aim of an institution","titleCN":"机构明示的宗旨","definition":"the declared aim that a body, a fund or a law is set up to serve","definitionCN":"一个机构、基金或法律被设立时所声明的目标","example":"The fund's purpose is written on its first page.","exampleCN":"这只基金的宗旨写在第一页上。","why":"organizations must put their aim forward in writing, which keeps the original image of placing something in front.","whyCN":"机构必须把目标写在前面，这保留了「把某物摆到前面」的原初意象。"},{"no":"07","title":"Result actually achieved","titleCN":"实际取得的效果","definition":"the outcome that an action actually produces, as in efforts that came to good purpose","definitionCN":"一个行动实际产生的效果，如「见了效」的努力","example":"All the digging came to good purpose when the well struck water.","exampleCN":"井里出水时，所有挖掘都见了效。","why":"an aim that is realized becomes a result, and older English used the noun for that realized effect.","whyCN":"实现的目标会变成结果，旧时英语就用这个名词指那种已实现的效用。"},{"no":"08","title":"A proposal or intent","titleCN":"提议、打算（较旧用法）","definition":"a plan or proposal one puts forward, the sense closest to the French source","definitionCN":"一个人摆出来的计划或提议，是最贴近法语来源的一层","example":"Their purpose was to rebuild the mill before winter.","exampleCN":"他们的打算是在入冬前把磨坊重建起来。","why":"the French ancestor meant a proposal put forward, and this plain sense still surfaces in formal writing.","whyCN":"法语祖词意为「摆出来的提议」，这一朴素义仍会在正式文字中浮现。"}],"etymology":{"intro":{"en":"Purpose comes through Old French porpos 'aim, intention' from porposer 'to put forth', a variant of proposer, which rests on Latin proponere 'to put forward', built on pro- 'forward' and ponere 'to place'. The deeper origin of ponere is not settled. Dates are approximate.","cn":"该词经古法语 porpos「目标、意图」来自 porposer「摆出、提出」，那是 proposer 的变体，其源头是拉丁 proponere「放到前面」，由 pro-「向前」与 ponere「放置」构成。ponere 的更深来源尚无定论，年代均为约数。"},"items":[{"era":"LATIN PONERE","en":"Ponere meant 'to put, place, set'. Its deeper origin is uncertain; the proposal that links it to a root for 'to place' is circular and adds nothing, so the source is best left open.","cn":"ponere 意为「放、置、摆」。其更深来源不确定；把它与另一个同样表示「放置」的词根相联系只是循环解释，并无增益，因此来源宜存疑。"},{"era":"LATIN PROPONERE","en":"Pro- 'forward' plus ponere gave proponere 'to put forward, set before one', used of plans, terms and proposals.","cn":"pro-「向前」加 ponere 构成 proponere「摆到前面、置于眼前」，用于计划、条款与提议。"},{"era":"OLD FRENCH PORPOSER","en":"Old French porposer 'to put forth, intend' produced the noun porpos, which named both the aim and the resolve behind it.","cn":"古法语 porposer「提出、打算」产生名词 porpos，兼指目标与背后的决心。"},{"era":"MIDDLE ENGLISH","en":"Middle English took purpose for an intention, and the phrase on purpose later fixed the sense of doing something deliberately.","cn":"中古英语用这个词表示意图，后来固定说法「故意地」把「有意为之」的意思定了下来。"},{"era":"INSTITUTIONAL USE","en":"Modern law and administration use the noun for the declared aim of a body, which is the oldest image of putting an aim in front of the work.","cn":"现代法律与行政用这个名词指机构声明的宗旨，这正是「把目标摆在工作前面」最古老的意象。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin of ponere and the exact date of the deliberateness phrase): no citation fixes the first use for an institution's aim, and any Indo-European form offered for ponere is a reconstruction.","cn":"来源不确定（ponere 的更深来源与「故意」说法确切成形的年代）：机构宗旨义没有确切的最早书证；凡为 ponere 给出的印欧语形式均属重构形式。"}]},"similar":{"note":{"en":"Group one separates verbs and nouns built on the same placing root; group two separates words for an aim by how explicit it is.","cn":"第一组区分同出「放置」词根的动词与名词；第二组按明确程度区分表示「目标」的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"propose","ipa":"/prəˈpəʊz/","tag":"the verb of putting forward","definition":"The direct relative: to put a plan or an offer before others, from the same Latin verb.","definitionCN":"最直接的同族词：把计划或提议摆到别人面前，同出那个拉丁动词。"},{"word":"pose","ipa":"/pəʊz/","tag":"place, then posture","definition":"From the same placing verb through French: to put something forward, hence to set a question or hold a position.","definitionCN":"同出那个「放置」动词经法语而来：把某物摆出，因而指提出问题或摆出姿势。"},{"word":"impose","ipa":"/ɪmˈpəʊz/","tag":"put upon","definition":"In- 'upon' plus ponere: to place a burden on someone, which is the same root pressing downward.","definitionCN":"由 in-「在上」加 ponere 构成：把负担压在别人身上，同一词根往下用力。"},{"word":"compose","ipa":"/kəmˈpəʊz/","tag":"place together","definition":"Com- 'together' plus ponere: to put parts together, hence to write or to calm oneself.","definitionCN":"由 com-「共同」加 ponere 构成：把部件放到一起，因而指写作或使镇定。"},{"word":"purport","ipa":"/pəˈpɔːt/","tag":"different root","definition":"From pro- plus portare 'to carry': to carry a meaning or a claim, with no placing involved and no shared root.","definitionCN":"由 pro- 加 portare「搬运」构成：承载某种含义或声称，不含「放置」，也不同根。"}]},{"heading":"NEAR MEANING","entries":[{"word":"aim","ipa":"/eɪm/","tag":"the pointed target","definition":"The thing one intends to hit or reach; it is sharper and more specific than purpose.","definitionCN":"打算击中或抵达的东西；比 purpose 更尖锐、更具体。"},{"word":"goal","ipa":"/ɡəʊl/","tag":"the measurable end","definition":"A defined end point one can mark and check; purpose is broader and can be a reason rather than a finish line.","definitionCN":"一个可标示、可核对的明确终点；purpose 更宽，可以是理由而非终点线。"},{"word":"intention","ipa":"/ɪnˈtenʃən/","tag":"what one means to do","definition":"What a person means to do, often before acting; it is closer to the mental state than to the thing served.","definitionCN":"一个人打算做什么，多在行动之前；更接近心理状态，而不是所服务的事。"},{"word":"reason","ipa":"/ˈriːzən/","tag":"the explanation","definition":"The explanation of why something is as it is; it can look backward, while purpose looks forward.","definitionCN":"解释某事为何如此的理由；可以向后看，而 purpose 向前看。"},{"word":"function","ipa":"/ˈfʌŋkʃən/","tag":"what a thing does","definition":"The work a thing performs; it is the mechanical face of purpose.","definitionCN":"一件东西所执行的工作；是 purpose 在机械层面的面孔。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The root means to place, and the prefix means forward: a purpose is an aim placed in front of the work.","cn":"词根意为「放置」，前缀意为「向前」：目的就是被摆在工作前面的那个目标。"},{"en":"The family runs purpose, purposeful, purposely, purposeless, purpose-built, multipurpose.","cn":"同族词覆盖名词、形容词、副词、否定式与两个复合词。"},{"en":"Fixed phrases mark the uses: on purpose, serve a purpose, fit for purpose, a sense of purpose.","cn":"固定搭配标出用法：故意地、起作用、适合用途、目标感。"},{"en":"The siblings propose, pose, impose and compose all come from the same placing verb.","cn":"同族的 propose、pose、impose 与 compose 都出自那个「放置」动词。"},{"en":"The look-alike purport comes from a verb meaning to carry, so it means to claim rather than to intend.","cn":"形近的 purport 出自一个意为「搬运」的动词，所以它的意思是「声称」而非「打算」。"}],"abstract":[{"en":"Picture a chalk line snapped on a board before the first cut.","cn":"想象第一锯之前，木板上先弹出的一条粉线。"},{"en":"Picture a sign at the head of a path saying what the path is for.","cn":"想象一条小路的起点立着一块牌子，写着这条路是为什么修的。"},{"en":"Picture a lamp aimed at one desk rather than lighting the whole room.","cn":"想象一盏灯只照一张桌子，而不是照亮整间屋子。"}]},"examples":[{"en":"The purpose of the new rule is to slow the traffic at the gate.","cn":"新规定的目的是让门口的车辆慢下来。"},{"en":"He knocked the cup over on purpose and then apologized.","cn":"他故意碰倒杯子，然后又道了歉。"},{"en":"The building has served its purpose and will be pulled down.","cn":"这座楼已经完成它的用途，将被拆除。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「purpose 破的」——先想清楚为什么做，才不容易把事情做破 → 目的","word":"purpose"},"root":"古法语 porpos「目标、意图」← porposer「提出」← 拉丁 proponere「放到前面」= pro-（向前）+ ponere（放置）；ponere 更深来源不确定。","sensesIntro":{"en":"Eight senses follow one gesture: an aim is placed in front of the work, and that placed aim then becomes a function, a firmness, a relevance, a reason for living, an institutional charter, a realized effect and finally a plain proposal.","cn":"八个义项沿同一个动作展开：先把目标摆到工作前面，这个被摆出的目标随后变成一项功能、一份坚定、一种相关性、一个活着的理由、一纸机构宗旨、一个已实现的效果，最后成为一句朴素的提议。"},"semanticMap":{"core":{"en":"CORE IMAGE: a snapped chalk line laid on a board before the saw goes in.","cn":"核心意象：锯子落下之前，先在被板上弹出一条粉线。"},"chain":["SET AN AIM","PLACE IT BEFORE","GUIDE THE WORK","GIVE A FUNCTION","HOLD FIRMLY","JUSTIFY A LIFE"],"branches":[{"senses":"01 · 08","en":"THE AIM PUT FORWARD: an intention in the mind and a proposal spoken aloud.","cn":"摆出的目标：心里的意图与说出口的提议。"},{"senses":"02 · 06","en":"THE AIM BUILT IN: one aim settles into a thing's function, another into a body's charter.","cn":"被造进去的目标：一个目标落成物的功能，另一个落成机构的宗旨。"},{"senses":"03","en":"THE AIM HELD TIGHT: resolve is the same aim felt as will.","cn":"被握紧的目标：决心就是同一个目标在意志层面的感受。"},{"senses":"04 · 07","en":"AIMED AND REALIZED: what bears on the matter, and what actually comes of it.","cn":"对准与实现：切中事务的，以及确实做出来的效果。"},{"senses":"05","en":"AIM LARGE ENOUGH FOR A LIFE: the aim becomes a reason to get up.","cn":"大到足够撑起一生的目标：目标变成起床的理由。"}]},"affixes":{"intro":{"en":"Purpose is a French-shaped noun whose Latin prefix and verb are still productive in English, so its parts can be read clearly.","cn":"这个词是法语形态的名词，其拉丁前缀与动词在英语里仍有构成力，因此部件读得很清楚。"},"latinIntro":{"en":"Latin ponere 'to place' gives propose, impose, compose, position and deposit; pro- 'forward' appears in proceed, promote and protect.","cn":"拉丁 ponere「放置」衍生出 propose、impose、compose、position 与 deposit；pro-「向前」见于 proceed、promote 与 protect。"},"items":[{"word":"pro-","structure":"pro- (Latin prefix, 'forward, before')","meaning":"forward; in front","meaningCN":"向前；在前","example":"The prefix puts the aim ahead of the act.","exampleCN":"这个前缀把目标放在行动之前。"},{"word":"ponere","structure":"ponere (Latin verb, 'to put, place')","meaning":"to put; to place","meaningCN":"放；安置","example":"The root supplies the placing.","exampleCN":"这个词根提供「放置」的动作。"},{"word":"proponere","structure":"pro- + ponere","meaning":"to put forward","meaningCN":"摆到前面；提出","example":"The plan was put forward at the meeting.","exampleCN":"计划在会上被提了出来。"},{"word":"purpose","structure":"Old French porpos, from porposer","meaning":"an aim, an intention","meaningCN":"目的；意图","example":"The purpose was written on the first page.","exampleCN":"目的写在了第一页上。"},{"word":"purposeful","structure":"purpose + -ful (full of)","meaning":"full of aim","meaningCN":"充满目的的","example":"A purposeful walk covered the ridge by noon.","exampleCN":"一次有目的的行走在正午前走完了山脊。"},{"word":"purposely","structure":"purpose + -ly (adverb)","meaning":"deliberately","meaningCN":"故意地","example":"She purposely left the door open.","exampleCN":"她故意让门开着。"},{"word":"purposeless","structure":"purpose + -less (without)","meaning":"having no aim","meaningCN":"没有目的的","example":"Purposeless digging ruined the lawn.","exampleCN":"没有目的的挖掘毁了草坪。"},{"word":"purpose-built","structure":"purpose + built (compound)","meaning":"made for one use","meaningCN":"专为某用途建造的","example":"A purpose-built studio replaced the shed.","exampleCN":"一间专用工作室取代了棚屋。"},{"word":"multipurpose","structure":"multi- + purpose","meaning":"serving several uses","meaningCN":"多用途的","example":"A multipurpose hall serves the whole village.","exampleCN":"一座多用途大厅供全村使用。"},{"word":"propose","structure":"pro- + ponere (verb)","meaning":"to put forward","meaningCN":"提出；提议","example":"They proposed a shorter route.","exampleCN":"他们提出了一条更短的路线。"},{"word":"impose","structure":"in- + ponere","meaning":"to place upon","meaningCN":"施加；强加","example":"The court imposed a fine.","exampleCN":"法院处以罚款。"}],"latinEntries":[{"word":"ponere","structure":"ponere, posui, positum (verb, third conjugation)","meaning":"to put, place","meaningCN":"放；安置"},{"word":"proponere","structure":"proponere, proposui, propositum (verb, third conjugation)","meaning":"to put forward","meaningCN":"摆到前面；提出"},{"word":"propositum","structure":"propositum, propositi (n., second declension)","meaning":"a plan, an intention","meaningCN":"计划；意图"},{"word":"positura","structure":"positura, positurae (f., first declension)","meaning":"a placing, position","meaningCN":"放置；位置"}]}},{"word":"purposeful","ipa_uk":"/ˈpɜː.pəs.fəl/","ipa_us":"/ˈpɝː.pəs.fəl/","definition_zh":"有明确目的的；有意为之的；坚定的；有意义的；专为某用途设计的","definition_en":"having a clear aim, and acting or being made in a way that serves it","core_image":"一个人把散在桌上的工具一件件收进对应的格子里，动作不快，但没有一次多余","scene":"她把工具箱的每一格都按用途排好，别人取什么都能立刻找到。A purposeful arrangement of the tools saved the crew an hour each morning.","sceneCN":"这里 purposeful 指「有明确目的、且服务于该目的」（第 1 个义项：目的明确）；句意为把工具按用途排好，每天早上为工班省下一小时。图中可辨识物件：分格的工具箱、按用途归位的扳手、没有多余动作的手、被标出的常用格。","pos":[{"tag":"adj.","zh":"有目的的；有意为之的；坚定的；有意义的"}],"collocations":[{"phrase":"a purposeful walk","zh":"有目的的行走"},{"phrase":"purposeful activity","zh":"有目的的活动"},{"phrase":"a purposeful life","zh":"有意义的人生"},{"phrase":"purposeful design","zh":"有明确用途的设计"},{"phrase":"purposeful silence","zh":"有意保持的沉默"},{"phrase":"purposeful use of time","zh":"有目的地利用时间"}],"forms":[{"label":"原级","form":"purposeful"},{"label":"比较级","form":"more purposeful"},{"label":"最高级","form":"most purposeful"},{"label":"副词","form":"purposefully"},{"label":"名词（有目的性）","form":"purposefulness"},{"label":"否定式","form":"purposeless"}],"derivatives":[{"word":"purposefully","pos":"adv.","zh":"在形容词后加副词后缀构成，语义由「有目的的」转为「有目的地」"},{"word":"purposefulness","pos":"n.","zh":"在形容词后加名词后缀构成，语义由「有目的的」转为「有目的性这一特质」"},{"word":"purposeless","pos":"adj.","zh":"把表示「充满」的后缀换成表示「缺少」的后缀，语义由「有目的」转为「无目的」"},{"word":"purpose","pos":"n.","zh":"基础名词，语义为「目的」，是本形容词的构词起点"}],"senses":[{"no":"01","title":"Having a clear aim","titleCN":"带着明确的目标","definition":"acting or existing with a definite aim that guides every step","definitionCN":"带着一个明确目标去行动或存在，每一步都受它引导","example":"A purposeful arrangement of the tools saved the crew an hour each morning.","exampleCN":"把工具按用途排好，每天早上为工班省下一小时。","why":"the suffix means full of, so a purposeful act is full of an aim rather than merely busy.","whyCN":"后缀意为「充满」，因此一个有目的的行为是被目标填满的，而不是仅仅忙碌。"},{"no":"02","title":"Done on purpose","titleCN":"有意为之，而非碰巧","definition":"deliberately done, so that the result was intended rather than accidental","definitionCN":"有意做出，因此结果是想要的，而不是碰巧的","example":"The gap in the wall was purposeful: it lets the cat through.","exampleCN":"墙上那道缝是有意留的，好让猫通过。","why":"an aim that is fully present in the act makes the act deliberate, and the word marks that intent.","whyCN":"目标完整地存在于行为中，这个行为就是有意的，这个词正是标出这份意图。"},{"no":"03","title":"Firm in carrying out","titleCN":"执行时意志坚定","definition":"showing steady resolution in the way an action is carried through","definitionCN":"在完成行动的方式上显出稳定的决心","example":"Her purposeful stride told the others the decision was final.","exampleCN":"她那坚定的步伐让众人知道决定已不可更改。","why":"an aim held without wavering shows in the body before it shows in argument.","whyCN":"一个不摇动的目标，会先显现在身体上，而不是先显现在论证里。"},{"no":"04","title":"Having genuine meaning","titleCN":"确实有意义的","definition":"filled with a point that makes the effort worth making, said of work or a life","definitionCN":"被一个使付出值得的意义所填满，用于工作或人生","example":"The years in the clinic were the most purposeful of his life.","exampleCN":"在诊所的那些年是他一生中最有意义的时光。","why":"when the aim is large, the word stops describing acts and starts describing a whole stretch of life.","whyCN":"当目标足够大，这个词就不再描述行为，而开始描述一整段人生。"},{"no":"05","title":"Made for one use","titleCN":"为某一用途而造","definition":"designed with a specific job in view, so that nothing is ornamental","definitionCN":"带着一项具体功能来设计，因此没有多余的装饰","example":"The bench was purposeful: low, wide and easy to clean.","exampleCN":"这条长凳是为用途而造的：低、宽、好清理。","why":"an aim can be built into an object, where it appears as the absence of decoration.","whyCN":"目标可以被造进一件物品里，在那里它显现为「没有装饰」。"},{"no":"06","title":"Focused rather than scattered","titleCN":"专注而不散乱","definition":"concentrated on the aim at hand instead of drifting among tasks","definitionCN":"集中在眼前的目标上，而不是在任务之间漂移","example":"A purposeful half hour beat a distracted afternoon.","exampleCN":"有目的的半小时胜过一个心不在焉的下午。","why":"the same filled aim shows as economy of motion, which is why the word often modifies time and work.","whyCN":"同一份被填满的目标会显现为动作的节省，因此这个词常修饰时间与工作。"},{"no":"07","title":"Read as having a hidden intent","titleCN":"可被读作另有意图","definition":"appearing to carry an intention beyond what is said, as of a glance or a pause","definitionCN":"看起来带着话语之外的另一层意图，用于眼神或停顿","example":"There was a purposeful pause before she answered.","exampleCN":"她回答之前有一个像是别有用意的停顿。","why":"observers read intent into small signs, and the word then describes what others infer rather than what was meant.","whyCN":"观察者会从小动作里读出意图，此时这个词描述的是别人推断出的东西，而不是本人所想的。"},{"no":"08","title":"Serving the aim without waste","titleCN":"为达成目的而不浪费","definition":"using only what the aim requires, with no surplus effort or material","definitionCN":"只用达成目的所必需的部分，不多费一点力气或材料","example":"The pruning was purposeful, and the tree carried more fruit the next year.","exampleCN":"那次修剪是有目的的，第二年树上的果子更多了。","why":"a fully present aim trims away whatever does not serve it, which is the practical face of the word.","whyCN":"一个完整在场的目标会把不服务于它的部分剪掉，这是这个词在实践上的面孔。"}],"etymology":{"intro":{"en":"Purposeful is purpose plus the Old English suffix -ful 'full of'. Purpose itself comes through Old French porpos from Latin proponere 'to put forward'. Dates are approximate.","cn":"purposeful 是名词 purpose 加上古英语后缀 -ful「充满」。purpose 本身经古法语 porpos 来自拉丁 proponere「放到前面」。年代均为约数。"},"items":[{"era":"OLD ENGLISH -FUL","en":"The suffix -ful meant 'full of, having the quality of', and it turned nouns into adjectives such as careful and useful.","cn":"后缀 -ful 意为「充满、具有……性质」，它把名词变成形容词，如 careful 与 useful。"},{"era":"OLD FRENCH PORPOS","en":"The noun entered English meaning an aim or intention put before the mind, from the verb for putting something forward.","cn":"这个名词进入英语时指摆在心头的目标或意图，其动词意为「把某物摆到前面」。"},{"era":"NINETEENTH CENTURY","en":"The adjective purposeful appears in the nineteenth century, when purposeful activity became a favourite phrase of educators and reformers.","cn":"这个形容词在十九世纪出现，当时「有目的的活动」成了教育者与改革者爱用的说法。"},{"era":"DESIGN USE","en":"Twentieth-century writing applied it to buildings and objects, where an aim shows as the absence of anything ornamental.","cn":"二十世纪的写作把它用于建筑与器物，那里目标显现为「没有多余装饰」。"},{"era":"MORAL USE","en":"The phrase a purposeful life treats an aim large enough to organize a lifetime as a virtue in itself.","cn":"「有意义的人生」这一说法，把一个大到能组织一生的目标本身当作一种德性。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (exact first date of the adjective): no citation fixes its first use for designed objects, and the dating of its moral use rests on printed sources only.","cn":"来源不确定（形容词确切的最早年代）：它首次用于器物设计没有确切书证；道德用法的年代只能依据留存印刷材料推断。"}]},"similar":{"note":{"en":"Group one separates look-alikes from the same purpose family; group two separates adjectives that praise directed activity.","cn":"第一组区分同属 purpose 词族的形近词；第二组按赞美「有方向的活动」的方式区分形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"purposely","ipa":"/ˈpɜːpəsli/","tag":"adverb, not adjective","definition":"The adverb meaning deliberately; it modifies the act rather than describing the actor.","definitionCN":"意为「故意地」的副词；修饰行为，而不是描述行为者。"},{"word":"purposeless","ipa":"/ˈpɜːpəsləs/","tag":"the negation","definition":"Without any aim, drifting; it is the direct opposite and carries a mild reproach.","definitionCN":"毫无目标、漂着；是直接的反面，带轻微责备。"},{"word":"purpose-built","ipa":"/ˌpɜːpəsˈbɪlt/","tag":"compound for buildings","definition":"Built specifically for one use; it narrows the design sense to construction.","definitionCN":"专为某一用途建造的；把设计义收窄到建筑。"},{"word":"purport","ipa":"/pəˈpɔːt/","tag":"different root","definition":"From a verb meaning to carry: to claim or seem to mean, which is a matter of appearance rather than aim.","definitionCN":"出自一个意为「搬运」的动词：声称或看似意指，说的是表象而非目标。"},{"word":"propose","ipa":"/prəˈpəʊz/","tag":"same root, different word","definition":"To put a plan forward; same Latin verb as purpose but no suffix of fullness.","definitionCN":"把计划摆出来；与 purpose 同出那个拉丁动词，但不带「充满」的后缀。"}]},{"heading":"NEAR MEANING","entries":[{"word":"deliberate","ipa":"/dɪˈlɪbərət/","tag":"chosen on purpose","definition":"Done consciously and after weighing; it stresses the choice, while purposeful stresses the aim.","definitionCN":"有意识、经过权衡后做出的；强调选择，而 purposeful 强调目标。"},{"word":"resolute","ipa":"/ˈrezəluːt/","tag":"unwavering will","definition":"Firm and not wavering in purpose; it describes the will rather than the aim's clarity.","definitionCN":"目标坚定、毫不动摇；描述意志，而不是目标的清晰。"},{"word":"meaningful","ipa":"/ˈmiːnɪŋfəl/","tag":"carries significance","definition":"Having significance or value; it is the inner, felt side of what purposeful describes outwardly.","definitionCN":"具有意义或价值；是 purposeful 在外在描述之下的内在感受面。"},{"word":"focused","ipa":"/ˈfəʊkəst/","tag":"attention narrowed","definition":"With attention concentrated on one thing; it describes attention, not the aim that directs it.","definitionCN":"注意力集中在一处；描述注意力，而不是引导它的目标。"},{"word":"systematic","ipa":"/ˌsɪstəˈmætɪk/","tag":"method, not aim","definition":"Done according to a method or system; it can be systematic without any clear purpose.","definitionCN":"按方法或体系来做；可以很有体系却毫无明确目的。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The suffix means full of, so a purposeful act is full of its aim rather than full of motion.","cn":"后缀意为「充满」，因此有目的的行为是被目标填满，而不是被动作填满。"},{"en":"The family runs purpose, purposeful, purposefully, purposefulness, purposeless.","cn":"同族词覆盖名词、形容词、副词、抽象名词与否定式。"},{"en":"Fixed phrases mark the fields: a purposeful walk, purposeful design, purposeful use of time.","cn":"固定搭配标出领域：有目的的行走、有明确用途的设计、有目的地利用时间。"},{"en":"The design sense shows as what is missing: a purposeful bench has no ornament at all.","cn":"设计义显现为「缺了什么」：一条为用途而造的凳子，一点装饰也没有。"},{"en":"The moral sense appears in a purposeful life, where the aim is large enough to organize years.","cn":"道德义出现在「有意义的人生」里，那里目标大到足以组织许多年。"}],"abstract":[{"en":"Picture a chisel laid down the moment the joint is finished.","cn":"想象接缝一做完，凿子立刻被放下。"},{"en":"Picture a route on a map with no loop and no detour.","cn":"想象地图上一条没有回环、没有绕行的路线。"},{"en":"Picture a lamp aimed at one desk while the rest of the room stays dark.","cn":"想象一盏灯只照一张桌子，其余房间仍是暗的。"}]},"examples":[{"en":"The workshop ran on purposeful practice, not on repetition for its own sake.","cn":"这间工坊靠的是有目的的练习，而不是为重复而重复。"},{"en":"Her purposeful editing cut the report by half.","cn":"她那番有目的的编辑把报告删掉了一半。"},{"en":"A purposeful silence followed the question, and then he answered.","cn":"问题之后是一段别有用意的沉默，然后他才回答。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"purpose（目的）+ full（满）——被目的装满的 → 有目的的","word":"purposeful"},"root":"purpose（古法语 porpos「目标」← 拉丁 proponere「放到前面」= pro- + ponere）+ 古英语后缀 -ful「充满」。","sensesIntro":{"en":"Eight senses follow one measure: an aim fills an act, a thing, a stretch of life or a silence, and the adjective reports how completely that aim is present.","cn":"八个义项沿同一把尺展开：一个目标填满一个行为、一件物、一段人生或一段沉默，这个形容词报告那个目标在场得有多完整。"},"semanticMap":{"core":{"en":"CORE IMAGE: tools sorted into labelled compartments with no wasted motion.","cn":"核心意象：工具被分进标好用途的格子，没有一个多余动作。"},"chain":["SET THE AIM","FILL THE ACT","SHOW IN MANNER","BUILD IT IN","ORGANIZE TIME","MAKE IT MEAN"],"branches":[{"senses":"01 · 02","en":"THE AIM PRESENT: what is done with an aim is also what is done deliberately.","cn":"在场的目标：带着目标做的，也就是有意做的。"},{"senses":"03","en":"THE AIM FELT AS WILL: steadiness of stride before any argument.","cn":"目标在意志上被感到：在论证之前，先是步伐的稳定。"},{"senses":"05 · 08","en":"THE AIM BUILT IN: a bench with no ornament and a pruning with no waste.","cn":"被造进去的目标：一条无装饰的长凳，一次不浪费的修剪。"},{"senses":"06","en":"THE AIM ORGANIZING TIME: half an hour aimed beats an afternoon adrift.","cn":"组织时间的目标：有方向的半小时胜过漂着的下午。"},{"senses":"04 · 07","en":"THE AIM READ TWICE: by the person as meaning, by others as a hidden intent.","cn":"被读两次的目标：本人读作意义，旁人读作别有用意。"}]},"affixes":{"intro":{"en":"The word is a borrowed noun plus a native suffix, so one half is Latin in origin and the other is English.","cn":"这个词是一个借入的名词加一个本族后缀，一半源自拉丁，一半是英语。"},"latinIntro":{"en":"Latin ponere 'to place' gives propose, compose and position; the native suffix -ful also builds useful, careful and hopeful.","cn":"拉丁 ponere「放置」衍生出 propose、compose 与 position；本族后缀 -ful 还构成 useful、careful 与 hopeful。"},"items":[{"word":"-ful","structure":"-ful (Old English suffix, 'full of')","meaning":"full of; having the quality of","meaningCN":"充满；具有……性质","example":"A useful map folds into a pocket.","exampleCN":"一张实用的地图能折进口袋。"},{"word":"purpose","structure":"Old French porpos, from Latin proponere","meaning":"an aim","meaningCN":"目的","example":"The purpose was stated in one line.","exampleCN":"目的用一行就写清了。"},{"word":"purposeful","structure":"purpose + -ful","meaning":"full of aim","meaningCN":"充满目标的","example":"The walk was purposeful and short.","exampleCN":"那次行走有明确目的，而且很短。"},{"word":"purposefully","structure":"purposeful + -ly (adverb)","meaning":"with a clear aim","meaningCN":"有目的地","example":"She purposefully chose the longer route.","exampleCN":"她有意选了更长的那条路。"},{"word":"purposefulness","structure":"purposeful + -ness (quality)","meaning":"the quality of having an aim","meaningCN":"有目的性这一特质","example":"The plan's purposefulness impressed the board.","exampleCN":"这份计划的目的性打动了董事会。"},{"word":"purposeless","structure":"purpose + -less (without)","meaning":"without aim","meaningCN":"无目的的","example":"Purposeless motion tired the children.","exampleCN":"无目的的跑动让孩子累了。"},{"word":"purpose-built","structure":"purpose + built (compound)","meaning":"built for one use","meaningCN":"专为某用途建造的","example":"A purpose-built shed held the grain.","exampleCN":"一间专用棚屋存粮。"},{"word":"multipurpose","structure":"multi- + purpose","meaning":"serving several aims","meaningCN":"多用途的","example":"A multipurpose room serves as both hall and clinic.","exampleCN":"一间多用途房既是会场也是诊所。"},{"word":"propose","structure":"pro- + ponere","meaning":"to put forward","meaningCN":"提出","example":"They proposed a simpler design.","exampleCN":"他们提出了一个更简的设计。"},{"word":"position","structure":"ponere + -tion","meaning":"a placing, a stand","meaningCN":"位置；立场","example":"The position was marked with a stake.","exampleCN":"位置用木桩标了出来。"}],"latinEntries":[{"word":"ponere","structure":"ponere, posui, positum (verb, third conjugation)","meaning":"to put, place","meaningCN":"放；安置"},{"word":"proponere","structure":"proponere, proposui, propositum (verb, third conjugation)","meaning":"to put forward","meaningCN":"摆到前面；提出"},{"word":"propositum","structure":"propositum, propositi (n., second declension)","meaning":"a plan, an aim","meaningCN":"计划；目的"}]}},{"word":"satisfaction","ipa_uk":"/ˌsæt.ɪsˈfæk.ʃən/","ipa_us":"/ˌsæt̬.ɪsˈfæk.ʃən/","definition_zh":"满意；满足感；令人满意的事物；赔偿；义务的履行；赎补","definition_en":"the feeling of pleasure that comes when a need or wish has been met","core_image":"碗里的饭刚好盛到碗沿，不多一勺也不少一勺，吃饭的人放下筷子","scene":"活儿干完那天，工头绕着修好的屋顶走了一圈，摸了摸檐口，没有再多说什么。He looked over the finished roof with quiet satisfaction and put the ladder away.","sceneCN":"这里 satisfaction 指「需求被满足后产生的满意」（第 1 个义项：满足感）；句意为他不声不响地带着满意看了一遍修好的屋顶，然后把梯子收了起来。图中可辨识物件：盛到碗沿的饭、放下的筷子、走完一圈的屋顶、收回的梯子。","pos":[{"tag":"n.","zh":"满意；满足；乐事；赔偿；履行；（神学）补赎"}],"collocations":[{"phrase":"a sense of satisfaction","zh":"满足感"},{"phrase":"express satisfaction","zh":"表示满意"},{"phrase":"to one's satisfaction","zh":"令某人满意地"},{"phrase":"job satisfaction","zh":"工作满意度"},{"phrase":"satisfaction with","zh":"对……的满意"},{"phrase":"in satisfaction of","zh":"作为对……的清偿"},{"phrase":"customer satisfaction","zh":"顾客满意度"}],"forms":[{"label":"单数","form":"satisfaction"},{"label":"复数","form":"satisfactions"},{"label":"动词","form":"satisfy"},{"label":"动词三单","form":"satisfies"},{"label":"动词过去式","form":"satisfied"},{"label":"形容词","form":"satisfactory"},{"label":"形容词（感到满意的）","form":"satisfied"}],"derivatives":[{"word":"satisfy","pos":"v.","zh":"基础动词，来自拉丁语「做够」，语义为「使满足、使满意」"},{"word":"satisfied","pos":"adj.","zh":"由过去分词转为形容词，语义由「已被满足」转为「感到满意的」"},{"word":"satisfactory","pos":"adj.","zh":"由动词加表示性质的形容词后缀构成，语义由「满足要求」转为「达到要求的」"},{"word":"satisfactorily","pos":"adv.","zh":"在形容词后加副词后缀构成，语义由「达到要求的」转为「以达标方式」"},{"word":"dissatisfaction","pos":"n.","zh":"加否定前缀构成，语义由「满意」转为「不满」"},{"word":"unsatisfied","pos":"adj.","zh":"加否定前缀构成，语义由「已满足」转为「未获满足的」"}],"senses":[{"no":"01","title":"Pleasure at a wish being met","titleCN":"愿望被满足时的愉快感","definition":"the pleasant feeling that comes when something one wanted has been granted or achieved","definitionCN":"想要的事被给予或达成时产生的愉快感受","example":"He looked over the finished roof with quiet satisfaction and put the ladder away.","exampleCN":"他不声不响地带着满意看了一遍修好的屋顶，然后把梯子收起来。","why":"the Latin verb means to make enough, so satisfaction is the feeling of having received enough.","whyCN":"那个拉丁动词意为「做够」，因此满足感就是「已经得到足够」的感受。"},{"no":"02","title":"Approval of something","titleCN":"对某事物的认可与满意","definition":"the judgement that a thing or a performance is acceptable or good","definitionCN":"认为某件东西或某次表现可以接受或很好的判断","example":"The inspector expressed satisfaction with the new wiring.","exampleCN":"检查员对新布线表示满意。","why":"an aim held by an evaluator is met, and the same word names that verdict as well as the warmer feeling.","whyCN":"评判者心里那把尺子被满足，这个词既指那份判决，也指更温热的那种感受。"},{"no":"03","title":"Compensation for a loss","titleCN":"对损失所作的补偿","definition":"something given to make good a loss or an injury, especially in law","definitionCN":"为弥补损失或伤害而给出之物，尤用于法律","example":"The court ordered satisfaction of the claim within ninety days.","exampleCN":"法院命令在九十天内对该项请求作出清偿。","why":"a debt or a wrong must be made enough, and paying it is literally making up the shortfall.","whyCN":"债或亏欠必须被「做够」，偿付就是在字面意义上把缺口补上。"},{"no":"04","title":"Fulfilment of an obligation","titleCN":"义务或债务的履行完毕","definition":"the carrying out of a duty, a promise or a debt to the full","definitionCN":"把义务、承诺或债务完整地执行到底","example":"Satisfaction of the mortgage freed the farm from the bank.","exampleCN":"房贷清偿之后，农场从银行手里解脱出来。","why":"the same making-enough is applied to obligations, where the shortfall is legal rather than emotional.","whyCN":"同一个「做够」被用到义务上，那里的缺口是法律性的，而不是情感性的。"},{"no":"05","title":"A thing that gives pleasure","titleCN":"一件令人感到满足的事","definition":"an event or fact that brings quiet pleasure when one thinks of it","definitionCN":"想起来就带来安静愉快的一件事或一个事实","example":"It was a satisfaction to find every tool back in its place.","exampleCN":"发现每件工具都回到原位，是一件令人满足的事。","why":"because the word is countable, one particular fulfilled wish can be pointed at as a satisfaction.","whyCN":"因为这个词可数，某一个被满足的愿望就可以被指认为一件「欣慰之事」。"},{"no":"06","title":"A need fully met","titleCN":"需求被填满的状态","definition":"the state in which a need or a demand has been met and nothing more is required","definitionCN":"某种需要或要求已被满足、不再缺任何东西的状态","example":"The satisfaction of demand ended the rationing.","exampleCN":"需求被满足之后，配给制结束了。","why":"the neutral sense is about quantity rather than mood: enough has been supplied, so the gap is closed.","whyCN":"这条中性义关乎数量而非心情：供给已经足够，缺口就合上了。"},{"no":"07","title":"Smug self-approval","titleCN":"自满、自得","definition":"a complacent pleasure in one's own condition, often blind to what is missing","definitionCN":"对自身处境的自得之乐，常常看不见还缺什么","example":"His satisfaction with the first draft kept him from reading it again.","exampleCN":"他对初稿的自满让他不肯再读一遍。","why":"the same feeling turned inward can harden into complacency, and the word then carries a mild criticism.","whyCN":"同一种感受转向自己，就会硬化成自满，此时这个词带轻微批评。"},{"no":"08","title":"Atonement in theology","titleCN":"神学意义上的补赎","definition":"in traditional Catholic teaching, an act by which the temporal penalty of sin is made good","definitionCN":"在天主教传统教导中，为补足罪的暂罚而做的一种行为","example":"The old prayer book lists fasting as a work of satisfaction.","exampleCN":"那本旧祈祷书把斋戒列为一种补赎行为。","why":"the technical sense keeps the legal layer: what is owed must be made enough before the account closes.","whyCN":"这个术语保留了法律层：所欠的必须先被补够，账目才能结清。"}],"etymology":{"intro":{"en":"Satisfaction comes from Latin satisfactio, from satisfacere 'to satisfy', built on satis 'enough' and facere 'to make, to do'. The deeper origin of satis is not settled. Dates are approximate.","cn":"该词来自拉丁 satisfactio，其动词 satisfacere「使满足」由 satis「足够」与 facere「做、造」构成。satis 的更深来源尚无定论，年代均为约数。"},"items":[{"era":"LATIN SATIS","en":"Satis meant 'enough, sufficiently'. Its deeper origin is uncertain; the comparison with a root meaning 'to fill' is a hypothesis rather than a demonstrated derivation.","cn":"satis 意为「足够、充足」。其更深来源不确定；把它与表示「填满」的词根相比对，只是假说，并非已证实的派生。"},{"era":"LATIN FACERE","en":"Facere meant 'to make, do'. It is one of the most productive verbs in Latin and supplies the second half of many English words.","cn":"facere 意为「做、造」。它是拉丁语中构词力最强的动词之一，为许多英语词提供了后半部分。"},{"era":"LATIN SATISFACERE","en":"Satis plus facere gave satisfacere 'to make enough, to give full measure', used first of paying a debt and answering a charge.","cn":"satis 加 facere 构成 satisfacere「做够、给足分量」，最早用于清偿债务与回应指控。"},{"era":"LATIN SATISFACTIO","en":"The noun satisfactio named the making-enough, and it carried both the legal and the emotional senses into later usage.","cn":"名词 satisfactio 指「做够」这件事，并把法律义与情感义一同带入后世用法。"},{"era":"OLD FRENCH","en":"Old French satisfaccion brought the word into English in the fourteenth century, where theology used it for the making good of sin's penalty.","cn":"古法语 satisfaccion 在十四世纪把这个词带入英语，神学用它指补足罪罚。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin of satis and the dating of the emotional sense): no citation fixes when the word became a feeling rather than a settlement, and any Indo-European form offered for satis is a reconstruction.","cn":"来源不确定（satis 的更深来源与情感义的确切年代）：没有书证能定住这个词何时从「结清」变成「一种感受」；凡为 satis 给出的印欧语形式均属重构形式。"}]},"similar":{"note":{"en":"Group one separates look-alikes that share the making verb or the enough-word but split into different meanings; group two separates kinds of pleased feeling.","cn":"第一组区分同出「做」这个动词或同出「足够」一词、却分向不同意义的形近词；第二组区分不同类型的愉快感受。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"satisfactory","ipa":"/ˌsætɪsˈfæktəri/","tag":"meets the standard","definition":"Good enough to meet a requirement; it judges the thing, not the person's feeling.","definitionCN":"足以达到要求；评判的是事物，而不是人的感受。"},{"word":"satiate","ipa":"/ˈsæʃieɪt/","tag":"shares the enough-word","definition":"To fill someone past the point of wanting more; it often implies excess rather than contentment.","definitionCN":"把某人填到不想再要；常含过量之意，而非知足。"},{"word":"satiety","ipa":"/səˈtaɪəti/","tag":"the state of full","definition":"The state of being fully fed or fully supplied, often to the point of weariness.","definitionCN":"被喂饱或供给充足的状态，常到厌倦的程度。"},{"word":"asset","ipa":"/ˈæset/","tag":"same enough-word, other path","definition":"From Old French asez 'enough', from the same enough-word: property that is enough to settle debts, hence anything of value.","definitionCN":"来自古法语 asez「足够」，同出那个「足够」词：足以抵债的财产，因而指任何有价值之物。"},{"word":"suffice","ipa":"/səˈfaɪs/","tag":"different first element","definition":"Sub- 'under' plus facere: to supply what is needed from below, meaning to be enough but not to please.","definitionCN":"由 sub-「在下」加 facere 构成：从下面补上所需，意为「够用」，但不含「使满意」。"},{"word":"sacrifice","ipa":"/ˈsækrɪfaɪs/","tag":"different first element","definition":"Sacer 'holy' plus facere: to make something holy, hence to give up something precious.","definitionCN":"由 sacer「神圣」加 facere 构成：使某物成圣，因而指献出珍贵之物。"}]},{"heading":"NEAR MEANING","entries":[{"word":"contentment","ipa":"/kənˈtentmənt/","tag":"settled and quiet","definition":"A steady, quiet acceptance of what one has; it is a lasting mood rather than a response to one event.","definitionCN":"对已有之物稳定而安静的接受；是持久心境，而非对某件事的反应。"},{"word":"fulfilment","ipa":"/fʊlˈfɪlmənt/","tag":"potential realized","definition":"The realizing of one's abilities or of a promise; it looks at what was brought into being.","definitionCN":"能力或承诺被实现；看的是被成就出来的东西。"},{"word":"pleasure","ipa":"/ˈpleʒə/","tag":"plain enjoyment","definition":"Enjoyment of any kind, including sensory delight; satisfaction is narrower and tied to a need met.","definitionCN":"任何形式的享受，包括感官之乐；satisfaction 更窄，且与「需求被满足」绑定。"},{"word":"gratification","ipa":"/ˌɡrætɪfɪˈkeɪʃən/","tag":"indulged wish","definition":"The pleasure of having a desire indulged; it often suggests something a little less necessary.","definitionCN":"欲望被纵容而得的快感；常暗示这欲望并不那么必要。"},{"word":"complacency","ipa":"/kəmˈpleɪsənsi/","tag":"self-satisfaction as a fault","definition":"Smug ease with oneself that ignores risks; it is the criticism that satisfaction can slide into.","definitionCN":"对自身状况自满而忽视风险；正是 satisfaction 可能滑向的那种批评。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Satis 'enough' plus facere 'to make': satisfaction is literally the making of enough.","cn":"satis「足够」加 facere「做」：满足在字面上就是「把够做出来」。"},{"en":"The family runs satisfy, satisfied, satisfactory, satisfactorily, satisfaction, dissatisfaction.","cn":"同族词覆盖动词、两个形容词、副词、名词与否定式。"},{"en":"Fixed phrases mark the fields: a sense of satisfaction, job satisfaction, customer satisfaction.","cn":"固定搭配标出领域：满足感、工作满意度、顾客满意度。"},{"en":"The legal layer survives in phrases about satisfying a claim or a debt, where the gap is money.","cn":"法律层保存在「清偿请求」或「清偿债务」这类说法里，那里的缺口是钱。"},{"en":"The look-alike suffice uses a different first element, so it means enough to serve without pleasing anyone.","cn":"形近的 suffice 用了不同的前半部分，所以它是「够用」，并不使人满意。"}],"abstract":[{"en":"Picture a bowl filled exactly to the rim, with the chopsticks laid down beside it.","cn":"想象一只碗刚好盛到碗沿，筷子放在旁边。"},{"en":"Picture a ledger closed on the last page with the two columns equal.","cn":"想象一本账在最后一页合上，两栏数字相等。"},{"en":"Picture a ladder put away in its hook because the roof is finished.","cn":"想象屋顶修完了，梯子被挂回钩子上。"}]},"examples":[{"en":"The volunteers worked without pay and spoke of deep satisfaction afterward.","cn":"志愿者们不计报酬地干活，事后说起了深深的满足感。"},{"en":"Satisfaction of the debt took the family eleven years.","cn":"清偿这笔债，这家人用了十一年。"},{"en":"The board reviewed the results to its own satisfaction.","cn":"董事会审阅结果，审得自己满意为止。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"satis（够）+ fact（做）——做到「够」为止 → 满意","word":"satisfaction"},"root":"拉丁 satisfactio ← satisfacere「做够、给足分量」= satis（足够）+ facere（做、造）；satis 更深来源不确定。","sensesIntro":{"en":"Eight senses follow one measure: enough is made, and the same enough is felt as a warm mood, heard as a verdict, paid as a debt, applied to a promise, pointed at as one glad fact, read as a closed gap, turned into smugness and finally counted as an act that settles an account.","cn":"八个义项沿同一把尺展开：先「做出足够」，这份足够再依次被感受为暖意、被说出为判决、被付作清偿、被落到承诺上、被指为一件欣慰之事、被读成一个合上的缺口、被转成自满，最后被算作一次结清账目的行为。"},"semanticMap":{"core":{"en":"CORE IMAGE: a bowl filled exactly to the rim, with the chopsticks laid down.","cn":"核心意象：一碗正好盛到碗沿，筷子已放下。"},"chain":["MAKE ENOUGH","FEEL ENOUGH","SAY IT IS ENOUGH","PAY WHAT IS OWED","KEEP A PROMISE","CLOSE THE ACCOUNT"],"branches":[{"senses":"01 · 05","en":"THE WARMTH: one fulfilled wish felt as pleasure, and a single glad fact pointed at.","cn":"暖意：一个被满足的愿望化成的愉快，以及被指认出来的一件欣慰事。"},{"senses":"02 · 06","en":"THE VERDICT ON A GAP: a thing judged acceptable, and a demand judged fully supplied.","cn":"对缺口的判决：某物被判为可以接受，某项需求被判为已足量供给。"},{"senses":"03 · 04","en":"THE DEBT MADE GOOD: money paid and a promise carried out are the same shortfall closed.","cn":"被补足的债：付出去的钱与履行的承诺，是同一道缺口被合上。"},{"senses":"07","en":"THE FEELING TURNED INWARD: the same warmth, seen from outside, becomes smugness.","cn":"转向内部的感受：同一份暖意，从外面看就成了自满。"},{"senses":"08","en":"THE ACCOUNT SETTLED: theology keeps the ledger and speaks of making the penalty good.","cn":"被结清的账：神学保留着这本账簿，说的是把刑罚补足。"}]},"affixes":{"intro":{"en":"Satisfaction is a Latin noun on a verb made of an adverb-like first element and a very common verb, and that verb still builds many English words.","cn":"这个词是一个拉丁名词，其动词由一个类似副词成分与一个极常见的动词构成，那个动词至今仍构成许多英语词。"},"latinIntro":{"en":"Latin facere 'to make' gives fact, effect, office, difficult and manufacture; satis appears in satiate and satiety, and in the French-shaped asset.","cn":"拉丁 facere「做」衍生出 fact、effect、office、difficult 与 manufacture；satis 见于 satiate、satiety，以及法语形态的 asset。"},"items":[{"word":"satis","structure":"satis (Latin adverb, 'enough')","meaning":"enough","meaningCN":"足够","example":"The measure was enough for the whole week.","exampleCN":"这些分量够用整整一周。"},{"word":"facere","structure":"facere (Latin verb, 'to make, do')","meaning":"to make; to do","meaningCN":"做；造","example":"The root supplies the making.","exampleCN":"这个词根提供「做」的意思。"},{"word":"satisfacere","structure":"satis + facere","meaning":"to make enough, to give full measure","meaningCN":"做够；给足分量","example":"The payment made the account whole.","exampleCN":"这笔付款使账目完整。"},{"word":"satisfactio","structure":"satisfacere + -tio (noun of action)","meaning":"a making enough, a settlement","meaningCN":"补足；结清","example":"The settlement closed the case.","exampleCN":"这次结清使案子了结。"},{"word":"satisfaction","structure":"satisfactio passing into French and English","meaning":"contentment, settlement","meaningCN":"满意；清偿","example":"The crew felt satisfaction at the finish.","exampleCN":"完工时工人们感到满意。"},{"word":"satisfy","structure":"satis + facere (English verb)","meaning":"to meet a need or a demand","meaningCN":"使满足；满足要求","example":"The answer satisfied the examiner.","exampleCN":"这个回答让考官满意。"},{"word":"satisfied","structure":"satisfy + -ed (participle as adjective)","meaning":"having the need met","meaningCN":"已获满足的","example":"The client left satisfied.","exampleCN":"客户满意地离开了。"},{"word":"satisfactory","structure":"satisfy + -ory (adjective of function)","meaning":"good enough to meet a standard","meaningCN":"达到要求的","example":"The repairs were judged satisfactory.","exampleCN":"修缮被判定为合格。"},{"word":"dissatisfaction","structure":"dis- + satisfaction","meaning":"the state of not being met","meaningCN":"不满","example":"Dissatisfaction with the schedule grew.","exampleCN":"对日程的不满逐渐增长。"},{"word":"unsatisfied","structure":"un- + satisfied","meaning":"still lacking what was needed","meaningCN":"未获满足的","example":"An unsatisfied demand kept prices high.","exampleCN":"未获满足的需求使价格居高不下。"},{"word":"satiate","structure":"satis + -ate (verb)","meaning":"to fill past desire","meaningCN":"使餍足","example":"Too much sweet food satiated the children.","exampleCN":"太多甜食让孩子们吃腻了。"},{"word":"suffice","structure":"sub- + facere","meaning":"to be enough for a purpose","meaningCN":"够用","example":"One lantern sufficed for the shed.","exampleCN":"一盏灯对棚屋来说够用了。"}],"latinEntries":[{"word":"satis","structure":"satis (adverb and indeclinable noun, 'enough')","meaning":"enough, sufficiently","meaningCN":"足够；充足"},{"word":"facere","structure":"facere, feci, factum (verb, third conjugation)","meaning":"to make, do","meaningCN":"做；造"},{"word":"satisfacere","structure":"satisfacere, satisfeci, satisfactum (verb, third conjugation)","meaning":"to make enough, satisfy","meaningCN":"做够；使满足"},{"word":"satisfactio","structure":"satisfactio, satisfactionis (f., third declension)","meaning":"a making enough, a settlement","meaningCN":"补足；清偿"}]}}]);
